   character(len=4), parameter :: PB(28) = [character(len=4) :: 'row', 'tral', 'me', 'dan', &
      'the', 'ath', 'is', 'en', 'wyn', 'mark', 'dor', 'esh', 'ion', 'mere', 'ay', 'orn', &
      'gar', 'ith', 'ova', 'ane', 'ul', 'ost', 'em', 'ard', 'ence', 'ys', 'oth', 'ach']
   character(len=4), parameter :: RA(24) = [character(len=4) :: 'Os', 'Vash', 'Mir', 'Kar', &
      'Ul', 'Ser', 'Thal', 'Bel', 'Dor', 'Ash', 'Ken', 'Lys', 'Mor', 'Nar', 'Per', 'Quel', &
      'Rhu', 'Sab', 'Tir', 'Var', 'Zer', 'Hel', 'Gor', 'Ith']
   character(len=4), parameter :: RB(24) = [character(len=4) :: 'tral', 'ti', 'row', 'ath', &
      'en', 'ia', 'os', 'mar', 'und', 'esh', 'ane', 'or', 'ova', 'eth', 'is', 'ad', 'ion', &
      'yr', 'enn', 'ak', 'ul', 'ara', 'oth', 'ica']
   character(len=4), parameter :: PST(36) = [character(len=4) :: 'Am', 'Is', 'Ves', 'Cor', &
      'Ul', 'Ther', 'Mal', 'Kas', 'Ser', 'Or', 'Ten', 'Bel', 'Dav', 'Har', 'Ly', 'Ny', 'Os', &
      'Per', 'Ras', 'Sav', 'Tam', 'Var', 'Zen', 'El', 'Ar', 'Iv', 'Gal', 'Mer', 'Tor', 'Wen', &
      'Ald', 'Bran', 'Cal', 'Ed', 'Fen', 'Hal']
   character(len=4), parameter :: PEND(12, 3) = reshape([character(len=4) :: &
      'on', 'ar', 'ic', 'an', 'us', 'em', 'or', 'ad', 'eth', 'in', 'ard', 'ulf', &
      'a', 'ia', 'ara', 'elle', 'is', 'ine', 'ys', 'wen', 'ira', 'ena', 'ae', 'ith', &
      'iel', 'ah', 'ias', 'ael', 'ora', 'eon', 'iah', 'uel', 'ith', 'ane', 'oth', 'ai'], [12, 3])
   character(len=11), parameter :: NUMW(0:20) = [character(len=11) :: 'zero', 'one', 'two', &
      'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', &
      'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', &
      'twenty']

   ! ================================================================ famous rules
   integer, parameter :: NFAM = 28
   character(len=18), parameter :: FAM_N(NFAM) = [character(len=18) :: 'HighLife', 'Seeds', &
      'Day & Night', 'Maze', 'Mazectric', 'Coral', 'Diamoeba', '2x2', 'Morley', 'Long Life', &
      'Amoeba', 'Life without Death', 'Anneal', 'Assimilation', 'Coagulations', 'Stains', &
      'Walled Cities', 'Pedestrian Life', 'DryLife', 'Vote', 'Iceballs', 'Serviettes', &
      'Flock', 'Live Free or Die', 'Bacteria', 'Plow World', 'Land Rush', 'Life']
   character(len=6), parameter :: FAM_B(NFAM) = [character(len=6) :: '36', '2', '3678', '3', &
      '3', '3', '35678', '36', '368', '345', '357', '3', '4678', '345', '378', '3678', &
      '45678', '38', '37', '5678', '25678', '234', '3', '2', '34', '378', '36', '3']
   character(len=9), parameter :: FAM_S(NFAM) = [character(len=9) :: '23', '', '34678', &
      '12345', '1234', '45678', '5678', '125', '245', '5', '1358', '012345678', '35678', &
      '4567', '235678', '235678', '2345', '23', '23', '45678', '5678', '', '12', '0', '456', &
      '012345678', '234578', '23']
   character(len=16), parameter :: FAM_L(NFAM) = [character(len=16) :: 'Replicators', &
      'Sowers', 'Twilight-folk', 'Maze-builders', 'Corridor-folk', 'Coral-growers', &
      'Diamond-folk', 'Twofold', 'Movers', 'Long-lived', 'Amoeba-folk', 'Deathless', &
      'Annealers', 'Assimilators', 'Clotters', 'Stainers', 'Wall-builders', 'Pedestrians', &
      'Dry-folk', 'Voters', 'Ice-folk', 'Weavers', 'Flockers', 'Free', 'Swarmers', &
      'Ploughmen', 'Settlers', 'First People']

contains

   ! ================================================================ the four calls

   subroutine chronicle_params()
      ! two hidden knobs: the years between Ages, and how busy a year may be
      P_AGEGAP = reg_param('age_gap', 'Years between Ages', 'chronicle', 40d0, 5d0, 400d0, &
         'At least this many years pass before the Chronicle proclaims a new Age.', ui=.false.)
      P_BUSY = reg_param('chron_busy', 'Entries per year', 'chronicle', 3d0, 1d0, 50d0, &
         'Small news is dropped when more entries than this were written in the last year.', &
         ui=.false.)
   end subroutine chronicle_params

   subroutine chronicle_init()
      ! a new world: name it and its regions, open the Book at the Age of Beginnings
      nid = 0;  printed = 0;  ndrop = 0;  ent = entry_t()
      harm = harm_t();  nharm = 0;  fall = fallen_t();  nfallen = 0
      rec = 0;  tlast = -1;  had_age = .false.;  t_seen = tick
      age_now = AGE_BEGIN;  age_tick = tick;  had_age(AGE_BEGIN) = .true.
      age_name = 'the Age of Beginnings'
      world_name = world_word()
      call name_regions()
      call add(KIND_AGE, 5, 'Here begins the Age of Beginnings. The world of '//trim(world_name)// &
               ' lay waiting, and the Hand looked upon it.', 0, 0, -1, 0)
   end subroutine chronicle_init

   subroutine chronicle_step()
      ! every waiting event becomes prose; then the queue is emptied
      integer :: k
      if (tick > t_seen) rec = rec*exp(-real(tick - t_seen, dp)/(10*TPY))
      t_seen = tick
      if (nregion > 0 .and. allocated(regs)) then
         if (size(regs) >= nregion) then
            if (len_trim(regs(1)%name) == 0 .or. len_trim(regs(nregion)%name) == 0) &
               call name_regions()
         end if
      end if
      do k = 1, nev
         call tell(evq(k))
      end do
      nev = 0
      if (mod(tick, int(TPY, i8)) == 0) call ages()
   end subroutine chronicle_step

   subroutine chronicle_command(c)
      ! the Chronicle notes when the Hand enters or leaves the Conway limit
      type(cmd_t), intent(in) :: c
      if (c%kind /= CMD_PURIST .or. .not. c%hand) return
      if (c%v > 0.5d0) then
         call add(KIND_HAND, 3, 'The Hand stilled the world. Sky and sea and plague fell away, '// &
                  'and only the old law remained: born of three, enduring on two or three.', &
                  0, 0, RULE_CONWAY, 1)
      else
         call add(KIND_HAND, 3, 'The Hand let the world go, and the winds and the peoples '// &
                  'moved again.', 0, 0, -1, 0)
      end if
   end subroutine chronicle_command

   integer function chronicle_dropped()
      ! entries thinned away by the rate limit so far
      chronicle_dropped = ndrop
   end function chronicle_dropped

   integer function chronicle_last()
      ! the id of the newest entry
      chronicle_last = nid
   end function chronicle_last

   ! ================================================================ the Book: entries

   subroutine add(kind, imp, text, x, y, rule, keya)
      ! write an entry, merging a repeat and thinning small news in a busy year
      integer,      intent(in) :: kind, imp, x, y, rule, keya
      character(*), intent(in) :: text
      integer :: id, k, reg, nrec, lim
      real(dp) :: now
      character(len=:), allocatable :: t
      now = year_now()
      reg = 0
      if ((x /= 0 .or. y /= 0) .and. allocated(region)) then
         reg = region(wrapi(x), wrapj(y))
      end if
      if (imp < 5 .and. kind /= EV_EXTINCT .and. kind /= KIND_AGE) then
         do id = nid, max(1, nid - 29, nid - NE + 1), -1
            k = mod(id - 1, NE) + 1
            if (ent(k)%year < now - 5) exit
            if (ent(k)%kind == kind .and. ent(k)%reg == reg .and. ent(k)%keya == keya .and. &
                ent(k)%rule == rule) then
               ent(k)%rep = ent(k)%rep + 1
               t = ent(k)%text(1:ent(k)%nbase)//' '//again(ent(k)%rep)
               ent(k)%text = t
               return
            end if
         end do
      end if
      if (imp <= 2) then
         lim = 3
         if (P_BUSY > 0) lim = nint(pv(P_BUSY))
         nrec = 0
         do id = nid, max(1, nid - NE + 1), -1
            k = mod(id - 1, NE) + 1
            if (ent(k)%year <= now - 1) exit
            nrec = nrec + 1
         end do
         if (nrec > lim) then
            ndrop = ndrop + 1
            return
         end if
      end if
      t = cap(text)
      nid = nid + 1
      k = mod(nid - 1, NE) + 1
      ent(k) = entry_t(id=nid, kind=kind, imp=max(1, min(5, imp)), x=x, y=y, rule=rule, &
                       reg=reg, keya=keya, rep=1, nbase=min(LT - 48, len(t)), year=now, text=t)
   end subroutine add

   function again(n) result(s)
      ! the tail of a merged entry
      integer, intent(in) :: n
      character(len=:), allocatable :: s
      select case (n)
      case (2);  s = 'So it befell again within those years.'
      case (3);  s = 'Thrice it befell within five years.'
      case default
         s = 'It befell '//numword(n)//' times within those years.'
      end select
   end function again

   subroutine chronicle_json(sb, since_id)
      ! "chron":[{id,year,kind,imp,text,x,y,rule}..] since since_id, and "age":{name,since}
      type(sbuf_t), intent(inout) :: sb
      integer,      intent(in)    :: since_id
      integer :: id, k
      logical :: first
      call sb_put(sb, '"chron":[')
      first = .true.
      do id = max(since_id + 1, nid - NE + 1, 1), nid
         k = mod(id - 1, NE) + 1
         if (.not. first) call sb_put(sb, ',')
         first = .false.
         call sb_put(sb, '{"id":'//itoa(id)//',"year":'//itoa(int(ent(k)%year))//',"kind":'// &
                         jstr(kname(ent(k)%kind))//',"imp":'//itoa(ent(k)%imp)//',"text":'// &
                         jstr(trim(ent(k)%text))//',"x":'//itoa(ent(k)%x)//',"y":'// &
                         itoa(ent(k)%y)//',"rule":'//itoa(ent(k)%rule)//'}')
      end do
      call sb_put(sb, '],"age":{"name":'//jstr(age_name)//',"since":'// &
                      itoa(int(age_tick/TPY))//'}')
   end subroutine chronicle_json

   function kname(k) result(s)
      ! the JSON name of an entry's kind
      integer, intent(in) :: k
      character(len=:), allocatable :: s
      character(len=12), parameter :: CN(31) = [character(len=12) :: 'arise', 'peak', &
         'extinct', 'hybrid', 'legend', 'wanderers', 'crossing', 'lazarus', 'radiation', &
         'dieoff', 'plague', 'plague_end', 'locusts', 'locusts_end', 'titan', 'road', &
         'causeway', 'titan_sleep', 'fire', 'frost', 'snowball', 'thaw', 'hothouse', 'drought', &
         'meteor', 'miracle', 'genesis', 'sweep', 'hunters', 'shrine', 'icebridge']
      character(len=15), parameter :: SN(40:69) = [character(len=15) :: 'realm', 'realm_fall', &
         'revolution', 'succession', 'war', 'peace', 'battle', 'conquest', 'alliance', &
         'sanction', 'tariff', 'tradepact', 'famine', 'price', 'faith', 'prophet', 'prophecy', &
         'prophecy_kept', 'prophecy_failed', 'schism', 'holywar', 'praise', 'convert', &
         'heresy', 'embargo_end', 'annex', 'secede', 'caravan', 'faith_end', 'prophet_death']
      if (k >= 1 .and. k <= 31) then
         s = trim(CN(k))
      else if (k >= 40 .and. k <= 69) then
         s = trim(SN(k))
      else if (k == KIND_AGE) then
         s = 'age'
      else if (k == KIND_HAND) then
         s = 'hand'
      else
         s = 'event'
      end if
   end function kname

   subroutine chronicle_print_new(unit)
      ! the entries not printed yet (headless), wrapped at 100 columns
      integer, intent(in) :: unit
      integer :: id, k, a, b
      character(len=:), allocatable :: t
      do id = max(printed + 1, nid - NE + 1, 1), nid
         k = mod(id - 1, NE) + 1
         t = 'Year '//itoa(int(ent(k)%year))//'. '//trim(ent(k)%text)
         if (ent(k)%kind == KIND_AGE) then
            write(unit, '(a)') ''
            t = '*** '//t//' ***'
         end if
         a = 1
         do while (a <= len(t))
            b = min(len(t), a + 99 - merge(0, 4, a == 1))
            if (b < len(t)) then
               do while (b > a + 40 .and. t(b+1:b+1) /= ' ')
                  b = b - 1
               end do
            end if
            if (a == 1) then
               write(unit, '(a)') t(a:b)
            else
               write(unit, '(a)') '    '//t(a:b)
            end if
            a = b + 1
            do while (a <= len(t))
               if (t(a:a) /= ' ') exit
               a = a + 1
            end do
         end do
      end do
      printed = nid
   end subroutine chronicle_print_new

   ! ================================================================ hashing and words

   integer function hh(a, b, c)
      ! a non-negative hash of three integers
      integer, intent(in) :: a, b, c
      hh = int(iand(mix32(ieor(mix32(iand(int(a, i8)*40503_i8 + int(b, i8), K32)), &
                        iand(int(c, i8)*2654435761_i8 + 12345_i8, K32))), 2147483647_i8))
   end function hh

   integer function tk()
      ! the clock folded into a default integer (for hashes)
      tk = int(iand(tick, 2147483647_i8))
   end function tk

   function pk(t1, t2, t3, t4, t5) result(s)
      ! one of several variants, chosen by the hash of the event being told
      character(*), intent(in) :: t1, t2
      character(*), intent(in), optional :: t3, t4, t5
      character(len=:), allocatable :: s
      integer :: n, k
      n = 2
      if (present(t3)) n = 3
      if (present(t4)) n = 4
      if (present(t5)) n = 5
      k = 1 + mod(hv, n)
      hv = hv/7 + 13*k
      select case (k)
      case (1);  s = t1
      case (2);  s = t2
      case (3);  s = t3
      case (4);  s = t4
      case default;  s = t5
      end select
   end function pk

   function cap(t) result(s)
      ! a capital letter at the start of every sentence
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      integer :: k, c
      logical :: up
      s = t
      up = .true.
      do k = 1, len(s)
         c = iachar(s(k:k))
         if (up) then
            if (c >= 97 .and. c <= 122) then
               s(k:k) = achar(c - 32);  up = .false.
            else if ((c >= 65 .and. c <= 90) .or. (c >= 48 .and. c <= 57)) then
               up = .false.
            end if
         end if
         if (k < len(s)) then
            if (index('.!?', s(k:k)) > 0 .and. s(k+1:k+1) == ' ') up = .true.
         end if
      end do
   end function cap

   function upfirst(t) result(s)
      ! t with its first letter in upper case
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      s = t
      if (len(s) == 0) return
      if (s(1:1) >= 'a' .and. s(1:1) <= 'z') s(1:1) = achar(iachar(s(1:1)) - 32)
   end function upfirst

   function lowfirst(t) result(s)
      ! t with its first letter in lower case
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      s = t
      if (len(s) == 0) return
      if (s(1:1) >= 'A' .and. s(1:1) <= 'Z') s(1:1) = achar(iachar(s(1:1)) + 32)
   end function lowfirst

   function nothe(t) result(s)
      ! a name without its leading article
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      s = trim(t)
      if (len(s) > 4) then
         if (s(1:4) == 'the ' .or. s(1:4) == 'The ') s = s(5:)
      end if
   end function nothe

   function commas(n) result(s)
      ! 2114 -> '2,114'
      integer, intent(in) :: n
      character(len=:), allocatable :: s, d
      integer :: k
      d = itoa(abs(n))
      s = ''
      do k = len(d), 1, -1
         s = d(k:k)//s
         if (mod(len(d) - k + 1, 3) == 0 .and. k > 1) s = ','//s
      end do
      if (n < 0) s = '-'//s
   end function commas

   function numword(n) result(s)
      ! small numbers in words, larger ones in figures
      integer, intent(in) :: n
      character(len=:), allocatable :: s
      character(len=7), parameter :: TENS(3:9) = [character(len=7) :: 'thirty', 'forty', &
         'fifty', 'sixty', 'seventy', 'eighty', 'ninety']
      if (n >= 0 .and. n <= 20) then
         s = trim(NUMW(n))
      else if (n > 20 .and. n < 100 .and. mod(n, 10) == 0) then
         if (n == 20) then
            s = 'twenty'
         else
            s = trim(TENS(n/10))
         end if
      else
         s = commas(n)
      end if
   end function numword

   function fracword(f) result(s)
      ! a share in the old manner
      real(dp), intent(in) :: f
      character(len=:), allocatable :: s
      if (f < 0.07d0) then
         s = 'a small part'
      else if (f < 0.15d0) then
         s = 'a tenth'
      else if (f < 0.22d0) then
         s = 'a fifth'
      else if (f < 0.29d0) then
         s = 'a quarter'
      else if (f < 0.42d0) then
         s = 'a third'
      else if (f < 0.58d0) then
         s = 'half'
      else if (f < 0.71d0) then
         s = 'two parts in three'
      else if (f < 0.83d0) then
         s = 'three parts in four'
      else if (f < 0.95d0) then
         s = 'nine parts in ten'
      else
         s = 'nearly all'
      end if
   end function fracword

   function roman(n) result(s)
      ! regnal numbers
      integer, intent(in) :: n
      character(len=:), allocatable :: s
      integer, parameter :: VAL(13) = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
      character(len=2), parameter :: SYM(13) = [character(len=2) :: 'M', 'CM', 'D', 'CD', 'C', &
         'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I']
      integer :: m, k
      s = ''
      m = max(1, min(3999, n))
      do k = 1, 13
         do while (m >= VAL(k))
            s = s//trim(SYM(k));  m = m - VAL(k)
         end do
      end do
   end function roman

   function ordword(n) result(s)
      ! 1 -> 'first' .. 12 -> 'twelfth', then '13th'
      integer, intent(in) :: n
      character(len=:), allocatable :: s
      character(len=8), parameter :: ORD(12) = [character(len=8) :: 'first', 'second', 'third', &
         'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth', 'tenth', 'eleventh', 'twelfth']
      if (n >= 1 .and. n <= 12) then
         s = trim(ORD(n))
      else
         s = itoa(n)//'th'
      end if
   end function ordword

   logical function isv(c)
      character, intent(in) :: c
      isv = index(VOW, c) > 0
   end function isv

   function joins(s, t) result(r)
      ! join two syllables so that the seam stays pronounceable
      character(*), intent(in) :: s, t
      character(len=:), allocatable :: r
      character :: a, b
      integer :: n
      n = len(s)
      if (n == 0) then
         r = t;  return
      end if
      if (len(t) == 0) then
         r = s;  return
      end if
      a = s(n:n);  b = t(1:1)
      if (b >= 'A' .and. b <= 'Z') b = achar(iachar(b) + 32)
      if (isv(a) .and. isv(b)) then
         if (a == 'i' .and. b == 'i') then
            r = s//t(2:)
         else if (index('ao', a) > 0 .and. index('ao', b) > 0) then
            r = s//'y'//t
         else
            r = s//t
         end if
      else if (a == 'n' .and. (b == 'b' .or. b == 'p')) then
         r = s(1:n-1)//'m'//t
      else if (n >= 2 .and. len(t) >= 2) then
         if (s(n-1:n) == 'th' .and. t(1:2) == 'th') then
            r = s//'e'//t
         else if (a == 'r' .and. b == 'r') then
            r = s//t(2:)
         else if (a == b .and. .not. isv(a)) then
            r = s//t(2:)
         else
            r = s//t
         end if
      else if (a == b .and. .not. isv(a)) then
         r = s//t(2:)
      else
         r = s//t
      end if
   end function joins

   logical function badword(s)
      ! does a made-up name contain a word nobody wants to read?
      character(*), intent(in) :: s
      character(len=len(s)) :: l
      integer :: k
      l = s
      do k = 1, len(l)
         if (l(k:k) >= 'A' .and. l(k:k) <= 'Z') l(k:k) = achar(iachar(l(k:k)) + 32)
      end do
      badword = .false.
      do k = 1, size(BADW)
         if (index(l, trim(BADW(k))) > 0) then
            badword = .true.;  return
         end if
      end do
   end function badword

   ! ================================================================ names of the peoples

   function people_name(rule) result(s)
      ! a syllable per rule bit, B bits then S bits: B3/S23 -> 'Conwayans'
      integer, intent(in) :: rule
      character(len=:), allocatable :: s
      integer :: r
      r = iand(rule, 65535)
      if (popcnt(r) <= 5) then
         s = full_name(r)
      else
         s = short_name(r)
      end if
      s = upfirst(s)
   end function people_name

   function full_name(r) result(s)
      ! every syllable, '-ra' for a rule without survival, and a plural ending
      integer, intent(in) :: r
      character(len=:), allocatable :: s
      integer :: b
      s = ''
      if (iand(r, 127) == 0) s = 'ne'
      do b = 0, 15
         if (btest(r, b)) s = joins(s, trim(SYL(b)))
      end do
      if (iand(r, 65408) == 0) s = joins(s, 'ra')
      s = plural(s)
   end function full_name

   function plural(t) result(s)
      ! -ans, -ites or -i by the ending
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      integer :: n
      n = len(t)
      s = t
      if (n >= 2) then
         if (t(n-1:n) == 'an') then
            s = t//'s';  return
         end if
      end if
      if (t(n:n) == 'y') then
         s = t//'ites'
      else if (index('ai', t(n:n)) > 0) then
         s = t
      else
         s = t//'i'
      end if
   end function plural

   function short_name(r) result(s)
      ! a rule of many bits: the first two B syllables, the first and last S syllables
      ! and a final consonant cluster chosen by the remaining bits
      integer, intent(in) :: r
      character(len=:), allocatable :: s, stem
      logical :: keep(0:15)
      integer :: b, nb, ns, nkeep, rest, tries, k, h
      character :: v
      keep = .false.;  nb = 0;  ns = 0
      do b = 0, 6
         if (btest(r, b) .and. nb < 2) then
            keep(b) = .true.;  nb = nb + 1
         end if
      end do
      do b = 7, 15
         if (btest(r, b)) then
            if (ns == 0) keep(b) = .true.
            ns = ns + 1
         end if
      end do
      do b = 15, 7, -1
         if (btest(r, b)) then
            keep(b) = .true.;  exit
         end if
      end do
      nkeep = count(keep)
      do b = 0, 15
         if (nkeep >= 4) exit
         if (btest(r, b) .and. .not. keep(b)) then
            keep(b) = .true.;  nkeep = nkeep + 1
         end if
      end do
      rest = 0
      do b = 0, 15
         if (btest(r, b) .and. .not. keep(b)) rest = ibset(rest, b)
      end do
      stem = ''
      if (iand(r, 127) == 0) stem = 'ne'
      do b = 0, 15
         if (keep(b)) stem = joins(stem, trim(SYL(b)))
      end do
      if (ns == 0) stem = joins(stem, 'ra')
      s = stem
      do tries = 0, 39
         h = int(mix32(iand(int(rest, i8)*2654435761_i8 + 977_i8 + 7919_i8*tries, K32)))
         if (h < 0) h = -(h + 1)
         if (isv(stem(len(stem):len(stem)))) then
            if (mod(h/4096, 3) == 0) then
               s = stem//trim(CODA1(mod(h, 8)))
            else
               s = stem//trim(CODA2(mod(h, 28)))
            end if
         else
            k = mod(h/256, 5)
            v = VOW(k+1:k+1)
            if (v == lastvowel(stem)) v = VOW(mod(k + 1, 5)+1:mod(k + 1, 5)+1)
            k = mod(h, 28)
            if (CODA2(k)(1:1) == stem(len(stem):len(stem))) k = mod(h + 1, 28)
            s = stem//v//trim(CODA2(k))
         end if
         if (.not. badword(s)) exit
      end do
   end function short_name

   character function lastvowel(s)
      character(*), intent(in) :: s
      integer :: k
      lastvowel = ' '
      do k = len(s), 1, -1
         if (isv(s(k:k))) then
            lastvowel = s(k:k);  return
         end if
      end do
   end function lastvowel

   function people_adj(rule) result(s)
      ! the adjective of a people: Conwayans -> Conwayan, Kara -> Kara
      integer, intent(in) :: rule
      character(len=:), allocatable :: s
      integer :: n
      s = people_name(rule)
      n = len(s)
      if (n > 4) then
         if (s(n-2:n) == 'ans' .or. s(n-3:n) == 'ites') s = s(1:n-1)
      end if
   end function people_adj

   function people_title(rule) result(s)
      ! 'the Pale Conwayans', 'the Thorn-Kara': traits and deeds as epithets
      integer, intent(in) :: rule
      character(len=:), allocatable :: s, adj, pre
      integer :: r, f
      logical :: known
      r = iand(rule, 65535)
      adj = '';  pre = ''
      if (allocated(ppl)) then
         f = ppl(r)%flags
         known = ppl(r)%peak > 0 .or. ppl(r)%n > 0
         if (btest(f, PF_LAZARUS)) then
            adj = 'Twice-born'
         else if (btest(f, PF_SCARRED)) then
            adj = 'Star-scarred'
         else if (btest(f, PF_DREAD)) then
            adj = 'Dread'
         else if (btest(f, PF_BLESSED)) then
            adj = 'Blessed'
         else if (btest(f, PF_ROAD)) then
            adj = 'Roadwalking'
         else if (known .and. ppl(r)%pig >= 11) then
            adj = 'Pale'
         else if (known .and. ppl(r)%pig <= 4) then
            adj = 'Dusky'
         end if
         if (btest(f, PF_SEAFARER)) then
            pre = 'Sea-'
         else if (btest(f, PF_HUNTER) .or. (known .and. ppl(r)%diet >= 4)) then
            pre = 'Thorn-'
         else if (btest(f, PF_FROST) .or. (known .and. ppl(r)%topt <= 2)) then
            pre = 'Frost-'
         else if (known .and. ppl(r)%topt >= 26) then
            pre = 'Sun-'
         end if
      end if
      s = 'the '
      if (len(adj) > 0) s = s//adj//' '
      s = s//pre//people_name(r)
   end function people_title

   function rule_words(rule) result(s)
      ! 'born of three or six, enduring on two or three'
      integer, intent(in) :: rule
      character(len=:), allocatable :: s
      integer :: r
      r = iand(rule, 65535)
      if (iand(r, 127) == 0) then
         s = 'never born anew'
      else
         s = 'born of '//digits_words(r, 0, 6, 2)
      end if
      if (iand(r, 65408) == 0) then
         s = s//' and enduring never'
      else if (iand(r, 65408) == 65408) then
         s = s//' and never dying'
      else
         s = s//' and enduring on '//digits_words(r, 7, 15, 0)
      end if
   end function rule_words

   function digits_words(r, b0, b1, n0) result(s)
      ! the neighbour counts of bits b0..b1 (count n0 at b0) in words
      integer, intent(in) :: r, b0, b1, n0
      character(len=:), allocatable :: s
      integer :: b, n, m, lo, hi
      logical :: run
      n = 0;  lo = -1;  hi = -1
      do b = b0, b1
         if (btest(r, b)) then
            n = n + 1
            if (lo < 0) lo = b
            hi = b
         end if
      end do
      run = n >= 4 .and. hi - lo + 1 == n
      if (run) then
         s = trim(NUMW(lo - b0 + n0))//' to '//trim(NUMW(hi - b0 + n0))
         return
      end if
      s = '';  m = 0
      do b = b0, b1
         if (.not. btest(r, b)) cycle
         m = m + 1
         if (m > 1 .and. m == n) then
            s = s//' or '
         else if (m > 1) then
            s = s//', '
         end if
         s = s//trim(NUMW(b - b0 + n0))
      end do
   end function digits_words

   function rule_flavour(rule) result(s)
      ! what kind of people a rule makes, for the news of their arising
      integer, intent(in) :: rule
      character(len=:), allocatable :: s
      integer :: r
      r = iand(rule, 65535)
      if (iand(r, 65408) == 0) then
         s = rule_words(r)//', who bear no survival in their rule and live only by spreading'
      else if (btest(r, 7)) then
         s = rule_words(r)//', who endure even alone'
      else if (lam(r) > 0.45) then
         s = rule_words(r)//', a teeming and restless kind'
      else if (lam(r) < 0.2) then
         s = rule_words(r)//', a sparse and patient kind'
      else
         s = rule_words(r)
      end if
   end function rule_flavour

   ! ================================================================ famous rules

   integer function famous_index(rule, dist) result(best)
      ! the nearest famous rule within one bit (0: none), and how far it is
      integer, intent(in)  :: rule
      integer, intent(out) :: dist
      integer :: k, d
      best = 0;  dist = 99
      do k = 1, NFAM
         d = hamming(rule, rule_of_bs(FAM_B(k), FAM_S(k)))
         if (d <= 1 .and. d < dist) then
            best = k;  dist = d
         end if
      end do
   end function famous_index

   function famous_rule(rule, dist) result(s)
      ! the name of a famous Life-like rule within one bit of this one ('' if none)
      integer, intent(in)  :: rule
      integer, intent(out) :: dist
      character(len=:), allocatable :: s
      integer :: k
      k = famous_index(rule, dist)
      s = ''
      if (k > 0) s = trim(FAM_N(k))
   end function famous_rule

   ! ================================================================ places

   function place_word(seed) result(s)
      ! a place name from two syllables: Mirrow, Ostral, Ume
      integer, intent(in) :: seed
      character(len=:), allocatable :: s
      integer :: h
      h = hh(seed, 71, world_seed)
      s = joins(trim(PA(1 + mod(h, 32))), trim(PB(1 + mod(h/32, 28))))
      if (mod(h/1024, 7) == 0) s = joins(s, trim(PB(1 + mod(h/8192, 28))))
      if (badword(s)) s = trim(PA(1 + mod(h, 32)))//'ane'
   end function place_word

   function world_word() result(s)
      ! the name of the world
      character(len=:), allocatable :: s
      character(len=3), parameter :: SUF(6) = [character(len=3) :: 'is', 'ia', 'ar', 'os', &
         'eth', 'une']
      integer :: h
      h = hh(world_seed, 3, 977)
      s = joins(place_word(h), trim(SUF(1 + mod(h/7, 6))))
   end function world_word

   subroutine name_regions()
      ! a name for every region from a syllable grammar and its character
      real(dp), allocatable :: se(:), sw(:), st(:)
      integer,  allocatable :: sn(:)
      character(len=24), allocatable :: used(:)
      character(len=:), allocatable :: w, nm
      integer :: i, j, k, r, salt, nsea, h
      real(dp) :: me, mw, mt, msea
      logical :: dup
      if (nregion < 1 .or. .not. allocated(regs)) return
      if (size(regs) < nregion) return
      allocate(se(nregion), sw(nregion), st(nregion), sn(nregion), used(nregion))
      se = 0;  sw = 0;  st = 0;  sn = 0;  used = ''
      do j = 1, NY
         do i = 1, NX
            r = region(i,j)
            if (r < 1 .or. r > nregion) cycle
            se(r) = se(r) + elev(i,j);  sw(r) = sw(r) + wet(i,j);  st(r) = st(r) + temp(i,j)
            sn(r) = sn(r) + 1
         end do
      end do
      msea = 0;  nsea = 0
      do r = 1, nregion
         if (regs(r)%kind == 1) then
            msea = msea + sn(r);  nsea = nsea + 1
         end if
      end do
      msea = msea/max(1, nsea)
      do r = 1, nregion
         me = se(r)/max(1, sn(r));  mw = sw(r)/max(1, sn(r));  mt = st(r)/max(1, sn(r))
         h = hh(r, 5, world_seed)
         if (regs(r)%kind == 0) then
            if (me > 1500) then
               w = 'Heights'
            else if (mw > 0.72d0) then
               w = 'Fens'
            else if (mw < 0.3d0) then
               w = 'Barrens'
            else if (mw < 0.45d0 .and. mt < 12) then
               w = 'Steppe'
            else if (me > 800) then
               w = trim(merge('Downs', 'Wold ', mod(h, 2) == 0))
            else
               select case (mod(h/2, 3))
               case (0);  w = 'Reach'
               case (1);  w = 'Vale'
               case default;  w = 'Marches'
               end select
            end if
         else
            if (me < -3500) then
               w = 'Deep'
            else if (me > -600) then
               w = 'Shallows'
            else if (sn(r) < 0.4d0*msea) then
               w = trim(merge('Sound', 'Gulf ', mod(h, 2) == 0))
            else
               w = 'Sea'
            end if
         end if
         do salt = 0, 30
            nm = place_word(r*97 + salt*7919)
            dup = .false.
            do k = 1, r - 1
               if (used(k) == nm) dup = .true.
            end do
            if (.not. dup) exit
         end do
         used(r) = nm
         select case (w)
         case ('Reach', 'Steppe', 'Wold')
            regs(r)%name = nm//' '//w
         case ('Vale')
            if (mod(h/8, 2) == 0) then
               regs(r)%name = 'the Vale of '//nm
            else
               regs(r)%name = nm//' Vale'
            end if
         case default
            regs(r)%name = 'the '//nm//' '//w
         end select
      end do
   end subroutine name_regions

   function region_at(i, j) result(s)
      ! the name of the region at cell (i,j)
      integer, intent(in) :: i, j
      character(len=:), allocatable :: s
      integer :: k
      s = 'the wilds'
      if (.not. allocated(region) .or. .not. allocated(regs)) return
      k = region(wrapi(i), wrapj(j))
      if (k >= 1 .and. k <= min(nregion, size(regs))) then
         if (len_trim(regs(k)%name) > 0) s = trim(regs(k)%name)
      end if
   end function region_at

   function reg_name(r) result(s)
      ! the name of region r
      integer, intent(in) :: r
      character(len=:), allocatable :: s
      s = 'a far country'
      if (.not. allocated(regs)) return
      if (r >= 1 .and. r <= min(nregion, size(regs))) then
         if (len_trim(regs(r)%name) > 0) s = trim(regs(r)%name)
      end if
   end function reg_name

   function placeof(x, y) result(s)
      ! the place of an event ('the world' when it is nowhere in particular)
      integer, intent(in) :: x, y
      character(len=:), allocatable :: s
      if (x == 0 .and. y == 0) then
         s = 'the world'
      else
         s = region_at(x, y)
      end if
   end function placeof

   ! ================================================================ Titans and plagues

   function titan_name(k) result(s)
      ! 'Ammon the Walker (RL)': an old god's name and a trade, with its rule
      integer, intent(in) :: k
      character(len=:), allocatable :: s
      character(len=7), parameter :: GN(20) = [character(len=7) :: 'Ammon', 'Orrek', 'Talos', &
         'Ymir', 'Kronn', 'Hadad', 'Moloch', 'Atlas', 'Brontes', 'Gog', 'Magog', 'Anu', 'Enlil', &
         'Ossar', 'Thule', 'Vorn', 'Baalor', 'Surt', 'Hrungn', 'Tiamut']
      character(len=9), parameter :: TR(10) = [character(len=9) :: 'Walker', 'Mason', &
         'Ploughman', 'Weaver', 'Wanderer', 'Spinner', 'Turner', 'Builder', 'Delver', 'Mower']
      integer :: h, g, id
      character(len=16) :: ru
      if (k < 1 .or. k > MAXTITAN) then
         s = 'an Old Machine';  return
      end if
      ru = titans(k)%rule
      id = titans(k)%id
      if (id == 0) id = k
      h = hh(id, 17, world_seed)
      g = 0
      do id = 1, len_trim(ru)
         g = g*31 + iachar(ru(id:id))
         g = mod(g, 1000003)
      end do
      if (trim(ru) == 'RL') then
         s = trim(GN(1 + mod(h, 20)))//' the Walker'
      else
         s = trim(GN(1 + mod(h, 20)))//' the '//trim(TR(1 + mod(g + h/20, 10)))
      end if
      if (len_trim(ru) > 0) s = s//' ('//trim(ru)//')'
   end function titan_name

   function strain_name(k) result(s)
      ! 'the Grey Cough', 'the Weeping': distinct for the first 160 strains
      integer, intent(in) :: k
      character(len=:), allocatable :: s
      character(len=22), parameter :: OLD(16) = [character(len=22) :: 'the Weeping', &
         'the Shivers', 'the Sweating Sickness', 'the Wasting', 'the Blackening', &
         'the Marsh Fever', 'the Long Sleep', 'the Trembling', 'the Bloody Flux', &
         'the Dancing Death', 'the Thin Fever', 'the Ash-Lung', 'the Quiet Death', &
         'the Stone Fever', 'the Bone-Ache', 'the Green Sweat']
      character(len=9), parameter :: ADJ(12) = [character(len=9) :: 'Grey', 'Pale', 'Red', &
         'Black', 'Weeping', 'Shaking', 'Bitter', 'Creeping', 'Hollow', 'Burning', 'Silent', &
         'Yellow']
      character(len=7), parameter :: NOUN(12) = [character(len=7) :: 'Cough', 'Rot', 'Fever', &
         'Pox', 'Blight', 'Flux', 'Wasting', 'Sweat', 'Ague', 'Canker', 'Palsy', 'Mange']
      integer :: m
      if (k < 1) then
         s = 'the Grey';  return
      end if
      m = mod((k - 1)*67 + mod(world_seed, 160) + 160, 160)
      if (m < 16) then
         s = trim(OLD(m + 1))
      else
         m = mod((m - 16)*65, 144)
         s = 'the '//trim(ADJ(1 + mod(m, 12)))//' '//trim(NOUN(1 + m/12))
      end if
      if (k > 160) s = s//' Returned'
   end function strain_name

   ! ================================================================ realms and rulers

   function gov_word(gov) result(s)
      ! the noun of a government: 'Kingdom', 'Holy See' ...
      integer, intent(in) :: gov
      character(len=:), allocatable :: s
      select case (gov)
      case (GOV_CHIEFDOM);   s = 'Chiefdom'
      case (GOV_KINGDOM);    s = 'Kingdom'
      case (GOV_REPUBLIC);   s = 'Republic'
      case (GOV_THEOCRACY);  s = 'Holy See'
      case (GOV_COMMUNE);    s = 'Commune'
      case (GOV_HORDE);      s = 'Horde'
      case (GOV_EMPIRE);     s = 'Empire'
      case (GOV_ANARCHY);    s = 'Anarchy'
      case default;          s = 'Realm'
      end select
   end function gov_word

   integer function realm_index(p)
      ! the syllable pair of realm p, kept distinct from the realms founded before it
      integer, intent(in) :: p
      integer :: q, m, idx(MAXPOL), tries
      logical :: dup
      realm_index = 0
      do q = 1, p
         idx(q) = mod(hh(pol(q)%seed, q, world_seed), 576)
         do tries = 1, 576
            dup = .false.
            do m = 1, q - 1
               if (idx(m) == idx(q)) dup = .true.
            end do
            if (.not. dup) exit
            idx(q) = mod(idx(q) + 173, 576)
         end do
      end do
      realm_index = idx(p)
   end function realm_index

   function realm_name(p) result(s)
      ! the short name of a realm: 'Ostral', 'Vashti'
      integer, intent(in) :: p
      character(len=:), allocatable :: s
      integer :: m
      if (p < 1 .or. p > MAXPOL) then
         s = 'Nowhere';  return
      end if
      m = realm_index(p)
      s = joins(trim(RA(1 + mod(m, 24))), trim(RB(1 + m/24)))
      if (badword(s)) s = trim(RA(1 + mod(m, 24)))//'ane'
   end function realm_name

   function realm_title(p) result(s)
      ! 'the Kingdom of Ostral', 'the Kara Horde', 'the Commune of the Ume Fens' ...
      integer, intent(in) :: p
      character(len=:), allocatable :: s
      if (p < 1 .or. p > MAXPOL) then
         s = 'a nameless realm';  return
      end if
      select case (pol(p)%gov)
      case (GOV_HORDE)
         if (pol(p)%people >= 0) then
            s = 'the '//people_adj(pol(p)%people)//' Horde'
         else
            s = 'the '//realm_name(p)//' Horde'
         end if
      case (GOV_EMPIRE)
         if (pol(p)%people >= 0) then
            s = 'the '//people_adj(pol(p)%people)//' Empire'
         else
            s = 'the Empire of '//realm_name(p)
         end if
      case (GOV_COMMUNE)
         if (pol(p)%capital >= 1 .and. pol(p)%capital <= nregion) then
            s = 'the Commune of '//reg_name(pol(p)%capital)
         else
            s = 'the Commune of '//realm_name(p)
         end if
      case default
         s = 'the '//gov_word(pol(p)%gov)//' of '//realm_name(p)
      end select
   end function realm_title

   function person_name(seed, sex) result(s)
      ! a given name: sex 1 male, 2 female, 3 prophetic
      integer, intent(in) :: seed, sex
      character(len=:), allocatable :: s, a, e
      integer :: h
      character :: c
      h = hh(seed, 29 + sex, 4099)
      a = trim(PST(1 + mod(h, 36)))
      e = trim(PEND(1 + mod(h/36, 12), max(1, min(3, sex))))
      c = a(len(a):len(a))
      if (index('lmnrst', c) > 0 .and. isv(e(1:1)) .and. mod(h/432, 5) < 2) then
         s = a//c//e
      else if (isv(c) .and. isv(e(1:1))) then
         s = a//'r'//e
      else
         s = joins(a, e)
      end if
      if (badword(s)) s = a//'an'
   end function person_name

   function prophet_name(seed) result(s)
      ! a prophet: 'Ossiel', 'Vesah'
      integer, intent(in) :: seed
      character(len=:), allocatable :: s
      s = person_name(seed, 3)
   end function prophet_name

   function ruler_name(p) result(s)
      ! 'Queen Ammara II the Pale', 'Consul Ithe Dorrow', 'Khan Tamar the Red'
      integer, intent(in) :: p
      character(len=:), allocatable :: s, ti, given, epi
      character(len=14), parameter :: EP(24) = [character(len=14) :: 'the Pale', 'the Bold', &
         'the Unready', 'the Wise', 'the Cruel', 'the Fair', 'the Pious', 'the Lame', &
         'the Great', 'the Silent', 'the Mad', 'the Young', 'Ironhand', 'the Builder', &
         'the Just', 'the Red', 'the Black', 'the Grey', 'the Fat', 'the Merciful', &
         'the Thrice-Wed', 'Stormborn', 'the Wanderer', 'the Last']
      integer :: g, seed, h
      logical :: female
      if (p < 1 .or. p > MAXPOL) then
         s = 'a nameless lord';  return
      end if
      g = pol(p)%gov
      seed = pol(p)%ruler
      if (seed == 0) seed = 7*pol(p)%seed + 1
      h = hh(seed, 41, 7)
      female = mod(h/3, 2) == 1
      given = person_name(seed, merge(2, 1, female))
      epi = ''
      if (mod(h/6, 3) /= 0) epi = ' '//trim(EP(1 + mod(hh(seed, pol(p)%regnal, 43), 24)))
      select case (g)
      case (GOV_KINGDOM);    ti = trim(merge('Queen', 'King ', female))
      case (GOV_EMPIRE);     ti = trim(merge('Empress', 'Emperor', female))
      case (GOV_HORDE);      ti = trim(merge('Khatun', 'Khan  ', female))
      case (GOV_CHIEFDOM);   ti = 'Chieftain'
      case (GOV_REPUBLIC);   ti = 'Consul'
      case (GOV_COMMUNE);    ti = 'Speaker'
      case (GOV_THEOCRACY);  ti = trim(merge('Prophetess ', 'High Priest', female))
      case default;          ti = 'the Warlord'
      end select
      select case (g)
      case (GOV_KINGDOM, GOV_EMPIRE, GOV_HORDE, GOV_CHIEFDOM)
         s = ti//' '//given//' '//roman(max(1, pol(p)%regnal))//epi
      case (GOV_REPUBLIC, GOV_COMMUNE)
         s = ti//' '//given//' '//place_word(hh(seed, 3, 11))
      case (GOV_THEOCRACY)
         s = ti//' '//given
         if (len(epi) > 0) s = s//epi
      case default
         s = ti//' '//given//epi
      end select
   end function ruler_name

   function seat_word(g) result(s)
      ! what a ruler of government g takes
      integer, intent(in) :: g
      character(len=:), allocatable :: s
      select case (g)
      case (GOV_KINGDOM);    s = 'crown'
      case (GOV_EMPIRE);     s = 'throne'
      case (GOV_HORDE);      s = 'horsetail standard'
      case (GOV_CHIEFDOM);   s = 'chief''s stool'
      case (GOV_REPUBLIC);   s = 'consul''s chair'
      case (GOV_COMMUNE);    s = 'speaker''s bench'
      case (GOV_THEOCRACY);  s = 'holy staff'
      case default;          s = 'what power there was'
      end select
   end function seat_word

   ! ================================================================ faiths and prophecy

   integer function faith_cause(f)
      ! what revealed faith f, as a CMD_* kind (10..30) or 100 + an EV_* kind; natural
      ! wonders may be given as 100 + EV kind or -EV kind, the ambiguous small codes are
      ! read by the faith's tenets where they can be
      integer, intent(in) :: f
      integer :: c
      real(sp) :: dv
      c = faiths(f)%cause;  dv = faiths(f)%devotion
      if (fa_wonder(f) .and. c > 0 .and. c < 100) then   ! rl_faith says: a natural wonder
         faith_cause = 100 + c
      else if (c >= 100) then
         faith_cause = c
      else if (c < 0) then
         faith_cause = 100 - c
      else if (c == EV_WANDERERS .or. c == EV_LAZARUS .or. c == EV_METEOR) then
         faith_cause = 100 + c
      else if (c == 15 .and. dv < 0) then
         faith_cause = 100 + EV_TITAN
      else if (c == 11 .and. dv < 0.55) then
         faith_cause = 100 + EV_PLAGUE
      else
         faith_cause = c
      end if
   end function faith_cause

   function faith_base(f) result(s)
      ! the name a faith takes from what revealed it
      integer, intent(in) :: f
      character(len=:), allocatable :: s
      integer :: c
      hv = hh(faiths(f)%seed, 53, f)
      if (mod(hv, 4) < 2) then
         hv = 0
      else
         hv = hv/4
      end if
      c = faith_cause(f)
      select case (c)
      case (CMD_SOW)
         s = pk('the Sown', 'the Seedbearers', 'the Children of the Furrow')
      case (CMD_MANNA)
         s = pk('the Church of the Open Hand', 'the Gleaners', 'the Table of Plenty')
      case (CMD_LIGHTNING)
         s = pk('the Thunder-Sworn', 'the Riven', 'the Church of the Bright Spear')
      case (CMD_RAIN)
         s = pk('the Rainward', 'the Covenant of Rain', 'the Weeping Sky')
      case (CMD_WIND)
         s = pk('the Windborn', 'the Followers of the Breath')
      case (CMD_PESTILENCE, 100 + EV_PLAGUE)
         s = pk('the Penitents of the Grey', 'the Flagellants', 'the Ashen Penitents')
      case (CMD_STARFALL, 100 + EV_METEOR)
         s = pk('the Starfallen', 'the Watchers of the Falling Star', &
                'the Church of the Burning Stone')
      case (CMD_TITAN, 100 + EV_TITAN)
         s = pk('the Brazen Path', 'the Machine Choir', 'the Followers of the Iron Walk')
      case (CMD_RAISE)
         s = pk('the Mountain-Born', 'the Shapers')
      case (CMD_LOWER)
         s = pk('the Sunken Way', 'the Delvers')
      case (CMD_FREEZE, 100 + EV_SNOWBALL, 100 + EV_FROST)
         s = pk('the Frost Covenant', 'the White Silence')
      case (CMD_THAW, 100 + EV_THAW)
         s = pk('the Thaw', 'the Kindled Spring')
      case (CMD_LOCUSTS, 100 + EV_LOCUSTS)
         s = pk('the Locust Brethren', 'the Hungry Wind')
      case (CMD_SMITE)
         s = pk('the Smitten', 'the Order of the Wrath', 'the Fearful')
      case (CMD_STAMP)
         s = pk('the Pattern-Keepers', 'the Order of the Glider')
      case (CMD_PROPHET)
         s = pk('the Voice of the Hand', 'the Listeners')
      case (100 + EV_LAZARUS)
         s = pk('the Resurrection', 'the Twice-Risen')
      case (100 + EV_FIRE)
         s = pk('the Flame', 'the Ashen Rite')
      case (100 + EV_WANDERERS)
         s = pk('the Way of the Wanderer', 'the Gliding Way')
      case default
         s = 'the Faith of '//reg_name(faiths(f)%origin)
      end select
   end function faith_base

   recursive function faith_name(f) result(s)
      ! 'the Starfallen', 'the Church of the Open Hand'; a schism is 'the Reformed ...',
      ! 'the True ...' or, if it turned on the Hand, 'the Unbowed ...'
      integer, intent(in) :: f
      character(len=:), allocatable :: s
      integer :: q, p, h, d, r
      character(len=8), parameter :: ORDW(6) = [character(len=8) :: 'Second', 'Third', &
                                     'Fourth', 'Fifth', 'Sixth', 'Seventh']
      if (f < 1 .or. f > MAXFAITH) then
         s = 'a nameless faith';  return
      end if
      p = faiths(f)%parent
      if (p >= 1 .and. p < f .and. p <= MAXFAITH) then
         h = hh(faiths(f)%seed, 59, f)
         if ((faiths(f)%devotion < 0) .neqv. (faiths(p)%devotion < 0)) then
            s = 'Unbowed'
         else if (mod(h, 2) == 0) then
            s = 'Reformed'
         else
            s = 'True'
         end if
         d = 0;  r = f                          ! a schism of a schism: named from the root
         do while (faiths(r)%parent >= 1 .and. faiths(r)%parent < r .and. d < 50)
            r = faiths(r)%parent;  d = d + 1
         end do
         if (d >= 2) s = trim(ORDW(min(d - 1, 6)))//' '//s
         s = 'the '//s//' '//nothe(faith_name(r))
         do q = 1, f - 1                        ! two alike: the younger says where it began
            if (faiths(q)%state == 0 .or. faiths(q)%parent < 1) cycle
            if (faith_name(q) == s) then
               s = s//' of '//reg_name(faiths(f)%origin)
               exit
            end if
         end do
         return
      end if
      s = faith_base(f)
      do q = 1, f - 1
         if (faiths(q)%state == 0) cycle
         if (faiths(q)%parent >= 1 .and. faiths(q)%parent < q) cycle
         if (faith_base(q) == s) then
            s = s//' of '//reg_name(faiths(f)%origin)
            exit
         end if
      end do
   end function faith_name

   function cause_phrase(f) result(s)
      ! how a faith came to be, for the news of its founding
      integer, intent(in) :: f
      character(len=:), allocatable :: s
      select case (faith_cause(f))
      case (CMD_SOW);          s = 'who saw the Hand sow the living'
      case (CMD_MANNA);        s = 'who ate of the Hand''s manna'
      case (CMD_LIGHTNING);    s = 'who saw the Hand''s lightning'
      case (CMD_RAIN);         s = 'who stood in the Hand''s rain'
      case (CMD_WIND);         s = 'who felt the Hand turn the wind'
      case (CMD_PESTILENCE);   s = 'who survived the Hand''s pestilence'
      case (CMD_STARFALL);     s = 'who saw the Hand cast down a star'
      case (CMD_TITAN);        s = 'who saw the Hand call up an Old Machine'
      case (CMD_RAISE);        s = 'who saw the Hand lift the hills'
      case (CMD_LOWER);        s = 'who saw the Hand press down the earth'
      case (CMD_FREEZE);       s = 'who felt the Hand''s frost'
      case (CMD_THAW);         s = 'who felt the Hand''s warmth'
      case (CMD_LOCUSTS);      s = 'who saw the Hand loose the swarm'
      case (CMD_SMITE);        s = 'who saw the Hand smite their kin'
      case (CMD_STAMP);        s = 'who saw the Hand set a pattern in the world'
      case (CMD_PROPHET);      s = 'who heard the Hand speak'
      case (100 + EV_METEOR);  s = 'who watched a star fall'
      case (100 + EV_TITAN);   s = 'who revere the Old Machines above the Hand'
      case (100 + EV_SNOWBALL, 100 + EV_FROST);  s = 'who lived through the white world'
      case (100 + EV_THAW);    s = 'who saw the ice break'
      case (100 + EV_LAZARUS); s = 'who saw a fallen people rise again'
      case (100 + EV_PLAGUE);  s = 'who were spared by the Grey'
      case (100 + EV_FIRE);    s = 'who walked through the great fire'
      case (100 + EV_WANDERERS);  s = 'who followed the first wanderers'
      case default;            s = 'whose beginnings are hidden'
      end select
   end function cause_phrase

   function speaker(k) result(s)
      ! who uttered prophecy k
      integer, intent(in) :: k
      character(len=:), allocatable :: s
      if (prophs(k)%prophet /= 0) then
         s = prophet_name(prophs(k)%prophet)//' of '//faith_name(prophs(k)%faith)
      else
         s = 'a seer of '//faith_name(prophs(k)%faith)
      end if
   end function speaker

   function victor(k) result(s)
      ! the realm a prophecy of victory is about
      integer, intent(in) :: k
      character(len=:), allocatable :: s
      integer :: p, q
      p = prophs(k)%target
      if (p < 1 .or. p > npol) then
         p = 0
         do q = 1, npol
            if (pol(q)%state == 1 .and. pol(q)%faith == prophs(k)%faith) then
               p = q;  exit
            end if
         end do
      end if
      if (p >= 1) then
         s = realm_title(p)
      else
         s = 'the faithful'
      end if
   end function victor

   function clause(k, mode) result(s)
      ! what prophecy k is about: mode 1 'shall', 2 past, 3 a plea to the Hand, 4 'would'
      integer, intent(in) :: k, mode
      character(len=:), allocatable :: s, r, p
      integer :: t
      r = reg_name(prophs(k)%region)
      t = prophs(k)%target
      p = 'the peoples'
      if (t >= 0 .and. t <= 65535) p = people_title(t)
      select case (prophs(k)%kind)
      case (PR_STAR)
         s = trim(fmode(mode, 'a star shall fall upon ', 'a star fell upon ', &
                        'cast down thy star upon ', 'a star would fall upon '))//' '//r
      case (PR_WINTER)
         s = fmode(mode, 'the white shall cover the world', 'the white came down upon the world', &
                   'send thy winter upon the world', 'the white would cover the world')
      case (PR_THAW)
         s = fmode(mode, 'the ice shall break and the seas run free', &
                   'the ice broke and the seas ran free', 'break the ice that binds the world', &
                   'the ice would break')
      case (PR_PLAGUE)
         s = trim(fmode(mode, 'a grey sickness shall come among', 'the sickness came among', &
                        'send thy pestilence among', 'a sickness would come among'))//' '//p
      case (PR_FALL)
         s = realm_title(t)//' '//fmode(mode, 'shall fall', 'fell', 'X', 'would fall')
         if (mode == 3) s = 'cast down '//realm_title(t)
      case (PR_RISE)
         s = trim(fmode(mode, 'a new people shall arise from', 'a new people arose from', &
                        'raise a new people from', 'a new people would arise from'))//' '//p
      case (PR_MANNA)
         s = trim(fmode(mode, 'manna shall fall upon', 'manna fell upon', &
                        'let thy manna fall upon', 'manna would fall upon'))//' '//r
      case (PR_TITAN)
         s = fmode(mode, 'the Old Machine shall wake', 'the Old Machine woke', &
                   'wake the Old Machine', 'the Old Machine would wake')
      case (PR_RAIN)
         s = fmode(mode, 'the rains shall return to the parched land', 'the rains returned', &
                   'open the heavens and send thy rain', 'the rains would return')
      case (PR_VICTORY)
         s = 'the banners of '//victor(k)//' '//fmode(mode, 'shall prevail', 'prevailed', 'X', &
                                                      'would prevail')
         if (mode == 3) s = 'give the banners of '//victor(k)//' the victory'
      case (PR_LAZARUS)
         s = p//fmode(mode, ', who are fallen, shall rise again from the soil', &
                      ' rose again from the soil', 'X', ' would rise again')
         if (mode == 3) s = 'raise '//p//' from the soil where they sleep'
      case (PR_FIRE)
         s = trim(fmode(mode, 'fire shall walk upon', 'fire walked upon', 'send thy fire upon', &
                        'fire would walk upon'))//' '//r
      case default
         s = fmode(mode, 'a sign shall be given', 'a sign was given', 'give us a sign', &
                   'a sign would be given')
      end select
   end function clause

   function fmode(mode, a, b, c, d) result(s)
      ! one of four forms
      integer,      intent(in) :: mode
      character(*), intent(in) :: a, b, c, d
      character(len=:), allocatable :: s
      select case (mode)
      case (1);  s = a
      case (2);  s = b
      case (3);  s = c
      case default;  s = d
      end select
   end function fmode

   function prophecy_text(k) result(s)
      ! the full words of prophecy k
      integer, intent(in) :: k
      character(len=:), allocatable :: s, yr, tail
      integer :: h
      if (k < 1 .or. k > MAXPROPH) then
         s = '';  return
      end if
      if (prophs(k)%state == 0) then
         s = '';  return
      end if
      yr = itoa(int(prophs(k)%t_due/TPY))
      h = hh(prophs(k)%seed, 61, k)
      if (prophs(k)%to_hand) then
         select case (mod(h, 5))
         case (0, 1, 2);  tail = 'and we shall know thee'
         case (3);        tail = 'and we shall sing thy name'
         case default;    tail = 'that the faithful may know thee'
         end select
         if (prophs(k)%kind == PR_MANNA) tail = 'for its children hunger, '//tail
         s = '"O Hand, '//clause(k, 3)//' before the year '//yr//', '//tail//'," prays '// &
             speaker(k)//'.'
      else
         select case (mod(h, 6))
         case (0, 1, 2);  tail = ' foretells'
         case (3);        tail = ' has seen it in a dream'
         case (4);        tail = ' proclaims'
         case default;    tail = ' cries out in the market'
         end select
         s = upfirst(speaker(k))//tail//': before the year '//yr//' '//clause(k, 1)//'.'
      end if
   end function prophecy_text

   ! ================================================================ telling one event

   function tok(t) result(s)
      ! the value of a {token} for the event being told
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      select case (t)
      case ('R');   s = placeof(cur%x, cur%y)
      case ('A');   s = people_title(cur%a)
      case ('a');   s = people_name(cur%a)
      case ('B');   s = people_title(cur%b)
      case ('b');   s = people_name(cur%b)
      case ('rs');  s = rule_str(cur%a)
      case ('rw');  s = rule_words(cur%a)
      case ('n');   s = commas(nint(min(2d9, max(-2d9, cur%v))))
      case ('nw');  s = numword(nint(min(2d9, max(-2d9, cur%v))))
      case ('f');   s = fracword(cur%v)
      case ('S');   s = trim(cur%s)
      case ('T');   s = titan_name(cur%a)
      case ('G');   s = strain_name(cur%a)
      case ('PA');  s = realm_title(cur%a)
      case ('PB');  s = realm_title(cur%b)
      case ('pa');  s = realm_name(cur%a)
      case ('pb');  s = realm_name(cur%b)
      case ('KA');  s = ruler_name(cur%a)
      case ('FA');  s = faith_name(cur%a)
      case ('FB');  s = faith_name(cur%b)
      case ('W');   s = trim(world_name)
      case ('Y');   s = itoa(int(cur%tick/TPY))
      case ('1');   s = trim(xs(1))
      case ('2');   s = trim(xs(2))
      case ('3');   s = trim(xs(3))
      case ('4');   s = trim(xs(4))
      case default; s = t
      end select
   end function tok

   function fill(t) result(s)
      ! a template with its {tokens} filled in
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      integer :: a, b
      s = ''
      a = 1
      do while (a <= len(t))
         if (t(a:a) == '{') then
            b = index(t(a:), '}')
            if (b > 1) then
               s = s//tok(t(a+1:a+b-2))
               a = a + b
               cycle
            end if
         end if
         s = s//t(a:a)
         a = a + 1
      end do
      s = fill_an(s)                           ! 'a' before a vowel is 'an'
   end function fill

   recursive function fill_an(t) result(s)
      ! the rest of a sentence with 'a' before a vowel made 'an'
      character(*), intent(in) :: t
      character(len=:), allocatable :: s
      integer :: a
      a = index(t, ' a ')
      if (a == 0 .or. a + 3 > len(t)) then
         s = t;  return
      end if
      if (index('aeiouAEIOU', t(a+3:a+3)) > 0) then
         s = t(1:a)//'an '//fill_an(t(a+3:))
      else
         s = t(1:a+2)//fill_an(t(a+3:))
      end if
   end function fill_an

   subroutine remember(e, rule, aux)
      ! keep a harm in mind, for the epitaphs to come
      type(event_t), intent(in) :: e
      integer,       intent(in) :: rule, aux
      nharm = nharm + 1
      harm(mod(nharm - 1, NH) + 1) = harm_t(kind=e%kind, x=e%x, y=e%y, rule=rule, aux=aux, &
                                            v=e%v, tick=e%tick)
   end subroutine remember

   subroutine tell(e)
      ! one event into the Book
      type(event_t), intent(in) :: e
      character(len=:), allocatable :: t
      integer :: imp, rl, ka, k, d, n
      cur = e;  xs = ''
      hv = hh(e%kind*7919 + e%a, e%b + 31*e%x + 977*e%y, int(iand(e%tick, 2147483647_i8)))
      if (e%kind >= 1 .and. e%kind <= NK) then
         rec(e%kind) = rec(e%kind) + 1
         tlast(e%kind) = e%tick
      end if
      imp = 2;  rl = -1;  ka = e%a;  t = ''
      select case (e%kind)
      ! ------------------------------------------------------------ the peoples
      case (EV_ARISE)
         imp = 3;  rl = e%a
         xs(1) = rule_flavour(e%a)
         if (e%b >= 0 .and. e%b /= e%a) then
            t = pk('From {B} of {R} arose a new people, {A} ({rs}), {1}.', &
                   'In {R} a new people came forth from {B}: {A} ({rs}), {1}.', &
                   'Out of {B} were born {A} ({rs}) in {R}, {1}.', &
                   'The {b} of {R} gave rise to a new people, {A} ({rs}), {1}.')
         else
            t = pk('In {R} arose a new people, {A} ({rs}), {1}.', &
                   'A new people stood up in {R}: {A} ({rs}), {1}.', &
                   'Unbidden, {A} ({rs}) appeared in {R}, {1}.')
         end if
         k = famous_index(e%a, d)
         if (k > 0 .and. k < NFAM) then
            xs(2) = trim(FAM_L(k));  xs(3) = trim(FAM_N(k))
            if (d == 0) then
               t = t//pk(' The {2} of old have returned: they are {3} of the elder books.', &
                         ' The {2} of old have returned, whom the elder books call {3}.')
            else
               t = t//pk(' They are kin to the {2} of old, the {3} of the elder books.', &
                         ' In them the elder books see kinship with {3}, the {2} of old.')
            end if
            if (allocated(ppl)) ppl(rl)%flags = ibset(ppl(rl)%flags, PF_LEGEND)
            imp = 4
         end if
      case (EV_PEAK)
         imp = 3;  rl = e%a
         t = pk('{A} now hold {f} of all that lives.', &
                'Never were {A} so many: {f} of the living are theirs.', &
                'The world fills with {A}; {f} of all life now bears their rule.')
      case (EV_EXTINCT)
         imp = 4;  rl = e%a
         t = epitaph(e)
      case (EV_HYBRID)
         imp = 3;  rl = e%a
         if (allocated(ppl)) ppl(rl)%flags = ibset(ppl(rl)%flags, PF_HYBRID)
         xs(1) = 'their kin'
         if (e%v >= 0 .and. e%v <= 65535) xs(1) = people_title(nint(e%v))
         t = pk('In {R} {1} and {B} mingled, and {A} were born of both.', &
                'Two peoples met in {R}, {1} and {B}; of their mingling came {A}.', &
                'Of {1} and {B} together were born {A} ({rs}), in {R}.')
      case (EV_LEGEND)
         imp = 4;  rl = e%a
         if (allocated(ppl)) ppl(rl)%flags = ibset(ppl(rl)%flags, PF_LEGEND)
         k = famous_index(e%a, d)
         if (k > 0) then
            xs(1) = trim(FAM_L(k));  xs(2) = trim(FAM_N(k))
            t = pk('{A} were seen to be the {1} of old, whom the elder books call {2}.', &
                   'The wise of {R} knew {A} at last: they are the {1}, {2} of the elder books.')
         else
            t = '{A} passed into legend.'
         end if
      case (EV_WANDERERS)
         rl = e%a;  imp = 3
         if (allocated(ppl)) ppl(rl)%flags = ibset(ppl(rl)%flags, PF_WANDER)
         if (rec(EV_WANDERERS) < 1.01d0 .and. .not. had_age(AGE_WANDER)) imp = 4
         t = pk('The first wanderers of {A} were seen crossing {R}: small ships of five, ' // &
                'gliding ever on.', &
                'Over {R} went wanderers of {A}, five together, never resting, never turning.', &
                'In {R} some of {A} took to the road: little ships of five cells that sail ' // &
                'the empty land.')
      case (EV_CROSSING)
         imp = 3;  rl = e%a
         if (allocated(ppl)) ppl(rl)%flags = ibset(ppl(rl)%flags, PF_SEAFARER)
         t = pk('Seafarers of {A} came ashore in {R}, a land their people had never known.', &
                '{A} crossed the water and set foot upon {R}.', &
                'Beyond the sea {A} found {R}, and settled there.')
      case (EV_LAZARUS)
         imp = 4;  rl = e%a
         t = lazarus(e)
      case (EV_RADIATION)
         imp = 3
         t = pk('A flowering of peoples: {nw} new peoples arose within ten years.', &
                'The rules of life ran wild; {nw} new peoples were named in ten years.', &
                'It was a time of many births: {nw} new peoples in a decade, the last of ' // &
                'them {A}.')
      case (EV_DIEOFF)
         imp = 4
         xs(1) = fracword(1 - e%v)
         t = pk('A great dying: {1} of all that lived perished.', &
                'The world emptied; {1} of the living were gone within five years.', &
                'Silence spread over {W}, for {1} of the living perished.')
      case (EV_HUNTERS)
         imp = 3;  rl = e%a
         call remember(e, e%a, 0)
         t = pk('{A} learned to hunt; they feed now upon other peoples.', &
                'In {R} {A} turned hunter, and the peoples about them grew few.', &
                '{A} grew teeth: they take their bread from the flesh of their neighbours.')
      ! ------------------------------------------------------------ plague and awe
      case (EV_PLAGUE)
         imp = 4;  rl = e%b
         call remember(e, e%b, e%a)
         if (trim(e%s) == 'hand') then
            t = pk('At the Hand''s word {G} was loosed upon {B} in {R}.', &
                   'The Hand sent {G} among {B}; it began in {R}.')
         else
            t = pk('{G} came among {B} in their crowded towns of {R}.', &
                   'In {R} {B} began to sicken: it was {G}.', &
                   'A sickness rose in {R}: {G}, and it fed upon {B}.')
         end if
      case (EV_PLAGUE_END)
         imp = 3;  rl = e%b
         t = pk('{G} passed from the world, having taken {n}.', &
                '{G} burned itself out at last; {n} lay dead of it.', &
                'The last fever of {G} cooled. It had taken {n} of {B} and their neighbours.')
      case (EV_SHRINE)
         imp = 3;  rl = e%b
         t = pk('In {R} the reverent of {B} raised a shrine, and pilgrims came.', &
                'A holy place grew in {R}, where {B} had long kept faith with the Hand.', &
                '{B} hallowed a shrine in {R}.')
      ! ------------------------------------------------------------ locusts and Titans
      case (EV_LOCUSTS)
         imp = 3
         call remember(e, -1, 0)
         t = pk('The Hungry Wind rose over {R}: a swarm of {n} darkened the sky.', &
                'Locusts gathered over {R}, {n} wings beating as one.', &
                'Over {R} the sky turned to wings; the swarm numbered {n}.')
      case (EV_LOCUSTS_END)
         imp = 2
         xs(1) = numword(e%a)
         t = pk('The swarm over {R} broke and scattered after {1} years; at its height it ' // &
                'numbered {n}.', 'The Hungry Wind fell still after {1} years.', &
                'The locusts went back to their solitary ways after {1} years.')
      case (EV_TITAN)
         imp = 4
         select case (e%b)
         case (0)
            t = pk('At the Hand''s call {T} woke in {R}.', &
                   'The Hand summoned {T}, and it rose in {R} and began to walk.')
         case (1)
            t = pk('From the crater in {R} climbed {T}, an Old Machine.', &
                   'Where the star had fallen in {R}, {T} woke and began to walk.')
         case default
            t = pk('Out of the Hand''s crater in {R} climbed {T}.', &
                   'The Hand''s star broke open the earth of {R}, and {T} climbed out.')
         end select
      case (EV_ROAD)
         imp = 4
         t = pk('After {n} steps of seeming madness, {T} began to build a road through {R}.', &
                'The tread of {T} grew straight in {R}: it was building a highway.', &
                '{T} ceased its wandering in {R} and laid down a road, straight as a spear.')
      case (EV_CAUSEWAY)
         imp = 4
         t = pk('{T} raised a causeway of {n} cells across the water to a new land.', &
                'The road of {T} ran into the sea and did not stop; a causeway joined the ' // &
                'lands at {R}.', 'At {R} the sea was bridged by {T}.')
      case (EV_TITAN_SLEEP)
         imp = 3
         t = pk('{T} lay down in {R} and became stone, after {n} steps.', &
                'In {R} {T} walked no more; it sleeps as a stone landmark.', &
                '{T} grew still in {R}; the peoples go round it now, as round a hill.')
      ! ------------------------------------------------------------ sky and fire
      case (EV_FIRE)
         ka = 0
         imp = 2
         if (e%v > 2000) imp = 3
         if (e%b == 1) imp = 4
         call remember(e, -1, 0)
         select case (trim(e%s))
         case ('hand');  xs(1) = 'the Hand''s fire'
         case ('star');  xs(1) = 'the fire of the fallen star'
         case default;   xs(1) = 'a fire kindled by lightning'
         end select
         t = pk('{1} walked through {R}, and {n} leagues of green burned.', &
                'Fire ran through {R}: {n} leagues of green went up in smoke.', &
                'In {R} {1} burned {n} leagues of green.')
         if (e%a > 0) t = t//' '//commas(e%a)//' of the living perished in it.'
         if (e%b == 1) t = t//' It was the greatest burning yet seen.'
      case (EV_FROST)
         imp = 4
         call remember(e, -1, 0)
         t = pk('A Great Winter came; the ice held {f} of the world.', &
                'The white came down from the poles until {f} of {W} lay under ice.', &
                'Winter would not end. Ice covered {f} of the world.')
      case (EV_SNOWBALL)
         imp = 5
         call remember(e, -1, 0)
         t = pk('The world turned white from pole to pole, and the sun glanced off it.', &
                '{W} became a ball of snow; only the warm girdle of the world still breathed.', &
                'The ice closed over the world. The living huddled in the last warm places.')
      case (EV_THAW)
         imp = 5
         t = pk('After {nw} years of white, the world thawed and the seas ran free.', &
                'The ice broke at last, after {nw} years, and green came back to the land.', &
                'The long white ended after {nw} years.')
      case (EV_HOTHOUSE)
         imp = 4
         xs(1) = ftoa(e%v, 1)
         t = pk('The air grew hot as a kiln; the mean warmth of the world rose past {1} ' // &
                'degrees.', 'The world sweltered, its mean warmth above {1} degrees.', &
                'A furnace age: the seas steamed at {1} degrees.')
      case (EV_DROUGHT)
         imp = 3
         call remember(e, -1, 0)
         t = pk('Drought lay upon the lands about {R}; the soil lost {f} of its water.', &
                'The rains failed about {R}, and the rivers shrank.', &
                'The earth cracked about {R}: drought.')
      case (EV_ICEBRIDGE)
         imp = 3
         t = pk('The sea froze between two lands near {R}, and a bridge of ice joined them.', &
                'Near {R} the sea became a road of ice from shore to shore.')
      case (EV_SWEEP)
         imp = 3
         if (e%a == 1) then
            t = pk('The Hand took hold of the sun, and it began to wax and wane at the ' // &
                   'Hand''s will.', &
                   'The sun began to breathe, brighter and dimmer, at the Hand''s will.')
         else
            t = pk('The sun was steady once more.', 'The Hand let go of the sun.')
         end if
      case (EV_METEOR)
         ka = 0
         call remember(e, -1, 0)
         n = dead_near(e%x, e%y, nint(e%v) + 2)
         if (e%b == 1) then
            imp = 5
            t = pk('The Hand cast down a star upon {R}.', &
                   'A star fell upon {R} from the Hand.', &
                   'The Hand hurled a burning stone upon {R}.')
         else
            imp = 4
            t = pk('A star fell upon {R}.', 'Fire fell out of heaven upon {R}.', &
                   'A stone of the sky struck {R}.')
         end if
         select case (trim(e%s))
         case ('sea');   t = t//pk(' The sea boiled and great waves ran out.', &
                                   ' The waters were thrown up to the clouds.')
         case ('lake');  t = t//pk(' A lake filled the wound.', &
                                   ' Where it struck, a round lake lies now.')
         case default;   t = t//pk(' The earth was torn open.', ' A crater smokes there still.')
         end select
         if (n > 0) t = t//' '//commas(n)//' perished.'
         if (dust > 0.12d0) t = t//pk(' The sky grew dark.', ' The sun was veiled with dust.')
      case (EV_MIRACLE)
         ka = e%b;  imp = 2
         t = miracle(e, imp)
      case (EV_GENESIS)
         imp = 5;  rl = RULE_CONWAY
         if (trim(e%s) == 'again') then
            t = pk('Life was kindled again in {R}: B3/S23, as in the beginning.', &
                   'From the dead world the old law woke again in {R}.')
         else
            t = pk('In the beginning there was B3/S23, and {A} woke in {R}, {n} strong.', &
                   'First came {A} ({rs}), born of three and enduring on two or three; ' // &
                   'they woke in {R}.')
         end if
      ! ------------------------------------------------------------ realms
      case (EV_REALM)
         imp = 4;  rl = e%b
         t = pk('{B} of {R} gathered under one rule, and {PA} was founded; {KA} held the ' // &
                'first seat.', 'In {R} arose {PA}, a realm of {B}, with {KA} at its head.', &
                '{PA} was founded in {R} by {B}. Its first ruler was {KA}.')
      case (EV_REALM_FALL)
         imp = 4
         xs(1) = numword(nint(e%v))
         if (e%b > 0) then
            t = pk('{PA} fell to {PB}, after {1} years.', &
                   'After {1} years {PA} was no more; {PB} had swallowed it.', &
                   'The banners of {PB} flew over the last city of {PA}. It had stood {1} years.')
         else
            t = pk('{PA} fell after {1} years, and its people scattered.', &
                   'After {1} years {PA} came apart, and none ruled there.', &
                   '{PA} is no more. It stood {1} years.')
         end if
      case (EV_REVOLUTION)
         imp = 4
         xs(1) = lowfirst(gov_word(nint(e%v)));  xs(2) = lowfirst(gov_word(e%b))
         t = pk('In {pa} the old {1} was cast down, and {PA} was proclaimed.', &
                'Revolution in {pa}: the {1} gave way to a {2}. It is {PA} now.', &
                'The people of {pa} rose against the {1}; {PA} stands in its place.')
      case (EV_SUCCESSION)
         imp = 2
         if (e%a >= 1 .and. e%a <= MAXPOL) xs(1) = seat_word(pol(e%a)%gov)
         select case (e%b)
         case (1)
            t = pk('The ruler of {PA} died, and {KA} took up the {1}.', &
                   '{KA} came to the {1} of {PA} upon the old ruler''s death.', &
                   'In {PA} the old ruler was laid in the earth; {KA} rules now.')
         case (2)
            imp = 3
            t = pk('{KA} cast down the ruler of {PA} and took the {1}.', &
                   'The ruler of {PA} was deposed; {KA} sits in their place.')
         case (3)
            imp = 3
            t = pk('The ruler of {PA} was slain in battle; {KA} took up the {1}.', &
                   'Word came from the field: the ruler of {PA} had fallen. {KA} reigns.')
         case default
            if (trim(e%s) == 're-elected') then
               t = pk('{PA} chose {KA} again.', '{KA} was chosen once more to lead {PA}.')
            else
               t = pk('{PA} chose {KA} to lead them.', 'By the voice of many, {KA} was ' // &
                      'raised in {PA}.', 'The choosing in {PA} fell upon {KA}.')
            end if
         end select
         if (trim(e%s) == 'crisis') then
            imp = 3
            t = t//pk(' The succession was bitterly disputed.', ' Not all bowed to them.')
         end if
      case (EV_WAR, EV_HOLYWAR)
         imp = 4
         call remember(e, -1, 0)
         if (e%kind == EV_HOLYWAR) then
            xs(1) = faith_name(nint(e%v))
            t = pk('In the name of {1}, {PA} declared holy war upon {PB}.', &
                   '{PA} took up the banners of {1} and marched upon {PB}.', &
                   'Holy war: {PA}, sworn to {1}, fell upon {PB}.')
         else
            select case (nint(e%v))
            case (1);  xs(1) = 'hungering for their land'
            case (2);  xs(1) = 'in the name of their god'
            case (3);  xs(1) = 'for plunder'
            case (4);  xs(1) = 'out of old border hatred'
            case (5);  xs(1) = 'for vengeance'
            case (6);  xs(1) = 'called to arms by an ally'
            case default;  xs(1) = 'for reasons none recall'
            end select
            t = pk('{PA} made war upon {PB}, {1}.', 'War: {PA} marched against {PB}, {1}.', &
                   '{PA} rose against {PB}, {1}.', 'The drums of {PA} sounded against {PB}, {1}.')
         end if
      case (EV_PEACE)
         imp = 3
         if (nint(e%v) == 1 .and. trim(e%s) == 'tribute') then
            t = pk('{PB} bowed to {PA} and paid tribute; the war was ended.', &
                   'The war ended with {PB} paying tribute to {PA}.')
         else if (nint(e%v) == -1) then
            t = pk('{PA} sued for peace and paid tribute to {PB}.', &
                   'Beaten, {PA} bought peace from {PB}.')
         else
            t = pk('Weary of war, {PA} and {PB} made a truce.', &
                   'A truce was sworn between {PA} and {PB}; nothing had been won.')
         end if
      case (EV_BATTLE)
         imp = 3
         call remember(e, -1, 0)
         t = pk('Near {R} the hosts of {PA} broke those of {PB}; {n} fell.', &
                'A great battle in {R}: {PA} prevailed over {PB}, and {n} were slain.', &
                'At {R} {PB} was beaten by {PA}. {n} lay on the field.')
      case (EV_CONQUEST)
         imp = 3
         call remember(e, -1, 0)
         xs(1) = reg_name(nint(e%v))
         t = pk('{PA} wrested {1} from {PB}.', '{1} passed by the sword from {PB} to {PA}.', &
                'The armies of {PA} took {1}; {PB} could not hold it.')
      case (EV_ANNEX)
         imp = 1
         xs(1) = reg_name(nint(e%v))
         t = pk('{PA} took {1} into its keeping without a blow.', &
                '{1} came under {PA} in peace.')
      case (EV_SECEDE)
         imp = 3
         xs(1) = 'a province'
         if (e%a >= 1 .and. e%a <= MAXPOL) xs(1) = reg_name(pol(e%a)%capital)
         t = pk('{1} broke away from {PB} and became {PA}.', &
                '{PB} was sundered: {PA} rose in {1} and would not be ruled.')
      case (EV_ALLIANCE)
         imp = 3
         t = pk('{PA} and {PB} swore alliance.', 'A pact of arms between {PA} and {PB}.', &
                '{PA} and {PB} clasped hands against their enemies.')
      case (EV_TRADEPACT)
         imp = 2
         t = pk('{PA} and {PB} opened their markets to each other.', &
                'A trade pact between {PA} and {PB}; caravans went to and fro.')
      case (EV_SANCTION)
         imp = 2
         if (nint(e%v) == 1) then
            t = pk('{PA} shut its markets against {PB}.', &
                   '{PA} would buy nothing from {PB} and sell it nothing.')
         else
            t = pk('{PA} lifted its ban upon the goods of {PB}.', '{PA} forgave {PB} its trade.')
         end if
      case (EV_EMBARGO_END)
         imp = 2
         t = pk('{PA} and {PB} opened their gates to each other''s goods again.', &
                'The embargo between {PA} and {PB} was ended.')
      case (EV_TARIFF)
         imp = 1
         if (e%v >= 1) then
            t = '{PA} barred its gates to the goods of {PB}.'
         else
            xs(1) = itoa(nint(100*e%v))
            t = pk('{PA} laid a duty of {1} in the hundred upon the goods of {PB}.', &
                   'The customs men of {PA} took {1} in the hundred from the traders of {PB}.')
         end if
      case (EV_FAMINE)
         imp = 3
         call remember(e, -1, e%a)
         t = pk('Famine in {PA}: {f} of the grain they needed could not be had.', &
                'The granaries of {PA} stood empty; {f} of its bread was wanting.', &
                'Hunger walked in {PA}.')
      case (EV_PRICE)
         imp = 2;  ka = e%b
         xs(1) = 'goods'
         if (e%b >= 1 .and. e%b <= NGOODS) xs(1) = trim(GOOD_NAME(e%b))
         if (trim(e%s) == 'crash') then
            if (e%v <= 0.34d0) then
               xs(2) = 'fell to a third'
            else if (e%v <= 0.55d0) then
               xs(2) = 'was halved'
            else
               xs(2) = 'fell'
            end if
            t = pk('The price of {1} {2} in the markets of the world.', &
                   'Merchants wept: {1} {2} in a year.')
         else
            if (e%v >= 2.8d0) then
               xs(2) = 'trebled'
            else if (e%v >= 1.8d0) then
               xs(2) = 'doubled'
            else
               xs(2) = 'rose by half'
            end if
            t = pk('The price of {1} {2} in the markets of the world.', &
                   'Dear {1}: its price {2} in a single year.')
         end if
      case (EV_CARAVAN)
         imp = 1
         xs(1) = 'goods'
         if (nint(e%v) >= 1 .and. nint(e%v) <= NGOODS) xs(1) = trim(GOOD_NAME(nint(e%v)))
         t = pk('A caravan of {1} went from {PA} to {PB}, and settlers followed it to {R}.', &
                'Traders of {PA} carried {1} to {PB}; some stayed, in {R}.')
      ! ------------------------------------------------------------ faiths
      case (EV_FAITH)
         imp = 4
         if (e%a >= 1 .and. e%a <= MAXFAITH) then
            xs(1) = cause_phrase(e%a)
         else
            xs(1) = 'whose beginnings are hidden'
         end if
         t = pk('In {R} a new faith was kindled: {FA}, {1}.', &
                'A faith was born in {R}: {FA}, {1}.', &
                '{FA} first gathered in {R}, {1}.')
      case (EV_FAITH_END)
         imp = 3
         t = pk('{FA} passed from the world; none keep their rites.', &
                'The last of {FA} died, and their temples stand empty.')
      case (EV_PROPHET)
         imp = 3
         xs(1) = prophet_name(e%b)
         t = pk('{1} rose among {FA} in {R} and began to prophesy.', &
                'A prophet came to {FA}: {1}, in {R}.', &
                'In {R} {1} heard voices, and {FA} listened.')
      case (EV_PROPHET_DEATH)
         imp = 2
         xs(1) = prophet_name(e%b)
         t = pk('{1}, prophet of {FA}, died.', '{1} of {FA} was gathered to the Hand.', &
                'The prophet {1} is dead; {FA} mourn.')
      case (EV_PROPHECY)
         imp = 3;  ka = e%a
         if (e%a >= 1 .and. e%a <= MAXPROPH) then
            t = prophecy_text(e%a)
            if (prophs(e%a)%to_hand) imp = 4
         end if
         if (len(t) == 0) t = '{FB} uttered a prophecy.'
      case (EV_PROPHECY_KEPT)
         imp = 4;  ka = e%a
         if (e%a >= 1 .and. e%a <= MAXPROPH) then
            xs(1) = speaker(e%a);  xs(2) = clause(e%a, 2)
            t = pk('The word of {1} was fulfilled: {2}.', &
                   'It came to pass as {1} had said: {2}.', &
                   'So it was: {2}, as {1} foretold.')
         else
            t = 'A prophecy of {FB} came to pass.'
         end if
         if (nint(e%v) == 1) then
            imp = 5
            t = t//pk(' The Hand had heard them. Praise the Hand!', &
                      ' It was the Hand that did it. Praise the Hand!', &
                      ' And the faithful cried: Praise the Hand!')
         end if
      case (EV_PROPHECY_FAILED)
         imp = 3;  ka = e%a
         if (e%a >= 1 .and. e%a <= MAXPROPH) then
            xs(1) = speaker(e%a);  xs(2) = clause(e%a, 4)
            xs(3) = itoa(int(prophs(e%a)%t_due/TPY))
            t = pk('{1} had foretold that {2}; but the year {3} came and went.', &
                   'The year {3} passed, and the word of {1} failed: they had said {2}.', &
                   'Shame upon {FB}: {1} had promised that {2}, and it was not so.')
         else
            t = 'A prophecy of {FB} failed.'
         end if
      case (EV_SCHISM)
         imp = 3
         t = pk('{FB} were rent asunder; {FA} went their own way.', &
                'Schism: {FA} broke from {FB}.', &
                'In bitterness {FA} left {FB}, and each called the other false.')
      case (EV_PRAISE)
         imp = 3;  ka = e%a
         t = pk('In {R} {FA} lifted up their voices: "Praise the Hand!"', &
                '"Praise the Hand!" sang {FA} in {R}.', &
                'The Hand''s gift was seen in {R}, and {FA} cried, "Praise the Hand!"')
      case (EV_CONVERT)
         imp = 3
         xs(1) = faith_name(e%b)
         xs(2) = 'the old ways'
         if (nint(e%v) >= 1) xs(2) = faith_name(nint(e%v))
         t = pk('{PA} turned from {2} to {1}.', '{PA} took {1} for its faith, forsaking {2}.', &
                'The temples of {PA} were given to {1}.')
      case (EV_HERESY)
         imp = 2
         t = pk('{FB} named {FA} heretics, and the realms that kept them grew cold to ' // &
                'each other.', '{FB} cursed {FA} as heretics.')
      case default
         imp = 1
         t = 'Something stirred in {R}.'
      end select
      if (len(t) == 0) return
      call add(e%kind, imp, fill(t), e%x, e%y, rl, ka)
   end subroutine tell

   function miracle(e, imp) result(t)
      ! the Hand's deeds (star-falls, plagues and Titans are told by their own events)
      type(event_t), intent(in)    :: e
      integer,       intent(inout) :: imp
      character(len=:), allocatable :: t
      t = ''
      select case (e%b)
      case (CMD_SOW)
         xs(1) = 'the living'
         if (e%a > 0) xs(1) = people_title(e%a)
         t = pk('The Hand sowed {1} in {R}.', 'Into {R} the Hand scattered {1}.', &
                'From the Hand {1} fell like seed upon {R}.')
      case (CMD_MANNA)
         t = pk('Manna fell from the Hand upon {R}, and the hungry ate.', &
                'The Hand fed {R}; the land grew green overnight.', &
                'Bread from heaven in {R}: the Hand''s manna.')
      case (CMD_LIGHTNING)
         t = pk('The Hand hurled lightning upon {R}.', 'A bolt from the Hand struck {R}.')
      case (CMD_RAIN)
         t = pk('At the Hand''s word the heavens opened over {R}.', &
                'The Hand sent rain upon {R}.')
      case (CMD_WIND)
         t = pk('The Hand turned the wind over {R}, and the swarms were driven before it.', &
                'A wind from the Hand swept {R}.')
      case (CMD_RAISE)
         t = pk('The Hand lifted the earth of {R} into hills.', 'Hills rose in {R} at the ' // &
                'Hand''s touch.')
      case (CMD_LOWER)
         t = pk('The Hand pressed down the earth of {R}.', 'The ground of {R} sank under ' // &
                'the Hand.')
      case (CMD_FREEZE)
         call remember(e, -1, 0)
         t = pk('The Hand breathed frost upon {R}.', 'Ice came to {R} out of season, ' // &
                'from the Hand.')
      case (CMD_THAW)
         t = pk('The Hand warmed {R}, and the ice let go.', 'The ice of {R} melted at the ' // &
                'Hand''s touch.')
      case (CMD_LOCUSTS)
         call remember(e, -1, 0)
         imp = 3
         t = pk('The Hand loosed the Hungry Wind upon {R}.', 'Locusts poured from the Hand ' // &
                'over {R}.')
      case (CMD_SMITE)
         call remember(e, -1, 0)
         imp = 3
         t = pk('The Hand smote {R}; {n} perished.', 'In {R} the Hand struck down {n} of ' // &
                'the living.', 'Wrath fell upon {R}: {n} were slain by the Hand.')
      case (CMD_STAMP)
         xs(1) = 'a pattern'
         if (len_trim(e%s) > 0) xs(1) = 'a '//trim(e%s)
         t = pk('The Hand set {1} upon {R}.', 'The Hand drew {1} in {R}, and it lived.')
      case (CMD_STARFALL, CMD_PESTILENCE, CMD_TITAN, CMD_PROPHET)
         t = ''
      case default
         t = 'The Hand moved upon {R}.'
      end select
   end function miracle

   integer function dead_near(x, y, r)
      ! cells that died this tick within r of (x,y)
      integer, intent(in) :: x, y, r
      integer :: a, b, rr
      dead_near = 0
      if (.not. allocated(died) .or. (x == 0 .and. y == 0)) return
      rr = min(r, 40)
      do b = -rr, rr
         do a = -rr, rr
            if (a*a + b*b > rr*rr) cycle
            if (died(wrapi(x + a), wrapj(y + b)) /= 0) dead_near = dead_near + 1
         end do
      end do
   end function dead_near

   ! ================================================================ epitaphs

   function epitaph(e) result(t)
      ! 'Here ended the Pale Kara, born of two and enduring never ...'
      type(event_t), intent(in) :: e
      character(len=:), allocatable :: t, place
      integer :: r, y0
      integer(i8) :: t0
      r = iand(e%a, 65535)
      t0 = -1
      if (allocated(ppl)) then
         t0 = ppl(r)%t_named
         if (t0 < 0) t0 = ppl(r)%t_first
      end if
      y0 = int(max(0_i8, t0)/TPY)
      xs(1) = itoa(y0)
      t = pk('Here ended {A}, {rw}. They arose in {1}, numbered {n} at their height, and ' // &
             'fell in {Y}.', &
             'The last of {A} passed from {R}. {rw}, they had stood since {1}, {n} strong at ' // &
             'their height.', &
             'So ended {A}, {rw}: arisen in {1}, {n} at their height, gone in {Y}.')
      t = t//' '//death_cause(e)
      place = seed_place(r)
      if (len(place) > 0) then
         t = t//pk(' Their seeds sleep in the soil of '//place//'.', &
                   ' Yet their seeds sleep in the soil of '//place//'.')
      else
         place = placeof(e%x, e%y)
      end if
      nfallen = nfallen + 1
      fall(mod(nfallen - 1, NFALL) + 1) = fallen_t(rule=r, year=int(e%tick/TPY), &
                                                 place=place, title=people_title(r))
   end function epitaph

   function death_cause(e) result(s)
      ! the likeliest cause of a people's end, from the harms remembered
      type(event_t), intent(in) :: e
      character(len=:), allocatable :: s
      integer :: k, m, best, pri, bp
      real(dp) :: d, yrs
      best = 0;  bp = 99
      do m = max(1, nharm - NH + 1), nharm
         k = mod(m - 1, NH) + 1
         yrs = real(e%tick - harm(k)%tick, dp)/TPY
         if (yrs > 30 .or. yrs < 0) cycle
         d = 1d9
         if (harm(k)%x /= 0 .or. harm(k)%y /= 0) &
            d = sqrt(dxwrap(real(harm(k)%x - e%x, dp))**2 + dywrap(real(harm(k)%y - e%y, dp))**2)
         pri = 99
         select case (harm(k)%kind)
         case (EV_PLAGUE)
            if (harm(k)%rule == e%a) then
               pri = 1
            else if (hamming(strains(max(1, min(MAXSTRAIN, harm(k)%aux)))%key, e%a) <= 1) then
               pri = 2
            end if
         case (EV_METEOR)
            if (d < 3*harm(k)%v + 25 .and. yrs < 15) pri = 3
         case (EV_MIRACLE)
            if (d < 30) pri = 4
         case (EV_SNOWBALL, EV_FROST)
            pri = 5
         case (EV_FIRE)
            if (d < 40) pri = 6
         case (EV_WAR, EV_HOLYWAR, EV_BATTLE, EV_CONQUEST)
            if (d < 50) pri = 7
         case (EV_HUNTERS)
            if (harm(k)%rule /= e%a .and. d < 80) pri = 8
         case (EV_LOCUSTS, EV_DROUGHT, EV_FAMINE)
            if (d < 60 .or. harm(k)%kind == EV_FAMINE) pri = 9
         end select
         if (pri < bp) then
            bp = pri;  best = k
         end if
      end do
      if (best == 0 .and. ice_frac > 0.5d0) bp = 5
      select case (bp)
      case (1, 2)
         xs(2) = strain_name(harm(best)%aux)
         s = pk('{2} took the last of them.', 'It was {2} that ended them.', &
                'They did not outlive {2}.')
      case (3)
         s = pk('A star fell near them, and they never recovered.', &
                'The fallen star broke them.')
      case (4)
         s = pk('The Hand''s anger was upon them.', 'They perished under the Hand.')
      case (5)
         s = pk('The ice came for them.', 'The white world was too cold for them.', &
                'They could not endure the long winter.')
      case (6)
         s = pk('Fire took their country.', 'They burned with their green land.')
      case (7)
         s = pk('War trampled their fields.', 'They were ground between the armies.')
      case (8)
         xs(2) = people_title(harm(best)%rule)
         s = pk('{2} hunted them to the last.', 'They were the prey of {2}.')
      case (9)
         s = pk('Hunger took them when the fields failed.', 'Their fields were eaten bare, ' // &
                'and they starved.')
      case default
         s = pk('No foe was named; they died of the slow hunger.', &
                'They were not slain; they faded, of the slow hunger.', &
                'None slew them. The slow hunger had them.')
      end select
   end function death_cause

   function seed_place(r) result(s)
      ! the region where most seeds of people r sleep ('' if none)
      integer, intent(in) :: r
      character(len=:), allocatable :: s
      integer, allocatable :: cnt(:)
      integer :: i, j, k, best
      s = ''
      if (.not. allocated(seedg) .or. nregion < 1) return
      allocate(cnt(nregion))
      cnt = 0
      do j = 1, NY
         do i = 1, NX
            if (seedg(i,j) == 0) cycle
            if (g_rule(seedg(i,j)) /= r) cycle
            k = region(i,j)
            if (k >= 1 .and. k <= nregion) cnt(k) = cnt(k) + 1
         end do
      end do
      best = 1
      do k = 2, nregion
         if (cnt(k) > cnt(best)) best = k
      end do
      if (cnt(best) > 0) s = reg_name(best)
   end function seed_place

   function lazarus(e) result(t)
      ! a fallen people rises: the foreshadowing paid off
      type(event_t), intent(in) :: e
      character(len=:), allocatable :: t
      integer :: k, m, f
      f = 0
      do m = nfallen, max(1, nfallen - NFALL + 1), -1
         k = mod(m - 1, NFALL) + 1
         if (fall(k)%rule == iand(e%a, 65535)) then
            f = k;  exit
         end if
      end do
      xs(1) = numword(nint(e%v))
      if (f > 0) then
         xs(2) = trim(fall(f)%place);  xs(3) = trim(fall(f)%title);  xs(4) = itoa(fall(f)%year)
         if (e%b == 1) then
            t = pk('From the soil of {2}, where {3} were laid down in {4}, they rose again.', &
                   'The seeds in the soil of {2} woke: {3}, fallen in {4}, live again.', &
                   'In {2} the earth gave back what it had kept since {4}: {3} rose again.')
         else
            t = pk('{3}, fallen in {4}, returned to {R} after {1} years.', &
                   'They were thought lost in {4}; yet {3} walk again in {R}.')
         end if
      else
         t = pk('{A}, thought lost these {1} years, rose again in {R}.', &
                'Out of the soil of {R} came {A} again, after {1} years.')
      end if
   end function lazarus

   ! ================================================================ Ages

   subroutine ages()
      ! once a year: is the world in a new Age?
      integer :: k, a, best, nwar, npact, nking, nproph, top, gap
      best = 0
      gap = 40
      if (P_AGEGAP > 0) gap = nint(pv(P_AGEGAP))
      if (tick - age_tick < int(gap, i8)*TPY) return
      nwar = 0;  npact = 0;  nking = 0;  nproph = 0;  top = 0
      do k = 1, npol
         if (pol(k)%state /= 1) cycle
         if (pol(k)%gov == GOV_KINGDOM .or. pol(k)%gov == GOV_EMPIRE) nking = nking + 1
         nwar = nwar + count(war(k, 1:npol) == 1)
         npact = npact + count(pact(k, 1:npol) == 1)
      end do
      nwar = nwar/2;  npact = npact/2
      do k = 1, nfaith
         if (faiths(k)%state == 1 .and. faiths(k)%prophet /= 0) nproph = nproph + 1
      end do
      if (allocated(ppl) .and. n_alive > 0) then
         do k = 0, 65535
            if (ppl(k)%n > top) top = ppl(k)%n
         end do
      end if
      do k = 1, NAGE - 1
         a = AGE_ORDER(k)
         if (cond(a)) then
            best = a;  exit
         end if
      end do
      if (best == 0 .or. best == age_now) return
      age_now = best;  age_tick = tick;  had_age(best) = .true.
      age_name = 'the Age of '//trim(AGE_WORD(best))
      call add(KIND_AGE, 5, card(best), 0, 0, -1, best)
   contains
      logical function cond(a)
         integer, intent(in) :: a
         select case (a)
         case (AGE_SILENCE);  cond = recent(EV_DIEOFF, 5)
         case (AGE_ICE);      cond = ice_frac > 0.5d0
         case (AGE_GREY);     cond = (n_alive > 0 .and. n_sick > 0.04d0*n_alive) .or. &
                                     rec(EV_PLAGUE) >= 3
         case (AGE_FIRE);     cond = n_burning > 0.004d0*NX*NY .or. rec(EV_FIRE) >= 4
         case (AGE_ONE);      cond = n_alive > 0.005d0*NX*NY .and. top > 0.8d0*n_alive
         case (AGE_WARS);     cond = nwar >= 2 .or. rec(EV_WAR) + rec(EV_HOLYWAR) >= 3
         case (AGE_TITAN);    cond = recent(EV_ROAD, 15)
         case (AGE_PROPHETS); cond = nproph >= 3 .or. rec(EV_PROPHECY) + rec(EV_PROPHET) >= 4
         case (AGE_KINGS);    cond = nking >= 3
         case (AGE_TRADE);    cond = npact >= 3 .or. rec(EV_TRADEPACT) + rec(EV_CARAVAN)/4 >= 3
         case (AGE_WONDER);   cond = recent(EV_MIRACLE, 5) .and. &
                                     (.not. had_age(AGE_WONDER) .or. rec(EV_MIRACLE) >= 6)
         case (AGE_MANY);     cond = n_notable >= 12 .or. recent(EV_RADIATION, 5)
         case (AGE_WANDER);   cond = recent(EV_WANDERERS, 10) .and. .not. had_age(AGE_WANDER)
         case default;        cond = .false.
         end select
      end function cond
   end subroutine ages

   logical function recent(kind, years)
      ! did an event of this kind happen within the last few years?
      integer, intent(in) :: kind, years
      recent = .false.
      if (kind < 1 .or. kind > NK) return
      if (tlast(kind) < 0) return
      recent = tick - tlast(kind) <= int(years, i8)*TPY
   end function recent

   function card(a) result(s)
      ! the title card of an Age
      integer, intent(in) :: a
      character(len=:), allocatable :: s
      hv = hh(a, world_seed, tk())
      s = 'Here begins the Age of '//trim(AGE_WORD(a))//'. '
      select case (a)
      case (AGE_WANDER)
         s = s//pk('Little ships of five cells sail the empty lands, and the peoples learn ' // &
                   'that the world is wide.', 'The first wanderers go out, and no land is far.')
      case (AGE_MANY)
         s = s//pk('The rules of life branch like a great tree; peoples beyond counting ' // &
                   'share the world.', 'Every valley has its own people now.')
      case (AGE_GREY)
         s = s//pk('Plague walks the crowded lands, and the living fear their neighbours.', &
                   'The Grey is everywhere; the towns are full of coughing.')
      case (AGE_ICE)
         s = s//pk('The white has come down from the poles, and the peoples huddle at the ' // &
                   'warm girdle of the world.', 'More than half the world lies under ice.')
      case (AGE_FIRE)
         s = s//pk('The green lands burn, one after another, and ash is the seed of the ' // &
                   'next spring.', 'Smoke hangs over the world.')
      case (AGE_TITAN)
         s = s//pk('The Old Machines build their roads, and the peoples walk where they lead.', &
                   'A Titan builds its highway across the world.')
      case (AGE_WONDER)
         s = s//pk('The Hand has moved upon the world, and nothing will be as it was.', &
                   'Signs and wonders: the Hand is near.')
      case (AGE_ONE)
         s = s//pk('One people holds nearly all the world; the others are memories.', &
                   'A single rule covers the earth.')
      case (AGE_SILENCE)
         s = s//pk('The living are few, and the wind blows over empty lands.', &
                   'A great dying has emptied the world.')
      case (AGE_KINGS)
         s = s//pk('Crowns are raised over the peoples, and houses count their kings.', &
                   'Kingdoms and empires divide the land.')
      case (AGE_PROPHETS)
         s = s//pk('Prophets cry in every market, and every faith awaits a sign from the Hand.', &
                   'The world is full of voices foretelling.')
      case (AGE_TRADE)
         s = s//pk('Caravans and pacts bind the realms; grain and salt go where the ' // &
                   'hungry are.', 'The markets of the world are open.')
      case (AGE_WARS)
         s = s//pk('The realms are at war, and the borders burn.', &
                   'Banners and fronts: the realms make war upon each other.')
      case default
         s = s//'The world lies waiting.'
      end select
   end function card

end module rl_chronicle

!=======================================================================
!  rl_render -- the look of the world
!
!  Every view of the map, and the planet seen from orbit, drawn into RGBA
!  byte buffers for the web page (or PPM pictures for headless runs).  The
!  map is an illuminated atlas: land hill-shaded from the north-west and
!  coloured by its plants, ink-dark seas with luminous shelves and a foam
!  line, rivers, Ising frost, clouds with their shadows, and a terminator
!  that sweeps with the sun and shows the shadow of the ring.  The living
!  are jewels in the hues of their peoples, and on the night side they
!  glow like the lights of cities.  Colours are mixed in linear light and
!  encoded through a gamma table; a people's hue is an angle on the OKLCH
!  wheel, so that equal steps of hue look equally different.  The orbit
!  view ray-casts the doughnut once into a lookup table; each frame then
!  only shades it: sunlight and the ring's shadow from the sunlight
!  tables, glinting seas, an atmosphere at the limb, stars behind.
!=======================================================================
module rl_render
   use rl_core
   use rl_soc, only: rowner, pol, npol, front, creed, faiths, nfaith, rfaith, rfaiths, nreg_s, &
                     sanction, VIEW_REALMS, VIEW_FAITHS, VIEW_TRADE
   implicit none
   private

   public :: render_params, render_init, render_tick, render_map, render_orbit, render_snapshot
   public :: render_people_hex

   ! ================================================================ knobs (indices into pv)
   integer :: P_NIGHT = 0, P_CLOUD = 0, P_RELIEF = 0, P_RIVER = 0

   ! ================================================================ fixed numbers
   integer,  parameter :: OW = 640, OH = 400        ! the orbit view, pixels
   integer,  parameter :: NG = 8191                 ! steps of the gamma table ...
   real(sp), parameter :: GMAX = 2, GSC = NG/GMAX   ! ... over linear light 0..GMAX (soft shoulder)
   integer,  parameter :: NHYP = 200, NBAT = 240    ! height tables, a row every 25 m
   real(sp), parameter :: HUEOFF = 30               ! people hue 38 (the founders) is OKLCH 68: gold
   real(sp), parameter :: TAUP = 0.25               ! presence filter: 1/tau, tau = 4 ticks
   integer(i1), parameter :: NFLASH = 2, NEMBER = 3, NSPARK = 2   ! ticks a flash, ember, glint lasts
   real(dp), parameter :: EL0 = 28*DEG              ! orbit camera: elevation above the ring plane,
   real(dp), parameter :: AZ0 = 62*DEG              ! its azimuth from the sun,
   real(dp), parameter :: DCAM = 9.4d0, FPX = 820d0 ! distance (tube radii) and focal length (px)
   real(sp), parameter :: HALO = 0.20               ! thickness of the atmosphere (tube radii)
   integer,  parameter :: DI(8) = [1, 1, 0, -1, -1, -1, 0, 1]   ! E NE N NW W SW S SE
   integer,  parameter :: DJ(8) = [0, 1, 1, 1, 0, -1, -1, -1]

   ! ================================================================ the palette (sRGB)
   integer, parameter :: Q_INK = 1, Q_PARCH = 2, Q_GOLD = 3, Q_VIOLET = 4, Q_EMBER = 5, &
      Q_SNOW = 6, Q_SEAICE = 7, Q_WALL = 8, Q_CLOUD = 9, Q_CHAR = 10, Q_STONE = 11, &
      Q_RIVER = 12, Q_TUNDRA = 13, Q_FOAM = 14, Q_SICK = 15, Q_PEWTER = 16, Q_LOCG = 17, &
      Q_LOCS = 18, Q_GLASS = 19, Q_LEAD = 20, Q_GOLDHI = 21, Q_SLEEP = 22, Q_FIREG = 23, &
      Q_RIVER2 = 24, Q_DIM = 25, NPAL = 25
   integer, parameter :: PAL8(3,NPAL) = reshape([ &
       11,  15,  26,   233, 220, 192,   216, 166,  87,   156, 108, 232,   255, 112,  36, &
      238, 242, 248,   206, 224, 242,   160, 188, 226,   246, 248, 252,    40,  36,  34, &
      194, 184, 160,    58, 122, 176,   126, 122, 110,   168, 206, 212,   150, 176, 112, &
      150, 156, 170,   255, 196,  74,   190, 144,  76,    96,  96, 102,     6,   6,   8, &
      255, 230, 168,   150, 146, 138,   255,  70,  18,    96, 168, 220,    92,  86,  76], [3,NPAL])
   real(sp) :: pal(3,NPAL)                          ! the same in linear light

   ! ================================================================ lookup tables
   logical  :: tables_ok = .false.
   character(len=1) :: genc(0:NG)                   ! linear light -> sRGB byte
   real(sp) :: gdec(0:255)                          ! sRGB byte -> linear light
   real(sp) :: jew(3,0:359,0:15)                    ! a people's colour by hue and lightness level
   real(sp) :: jneu(3,0:15)                         ! the founders' neutral warm white
   real(sp) :: hyp(3,0:NHYP), bat(3,0:NBAT)         ! land by height, sea by depth
   real(sp) :: veg(3,0:63,0:15)                     ! land by verdure (0..1.2) and soil moisture
   real(sp) :: tpl(3,0:200)                         ! temperature -50..50 C, every 0.5 C
   real(sp) :: vpl(3,0:63), wpl(3,0:31), hpl(3,0:31)  ! verdure, soil moisture, humidity views
   real(sp) :: bbd(3,0:31)                          ! blackbody glow, dull red .. white
   real(sp) :: nzs(0:63,0:63), nzw(0:63,0:63)       ! smooth and white noise tiles, 0..1
   real(sp) :: stab(0:63), ptab(0:11), etch(0:15)   ! shimmer wave, plague pulse, furrow etching
   real(sp) :: tsh(0:7,0:7,2), thi(0:7,0:7,2)       ! jewel tiles (4 and 8 px): shade, highlight
   character(len=1) :: A255

   ! ================================================================ the relief layer
   ! rebuilt whenever elev or land change
   real(sp),    allocatable :: sbase(:,:,:)         ! (3,NX,NY) hypsometric tint or depth colour
   real(sp),    allocatable :: shs(:,:)             ! hill-shading (1 = flat ground)
   real(sp),    allocatable :: svw(:,:)             ! weight of the plants' colours (falls with height)
   integer(i1), allocatable :: sfoam(:,:)           ! 2 sea next to land, 1 a cell further out
   integer(i1), allocatable :: ph(:,:)              ! phase of the sea's shimmer
   real(sp),    allocatable :: seen_elev(:,:)
   integer(i1), allocatable :: seen_land(:,:)
   ! rivers, rebuilt whenever flow changes
   real(sp),    allocatable :: rivs(:,:)            ! river strength 0..1 (0: none)
   integer,     allocatable :: rcon(:,:)            ! bit k-1: the river runs toward neighbour k
   real(dp) :: seen_flow = -1, river_thr = 0

   ! ================================================================ memory between ticks
   real(sp),    allocatable :: pres(:,:)            ! presence: exponential average of alive
   integer(i1), allocatable :: tflash(:,:), tember(:,:), tspark(:,:), seen_ice(:,:)
   integer,     allocatable :: prule(:,:)           ! rule of the last life seen in the cell
   logical :: ticked = .false.                      ! has render_tick run since render_init?

   ! ================================================================ work of one frame
   real(sp),    allocatable :: cc(:,:,:)            ! (3,NX,NY) colour of the ground, linear
   real(sp),    allocatable :: lc(:,:,:)            ! (3,NX,NY) colour of a living cell's jewel
   real(sp),    allocatable :: ce(:,:,:)            ! (3,NX,NY) light of the night side (orbit)
   integer(i1), allocatable :: jfl(:,:)             ! jewel edges: 1 W, 2 E, 4 N, 8 S differ
   real(sp),    allocatable :: cal(:,:), fgl(:,:)   ! cloud opacity, glow around fires
   real(sp),    allocatable :: wk(:,:), wk2(:,:), wk3(:,:)   ! scratch fields
   integer,     allocatable :: lab(:,:)             ! labels; lines are drawn where they differ
   integer,     allocatable :: own(:,:), qq(:)      ! stained glass: owner rule, BFS queue
   integer(i1), allocatable :: dst(:,:)
   real(sp),    allocatable :: chh(:), hwt(:), ra(:), rb(:), dlt(:,:)   ! the sun now
   integer,     allocatable :: hk0(:), hk1(:)
   real(sp) :: nlv = 0.09                           ! night light, linear

   ! ================================================================ the orbit lookup table
   real(dp) :: lut_el = -999
   integer  :: nhit = 0, nhal = 0
   integer,  allocatable :: hpix(:), halpix(:)      ! pixel (1-based) of each hit, of each halo pixel
   real(sp), allocatable :: hbt(:,:)                ! (2,nhit) azimuth, tube angle (turns)
   real(sp), allocatable :: hn(:,:)                 ! (4,nhit) cos/sin tube angle, cos/sin azimuth
   real(sp), allocatable :: hv(:,:)                 ! (5,nhit) view vector, n.v, coverage
   real(sp), allocatable :: ohv(:), ohn(:,:)        ! per pixel: halo strength, its normal
   character(len=:), allocatable :: obg             ! the sky behind, encoded

contains

   ! ================================================================ parameters

   subroutine render_params()
      ! the few knobs of the look; none of them is physics, so none is a slider
      P_NIGHT = reg_param('nightlight', 'Night-side light', 'Heavens', 1d0, 0.05d0, 1d0, &
         'How bright the night side of the map is drawn (1: no night at all).', ui=.false.)
      P_CLOUD = reg_param('cloudshow', 'Cloud opacity', 'Climate', 0.9d0, 0d0, 1.5d0, &
         'How opaque the clouds are drawn on the map (0 hides them).', ui=.false.)
      P_RELIEF = reg_param('relief', 'Hill-shading', 'Land', 1d0, 0d0, 2.5d0, &
         'Strength of the hill-shading on the map (a vertical exaggeration).', ui=.false.)
      P_RIVER = reg_param('rivers', 'Rivers drawn', 'Land', 0.035d0, 0d0, 0.15d0, &
         'Fraction of the land, its largest channels, drawn as rivers.', ui=.false.)
   end subroutine render_params

   real(sp) function pval(k, dflt)
      ! a parameter's value, or its default if it was never registered
      integer,  intent(in) :: k
      real(dp), intent(in) :: dflt
      if (k > 0) then
         pval = real(pv(k), sp)
      else
         pval = real(dflt, sp)
      end if
   end function pval

   ! ================================================================ start and tick

   subroutine render_init()
      ! palettes and tables (once), the relief layer, memory reset, the orbit table
      call render_params()
      if (.not. tables_ok) call make_tables()
      call alloc_state()
      pres = real(alive, sp)
      tflash = 0;  tember = 0;  tspark = 0
      seen_ice = ice
      prule = iand(gene, 65535)
      ticked = .false.
      call build_static()
      seen_flow = -1
      call prep_rivers()
      if (.not. allocated(hpix)) call build_orbit(EL0)
   end subroutine render_init

   subroutine render_tick()
      ! per-tick memory: the presence filter, birth flashes, death embers, frost glints
      integer :: i, j
      if (.not. ready()) return
      do j = 1, NY
         do i = 1, NX
            pres(i,j) = pres(i,j) + TAUP*(alive(i,j) - pres(i,j))
            if (born(i,j) /= 0) then
               tflash(i,j) = NFLASH
            else if (tflash(i,j) > 0) then
               tflash(i,j) = tflash(i,j) - 1_i1
            end if
            if (died(i,j) /= 0) then
               tember(i,j) = NEMBER
            else if (tember(i,j) > 0) then
               tember(i,j) = tember(i,j) - 1_i1
            end if
            if (alive(i,j) /= 0) prule(i,j) = iand(gene(i,j), 65535)
            if (ice(i,j) /= seen_ice(i,j)) then
               tspark(i,j) = NSPARK
               seen_ice(i,j) = ice(i,j)
            else if (tspark(i,j) > 0) then
               tspark(i,j) = tspark(i,j) - 1_i1
            end if
         end do
      end do
      ticked = .true.
   end subroutine render_tick

   logical function ready()
      ! are the module's arrays there, and the size of this board?
      ready = .false.
      if (.not. allocated(pres)) return
      ready = size(pres, 1) == NX .and. size(pres, 2) == NY
   end function ready

   subroutine ensure()
      ! make the module usable even if render_init was not called for this board
      if (.not. tables_ok) call make_tables()
      if (.not. ready()) then
         call alloc_state()
         pres = real(alive, sp)
         tflash = 0;  tember = 0;  tspark = 0;  seen_ice = ice
         prule = iand(gene, 65535)
         ticked = .false.
         call build_static()
         seen_flow = -1
      end if
   end subroutine ensure

   subroutine alloc_state()
      ! (re)allocate every board-sized array of the module
      if (allocated(pres)) then
         deallocate(sbase, shs, svw, sfoam, ph, seen_elev, seen_land, rivs, rcon, pres, &
                    tflash, tember, tspark, seen_ice, prule, cc, lc, ce, jfl, cal, fgl, wk, &
                    wk2, wk3, lab, own, qq, dst, chh, hwt, ra, rb, dlt, hk0, hk1)
      end if
      allocate(sbase(3,NX,NY), shs(NX,NY), svw(NX,NY), sfoam(NX,NY), ph(NX,NY))
      allocate(seen_elev(NX,NY), seen_land(NX,NY), rivs(NX,NY), rcon(NX,NY))
      allocate(pres(NX,NY), tflash(NX,NY), tember(NX,NY), tspark(NX,NY), seen_ice(NX,NY))
      allocate(prule(NX,NY), cc(3,NX,NY), lc(3,NX,NY), ce(3,NX,NY), jfl(NX,NY))
      allocate(cal(NX,NY), fgl(NX,NY), wk(NX,NY), wk2(NX,NY), wk3(NX,NY), lab(NX,NY))
      allocate(own(NX,NY), qq(NX*NY), dst(NX,NY))
      allocate(chh(NX), hwt(NX), hk0(NX), hk1(NX), ra(NY), rb(NY), dlt(NHOUR+1,NY))
      rivs = 0;  rcon = 0;  cc = 0;  lc = 0;  ce = 0;  jfl = 0;  cal = 0;  fgl = 0;  lab = 0
   end subroutine alloc_state

   ! ================================================================ colour helpers

   pure real(sp) function lin(c8)
      ! an sRGB byte as linear light
      integer, intent(in) :: c8
      real(sp) :: c
      c = c8/255.
      if (c <= 0.04045) then
         lin = c/12.92
      else
         lin = ((c + 0.055)/1.055)**2.4
      end if
   end function lin

   pure function lin3(c8) result(c)
      ! an sRGB triple as linear light
      integer, intent(in) :: c8(3)
      real(sp) :: c(3)
      c = [lin(c8(1)), lin(c8(2)), lin(c8(3))]
   end function lin3

   pure real(sp) function tosrgb(x)
      ! linear light 0..1 as an sRGB value 0..1
      real(sp), intent(in) :: x
      if (x <= 0.0031308) then
         tosrgb = 12.92*max(0., x)
      else
         tosrgb = 1.055*x**(1/2.4) - 0.055
      end if
   end function tosrgb

   pure real(sp) function smooth(e0, e1, x)
      ! smoothstep from e0 to e1 (e1 < e0 runs downhill)
      real(sp), intent(in) :: e0, e1, x
      real(sp) :: t
      t = min(1., max(0., (x - e0)/(e1 - e0)))
      smooth = t*t*(3 - 2*t)
   end function smooth

   pure function enc(r, g, b) result(q)
      ! a linear colour as four RGBA bytes
      real(sp), intent(in) :: r, g, b
      character(len=4) :: q
      q(1:1) = genc(int(min(GMAX, max(0., r))*GSC + 0.5))
      q(2:2) = genc(int(min(GMAX, max(0., g))*GSC + 0.5))
      q(3:3) = genc(int(min(GMAX, max(0., b))*GSC + 0.5))
      q(4:4) = A255
   end function enc

   subroutine oklch(l, c, hdeg, v, ok)
      ! linear sRGB of the OKLCH colour (l, c, h); ok is false out of gamut
      real(dp), intent(in)  :: l, c, hdeg
      real(dp), intent(out) :: v(3)
      logical,  intent(out) :: ok
      real(dp) :: a, b, l1, m1, s1
      a = c*cos(hdeg*DEG);  b = c*sin(hdeg*DEG)
      l1 = (l + 0.3963377774d0*a + 0.2158037573d0*b)**3
      m1 = (l - 0.1055613458d0*a - 0.0638541728d0*b)**3
      s1 = (l - 0.0894841775d0*a - 1.2914855480d0*b)**3
      v(1) =  4.0767416621d0*l1 - 3.3077115913d0*m1 + 0.2309699292d0*s1
      v(2) = -1.2684380046d0*l1 + 2.6097574011d0*m1 - 0.3413193965d0*s1
      v(3) = -0.0041960863d0*l1 - 0.7034186147d0*m1 + 1.7076147010d0*s1
      ok = all(v >= -1d-5) .and. all(v <= 1 + 1d-5)
   end subroutine oklch

   function okfit(l, c, hdeg) result(v)
      ! the OKLCH colour with chroma reduced until it fits the sRGB gamut
      real(dp), intent(in) :: l, c, hdeg
      real(sp) :: v(3)
      real(dp) :: lo, hi, mid, w(3)
      logical  :: ok
      call oklch(l, c, hdeg, w, ok)
      if (.not. ok) then
         lo = 0;  hi = c
         do while (hi - lo > 1d-4)
            mid = 0.5d0*(lo + hi)
            call oklch(l, mid, hdeg, w, ok)
            if (ok) then
               lo = mid
            else
               hi = mid
            end if
         end do
         call oklch(l, lo, hdeg, w, ok)
      end if
      v = real(min(1d0, max(0d0, w)), sp)
   end function okfit

   integer function hue_of(r)
      ! display hue 0..359 of people r: its own, else the first ancestor's within
      ! six generations; -1 for the founders' neutral white
      integer, intent(in) :: r
      integer :: k, n
      hue_of = -1
      k = r
      do n = 0, 6
         if (ppl(k)%hue >= 0) then
            hue_of = modulo(nint(ppl(k)%hue), 360)
            return
         end if
         k = ppl(k)%parent
         if (k < 0 .or. k > 65535) return
      end do
   end function hue_of

   logical function is_kin(r, hl)
      ! is people r the people hl, or descended from it through either parent?
      integer, intent(in) :: r, hl
      integer :: k, n
      is_kin = .true.
      k = r
      do n = 0, 24
         if (k == hl .or. ppl(k)%mate == hl) return
         k = ppl(k)%parent
         if (k < 0 .or. k > 65535) exit
      end do
      is_kin = .false.
   end function is_kin

   integer function jlevel(g, e)
      ! lightness level 0..15 of a jewel: pale pigments light, the hungry dim
      integer,  intent(in) :: g
      real(sp), intent(in) :: e
      jlevel = max(0, min(15, int(3.5 + 0.55*g_pig(g) + 5*(e - 0.5))))
   end function jlevel

   subroutine body_rgb(rl, lv, r, g, b)
      ! the jewel colour of people rl at lightness level lv
      integer,  intent(in)  :: rl, lv
      real(sp), intent(out) :: r, g, b
      integer :: hh
      hh = hue_of(rl)
      if (hh >= 0) then
         r = jew(1,hh,lv);  g = jew(2,hh,lv);  b = jew(3,hh,lv)
      else
         r = jneu(1,lv);  g = jneu(2,lv);  b = jneu(3,lv)
      end if
   end subroutine body_rgb

   function render_people_hex(rule) result(s)
      ! '#rrggbb' of a people's jewel at middling lightness (for swatches on the page)
      integer, intent(in) :: rule
      character(len=7) :: s
      real(sp) :: r, g, b
      character(len=4) :: q
      if (.not. tables_ok) call make_tables()
      call body_rgb(iand(rule, 65535), 9, r, g, b)
      q = enc(r, g, b)
      write(s, '(a,3z2.2)') '#', iachar(q(1:1)), iachar(q(2:2)), iachar(q(3:3))
   end function render_people_hex

   ! ================================================================ tables

   subroutine make_tables()
      ! every palette and lookup table of the look
      integer  :: k, h, lv, kw, a, b, n
      real(dp) :: l, c
      real(sp) :: x, y, d, v, w, sand, t
      real(sp) :: lush(3,0:63), soil(3)
      integer(i8) :: key
      A255 = char(255)
      do k = 1, NPAL
         pal(:,k) = lin3(PAL8(:,k))
      end do
      ! gamma, with a soft shoulder above linear 0.8
      do k = 0, NG
         x = k/GSC
         if (x > 0.8) x = 0.8 + 0.2*(1 - exp(-(x - 0.8)/0.2))
         genc(k) = char(min(255, nint(255*tosrgb(x))))
      end do
      do k = 0, 255
         gdec(k) = lin(k)
      end do
      ! jewels: OKLCH lightness by level, chroma as high as the gamut allows
      do lv = 0, 15
         l = 0.50d0 + 0.025d0*lv
         c = 0.20d0 - 0.004d0*lv
         do h = 0, 359
            jew(:,h,lv) = okfit(l, c, real(h + HUEOFF, dp))
         end do
         jneu(:,lv) = okfit(l + 0.04d0, 0.028d0, 85d0)
      end do
      ! land by height and sea by depth (25 m steps)
      call ramp([0., 150., 500., 1000., 1600., 2200., 2800., 3300., 3600., 4500., 5000.], &
         reshape([92, 112, 66,  104, 120, 70,  134, 134, 84,  160, 144, 100,  158, 128, 94, &
                  134, 112, 92,  124, 118, 112,  150, 148, 146,  226, 228, 232,  246, 247, 250, &
                  250, 250, 252], [3, 11]), 0., 25., hyp)
      call ramp([0., 120., 400., 1200., 2500., 4000., 6000.], &
         reshape([50, 132, 140,  34, 106, 126,  22, 72, 104,  15, 45, 80,  11, 29, 57, &
                  8, 18, 40,  6, 11, 25], [3, 7]), 0., 25., bat)
      ! plants: bare soil, ochre, olive, green, deep forest; sand where it is dry
      call ramp([0., 0.15, 0.35, 0.6, 0.85, 1.2], &
         reshape([150, 124, 90,  172, 140, 80,  126, 128, 68,  76, 112, 56,  46, 90, 50, &
                  34, 76, 46], [3, 6]), 0., 1.2/63, lush)
      soil = lin3([216, 192, 142])
      do kw = 0, 15
         w = kw/15.
         do k = 0, 63
            v = k*1.2/63
            sand = smooth(0.42, 0.08, w)*(1 - smooth(0.08, 0.45, v))
            veg(:,k,kw) = lush(:,k) + sand*(soil - lush(:,k))
         end do
      end do
      ! temperature, diverging about the freezing point
      call ramp([-50., -35., -20., -10., -3., 0., 5., 12., 20., 28., 36., 50.], &
         reshape([24, 22, 64,  38, 52, 122,  56, 98, 170,  104, 152, 206,  168, 200, 228, &
                  204, 220, 232,  238, 226, 176,  242, 196, 118,  230, 146, 76,  206, 86, 54, &
                  158, 38, 52,  96, 16, 44], [3, 12]), -50., 0.5, tpl)
      call ramp([0., 0.15, 0.3, 0.5, 0.75, 1.0, 1.2], &
         reshape([40, 33, 24,  86, 68, 38,  124, 112, 46,  108, 150, 58,  116, 190, 80, &
                  176, 224, 120,  226, 246, 178], [3, 7]), 0., 1.2/63, vpl)
      call ramp([0., 0.3, 0.55, 0.8, 1.0], reshape([198, 166, 112,  168, 160, 112, &
                  104, 148, 122,  50, 118, 142,  34, 84, 152], [3, 5]), 0., 1./31, wpl)
      call ramp([0., 0.5, 1.0, 1.5], reshape([10, 16, 32,  22, 40, 74,  40, 74, 122, &
                  76, 118, 168], [3, 4]), 0., 1.5/31, hpl)
      call ramp([0., 0.35, 0.6, 0.8, 1.0], reshape([150, 24, 6,  255, 70, 10,  255, 140, 30, &
                  255, 210, 120,  255, 250, 236], [3, 5]), 0., 1./31, bbd)
      ! noise tiles: white, and smooth (a periodic blur of it), both 0..1
      key = mix32(77777_i8)
      do b = 0, 63
         do a = 0, 63
            nzw(a,b) = real(hr2(a, b, key), sp)
         end do
      end do
      nzs = nzw
      do n = 1, 3
         call blur_tile(nzs)
      end do
      nzs = (nzs - minval(nzs))/max(1e-6, maxval(nzs) - minval(nzs))
      do k = 0, 63
         stab(k) = real(sin(TWOPI*k/64), sp)
      end do
      do k = 0, 11
         ptab(k) = 1 - abs(k - 6)/6.
      end do
      etch = [0.86, 0.64, 0.76, 0.58, 0.82, 0.68, 0.72, 0.60, &
              0.86, 0.64, 0.76, 0.58, 0.82, 0.68, 0.72, 0.60]
      ! jewel tiles: a gradient lit from the north-west and a highlight near that corner
      tsh = 1;  thi = 0
      do b = 0, 3
         do a = 0, 3
            tsh(a,b,1) = 1.08 - 0.05*(a + b)
         end do
      end do
      thi(1,1,1) = 0.62;  thi(0,1,1) = 0.18;  thi(1,0,1) = 0.18;  thi(2,1,1) = 0.10
      thi(1,2,1) = 0.10;  thi(0,0,1) = 0.08
      do b = 0, 7
         do a = 0, 7
            tsh(a,b,2) = 1.10 - 0.028*(a + b)
            d = sqrt((a - 2.)**2 + (b - 2.)**2)
            t = max(0., 1 - d/1.7)
            thi(a,b,2) = 0.75*t*t + 0.10*max(0., 1 - d/4.)
         end do
      end do
      y = 0
      tables_ok = .true.
   end subroutine make_tables

   subroutine ramp(xs, cs, x0, dx, tab)
      ! tab(:,k) at x0 + k*dx, interpolated in linear light between sRGB stops (xs, cs)
      real(sp), intent(in)  :: xs(:)
      integer,  intent(in)  :: cs(:,:)
      real(sp), intent(in)  :: x0, dx
      real(sp), intent(out) :: tab(:,0:)
      integer  :: k, m, n
      real(sp) :: x, t
      n = size(xs)
      do k = 0, ubound(tab, 2)
         x = x0 + k*dx
         m = 1
         do while (m < n - 1 .and. x > xs(m+1))
            m = m + 1
         end do
         t = min(1., max(0., (x - xs(m))/(xs(m+1) - xs(m))))
         tab(:,k) = (1 - t)*lin3(cs(:,m)) + t*lin3(cs(:,m+1))
      end do
   end subroutine ramp

   subroutine blur_tile(f)
      ! a 3x3 box blur of a periodic 64x64 tile
      real(sp), intent(inout) :: f(0:63,0:63)
      real(sp) :: g(0:63,0:63)
      integer :: a, b
      do b = 0, 63
         do a = 0, 63
            g(a,b) = (f(modulo(a-1,64),b) + f(a,b) + f(modulo(a+1,64),b))/3
         end do
      end do
      do b = 0, 63
         do a = 0, 63
            f(a,b) = (g(a,modulo(b-1,64)) + g(a,b) + g(a,modulo(b+1,64)))/3
         end do
      end do
   end subroutine blur_tile

   subroutine blur(f, r)
      ! box blur of radius r along x, then along y, on the torus (in place)
      real(sp), intent(inout) :: f(:,:)
      integer,  intent(in)    :: r
      real(sp) :: row(NX), s(NX), q
      integer  :: i, j, k
      q = 1./(2*r + 1)
      do j = 1, NY
         row = f(:,j)
         s(1) = 0
         do k = -r, r
            s(1) = s(1) + row(wrapi(1 + k))
         end do
         do i = 2, NX
            s(i) = s(i-1) + row(wrapi(i + r)) - row(wrapi(i - 1 - r))
         end do
         f(:,j) = s*q
      end do
      wk3 = f
      s = 0
      do k = -r, r
         s = s + wk3(:,wrapj(1 + k))
      end do
      f(:,1) = s*q
      do j = 2, NY
         s = s + wk3(:,wrapj(j + r)) - wk3(:,wrapj(j - 1 - r))
         f(:,j) = s*q
      end do
   end subroutine blur

   ! ================================================================ the relief layer

   subroutine check_static()
      ! rebuild the relief layer if the land has been sculpted, and the rivers if flow moved
      if (any(elev /= seen_elev) .or. any(land /= seen_land)) then
         call build_static()
         seen_flow = -1
      end if
      call prep_rivers()
   end subroutine check_static

   subroutine build_static()
      ! hypsometric and depth colours, hill-shading from the north-west, foam, plant weight
      real(sp), parameter :: LX = -0.5417, LY = 0.5417, LZ = 0.6428
      integer  :: i, j, k, a, b, nl
      real(sp) :: e, gx, gy, kk, sx, sy, sh, lap
      do j = 1, NY
         do i = 1, NX
            e = elev(i,j)
            gx = 0.5*(elev(ip(i),j) - elev(im(i),j))
            gy = 0.5*(elev(i,jp(j)) - elev(i,jm(j)))
            lap = elev(ip(i),j) + elev(im(i),j) + elev(i,jp(j)) + elev(i,jm(j)) - 4*e
            if (land(i,j) >= 1) then
               kk = 1./240
               k = min(NHYP, max(0, nint(e/25)))
               sbase(:,i,j) = hyp(:,k)
               svw(i,j) = 1 - smooth(1700., 3300., e)
            else
               kk = 1./700
               k = min(NBAT, max(0, nint(-e/25)))
               sbase(:,i,j) = bat(:,k)
               svw(i,j) = 0
            end if
            sx = -kk*gx;  sy = -kk*gy
            sh = (sx*LX + sy*LY + LZ)/(sqrt(sx*sx + sy*sy + 1)*LZ)
            sh = sh*(1 + max(-0.12, min(0.12, kk*lap*0.35)))     ! ridges catch light, valleys less
            shs(i,j) = max(0.25, min(1.6, sh))
            ph(i,j) = int(iand(int(190*nzs(iand(i,63), iand(j,63))) + 2*i + j, 63), i1)
         end do
      end do
      do j = 1, NY
         do i = 1, NX
            sfoam(i,j) = 0
            if (land(i,j) /= 0) cycle
            nl = 0
            do b = -2, 2
               do a = -2, 2
                  if (land(wrapi(i + a), wrapj(j + b)) /= 0) then
                     if (abs(a) <= 1 .and. abs(b) <= 1) then
                        nl = 2
                     else
                        nl = max(nl, 1)
                     end if
                  end if
               end do
            end do
            sfoam(i,j) = int(nl, i1)
         end do
      end do
      seen_elev = elev;  seen_land = land
   end subroutine build_static

   subroutine prep_rivers()
      ! the largest channels of the flow become rivers: strength and the way they run
      integer, parameter :: NB = 48
      integer  :: hist(0:NB-1), i, j, k, kk, nland, acc, ii, jj
      real(dp) :: s, want
      real(sp) :: f, best, x
      s = sum(real(flow, dp))
      if (s == seen_flow) return
      seen_flow = s
      rivs = 0;  rcon = 0
      if (s <= 0) return
      hist = 0;  nland = 0
      do j = 1, NY
         do i = 1, NX
            if (land(i,j) /= 1) cycle
            nland = nland + 1
            if (flow(i,j) <= 0) cycle
            k = max(0, min(NB-1, int(4*log(real(flow(i,j), dp))/log(2d0)) + 16))
            hist(k) = hist(k) + 1
         end do
      end do
      want = pval(P_RIVER, 0.035d0)*nland
      acc = 0
      river_thr = huge(1d0)
      do k = NB - 1, 0, -1
         acc = acc + hist(k)
         if (acc > want) exit
         river_thr = 2d0**((k - 16)/4d0)
      end do
      if (want < 1) river_thr = huge(1d0)
      do j = 1, NY
         do i = 1, NX
            if (land(i,j) /= 1 .or. flow(i,j) <= river_thr) cycle
            rivs(i,j) = real(min(1d0, 0.3d0 + 0.22d0*log(flow(i,j)/river_thr)/log(2d0)), sp)
         end do
      end do
      ! each river cell runs to its lowest neighbour that is river or sea
      do j = 1, NY
         do i = 1, NX
            if (rivs(i,j) <= 0) cycle
            best = elev(i,j);  kk = 0
            do k = 1, 8
               ii = wrapi(i + DI(k));  jj = wrapj(j + DJ(k))
               if (land(ii,jj) == 1 .and. rivs(ii,jj) <= 0) cycle
               x = elev(ii,jj)
               if (land(ii,jj) /= 1) x = min(x, -1.)
               if (x < best) then
                  best = x;  kk = k
               end if
            end do
            if (kk == 0) cycle
            rcon(i,j) = ibset(rcon(i,j), kk - 1)
            ii = wrapi(i + DI(kk));  jj = wrapj(j + DJ(kk))
            if (rivs(ii,jj) > 0) rcon(ii,jj) = ibset(rcon(ii,jj), mod(kk + 3, 8))
         end do
      end do
      f = 0
   end subroutine prep_rivers

   ! ================================================================ sky, sun, fire

   subroutine prep_clouds()
      ! cloud opacity: the cloud field blurred, given ragged edges by drifting noise
      real(sp) :: cs, x
      integer  :: i, j, t1, t2
      cs = pval(P_CLOUD, 1d0)
      if (cs <= 0) then
         cal = 0
         return
      end if
      wk = cloud
      call blur(wk, 2)
      call blur(wk, 1)
      t1 = int(mod(tick/3, 64_i8));  t2 = int(mod(tick/5, 64_i8))
      do j = 1, NY
         do i = 1, NX
            x = wk(i,j) + 0.42*(nzs(iand(i + t1, 63), iand(j, 63)) - 0.5) &
                        + 0.12*(nzw(iand(i - t2, 63), iand(j + 7, 63)) - 0.5)
            cal(i,j) = cs*0.8*smooth(0.68, 1.05, x)       ! only thick weather shows
         end do
      end do
   end subroutine prep_clouds

   subroutine prep_fire()
      ! the red glow that spills from burning cells onto their neighbours
      integer :: i, j, a, b
      fgl = 0
      if (.not. any(fire > 0)) return
      do j = 1, NY
         do i = 1, NX
            if (fire(i,j) <= 0) cycle
            do b = -2, 2
               do a = -2, 2
                  fgl(wrapi(i + a), wrapj(j + b)) = fgl(wrapi(i + a), wrapj(j + b)) + &
                     0.22/(1 + a*a + b*b)
               end do
            end do
         end do
      end do
      fgl = min(fgl, 1.)
   end subroutine prep_fire

   subroutine prep_sun()
      ! the sun now: hour angle of every column and the sunlight of the season, per row
      integer  :: i, j, ks, ks2, k0
      real(dp) :: dec, hh, x, fs
      real(sp) :: w
      dec = tilt*sin(TWOPI*season_frac())
      fs = season_frac()*NSEAS
      ks = min(NSEAS - 1, int(fs));  ks2 = mod(ks + 1, NSEAS)
      w = real(fs - ks, sp)
      do j = 1, NY
         ra(j) = real(cos(theta_of(j))*cos(dec), sp)
         rb(j) = real(sin(theta_of(j))*sin(dec), sp)
         dlt(1:NHOUR,j) = (1 - w)*daylit(j,:,ks) + w*daylit(j,:,ks2)
         dlt(NHOUR+1,j) = dlt(1,j)
      end do
      do i = 1, NX
         hh = modulo(phi_of(i) - sunlon, TWOPI)
         chh(i) = real(cos(hh), sp)
         x = hh/TWOPI*NHOUR
         k0 = min(NHOUR - 1, int(x))
         hk0(i) = k0 + 1;  hk1(i) = k0 + 2
         hwt(i) = real(x - k0, sp)
      end do
      nlv = pval(P_NIGHT, 0.3d0)**2
   end subroutine prep_sun

   pure real(sp) function daylight(c, dl)
      ! how lit the map is: a soft terminator from the sun's height (c = cos of its zenith
      ! angle), dimmed by the shadow of the ring (dl, the sunlight table there)
      real(sp), intent(in) :: c, dl
      real(sp) :: s, t
      daylight = smooth(-0.07, 0.14, c)
      if (c > 0) then
         s = min(1., dl/max(c, 0.04))
         t = min(1., c/0.08)
         daylight = daylight*(s*t + 1 - t)
      end if
   end function daylight

   ! ================================================================ the views, cell by cell

   subroutine pass_living(hl, fine, orb)
      ! LIVING.  Map: the lit ground into cc, the jewels of the living into lc and their
      ! edges into jfl.  Orbit (orb): daylight colours with life blended in, into cc, and
      ! the lights of the night side (life, fire, embers) into ce.
      integer, intent(in) :: hl
      logical, intent(in) :: fine, orb
      real(sp) :: r, g, b, x, a, v, rel, hs, ca, sa, day, c, dl, tw, mr, mg, mb, lm
      real(sp) :: br, bg, bb, er, eg, eb, al, y
      integer  :: i, j, kv, kw, rl, lv, tk3, tkp, gg, fl
      logical  :: lens
      rel = pval(P_RELIEF, 1d0)
      lens = hl >= 0
      call prep_clouds()
      call prep_fire()
      call prep_sun()
      tk3 = int(mod(3*tick, 64_i8))
      tkp = int(mod(tick, 12_i8))
      do j = 1, NY
         do i = 1, NX
            ! ---- the ground
            if (land(i,j) == 0) then
               hs = 1 + 0.4*rel*(shs(i,j) - 1)
               x = hs*(1 + 0.05*stab(iand(ph(i,j) + tk3, 63)))
               r = sbase(1,i,j)*x;  g = sbase(2,i,j)*x;  b = sbase(3,i,j)*x
               if (sfoam(i,j) > 0) then
                  a = 0.15*sfoam(i,j)
                  r = r + a*(pal(1,Q_FOAM) - r)
                  g = g + a*(pal(2,Q_FOAM) - g)
                  b = b + a*(pal(3,Q_FOAM) - b)
               end if
            else if (land(i,j) == 2) then
               r = pal(1,Q_STONE);  g = pal(2,Q_STONE);  b = pal(3,Q_STONE)
               if (.not. fine .and. furrow(i,j) >= 16) then
                  x = 0.5 + 0.5*etch(iand(furrow(i,j) - 16, 15))
                  r = r*x;  g = g*x;  b = b*x
               end if
            else
               v = min(1.2, max(0., verd(i,j)))
               kv = int(v*52.5 + 0.5)
               kw = int(min(1., max(0., wet(i,j)))*15 + 0.5)
               r = veg(1,kv,kw);  g = veg(2,kv,kw);  b = veg(3,kv,kw)
               a = smooth(5., -6., temp(i,j))*(1 - smooth(0.2, 0.55, v))
               if (a > 0) then
                  r = r + a*(pal(1,Q_TUNDRA) - r)
                  g = g + a*(pal(2,Q_TUNDRA) - g)
                  b = b + a*(pal(3,Q_TUNDRA) - b)
               end if
               a = svw(i,j)
               r = sbase(1,i,j) + a*(r - sbase(1,i,j))
               g = sbase(2,i,j) + a*(g - sbase(2,i,j))
               b = sbase(3,i,j) + a*(b - sbase(3,i,j))
               if (ash(i,j) > 0.01) then
                  a = min(0.85, 1.1*ash(i,j))
                  r = r + a*(pal(1,Q_CHAR) - r)
                  g = g + a*(pal(2,Q_CHAR) - g)
                  b = b + a*(pal(3,Q_CHAR) - b)
               end if
               if (.not. fine .and. furrow(i,j) >= 16) then
                  x = etch(iand(furrow(i,j) - 16, 15))
                  r = r*x;  g = g*x;  b = b*x
               end if
               hs = max(0.3, 1 + rel*(shs(i,j) - 1))
               r = r*hs;  g = g*hs;  b = b*hs
               if (.not. fine .and. rivs(i,j) > 0) then
                  a = 0.35 + 0.6*rivs(i,j)
                  r = r + a*(pal(1,Q_RIVER) - r)
                  g = g + a*(pal(2,Q_RIVER) - g)
                  b = b + a*(pal(3,Q_RIVER) - b)
               end if
            end if
            ! ---- frost: crystalline white, the domain walls a shade darker, glints where it flipped
            if (ice(i,j) > 0) then
               if (land(i,j) == 0) then
                  a = 0.62 + 0.3*smooth(0., -12., temp(i,j))
                  br = pal(1,Q_SEAICE);  bg = pal(2,Q_SEAICE);  bb = pal(3,Q_SEAICE)
               else
                  a = 0.80 + 0.15*smooth(0., -10., temp(i,j))
                  x = max(0.55, 1 + 0.7*rel*(shs(i,j) - 1))
                  br = pal(1,Q_SNOW)*x;  bg = pal(2,Q_SNOW)*x;  bb = pal(3,Q_SNOW)*x
               end if
               if (ice(ip(i),j) < 0 .or. ice(im(i),j) < 0 .or. ice(i,jp(j)) < 0 &
                   .or. ice(i,jm(j)) < 0) then
                  br = 0.86*pal(1,Q_WALL);  bg = 0.86*pal(2,Q_WALL);  bb = 0.86*pal(3,Q_WALL)
               end if
               x = 0.94 + 0.08*nzw(iand(i,63), iand(j,63))
               r = r + a*(br*x - r);  g = g + a*(bg*x - g);  b = b + a*(bb*x - b)
               if (tspark(i,j) > 0 .and. .not. fine) then
                  if (nzw(iand(i + 17,63), iand(j + 5,63)) < 0.5) then
                     r = r + 0.35;  g = g + 0.38;  b = b + 0.42
                  end if
               end if
            end if
            ! ---- clouds and their shadows (a cloud to the north-west shades the ground)
            sa = cal(im(i),jp(j))
            ca = cal(i,j)
            x = 1 - 0.32*sa
            r = r*x;  g = g*x;  b = b*x
            if (ca > 0) then
               x = 1 - 0.18*ca
               r = r + ca*(pal(1,Q_CLOUD)*x - r)
               g = g + ca*(pal(2,Q_CLOUD)*x - g)
               b = b + ca*(pal(3,Q_CLOUD)*x - b)
            end if
            ! ---- what glows of itself: fire, the glow about it, embers of the dead
            er = 0;  eg = 0;  eb = 0
            if (fire(i,j) > 0) then
               kv = merge(30, 19, fire(i,j) >= 2)
               x = merge(1.5, 1.1, fire(i,j) >= 2)
               er = bbd(1,kv)*x;  eg = bbd(2,kv)*x;  eb = bbd(3,kv)*x
               r = r*0.3;  g = g*0.3;  b = b*0.3
            else if (fgl(i,j) > 0) then
               er = pal(1,Q_FIREG)*fgl(i,j);  eg = pal(2,Q_FIREG)*fgl(i,j)
               eb = pal(3,Q_FIREG)*fgl(i,j)
            end if
            if (tember(i,j) > 0 .and. alive(i,j) == 0) then
               x = 0.22*tember(i,j)/real(NEMBER)
               er = er + x*pal(1,Q_EMBER);  eg = eg + x*pal(2,Q_EMBER);  eb = eb + x*pal(3,Q_EMBER)
            end if
            ! ---- the living
            if (alive(i,j) /= 0) then
               gg = gene(i,j);  rl = iand(gg, 65535)
               lv = jlevel(gg, energy(i,j))
               call body_rgb(rl, lv, br, bg, bb)
               if (sick(i,j) > 0) then
                  a = 0.38 + 0.3*ptab(mod(tkp + 5*strain(i,j), 12))
                  br = br + a*(pal(1,Q_SICK) - br)
                  bg = bg + a*(pal(2,Q_SICK) - bg)
                  bb = bb + a*(pal(3,Q_SICK) - bb)
               else if (sick(i,j) < 0) then
                  br = br + 0.25*(pal(1,Q_PEWTER) - br)
                  bg = bg + 0.25*(pal(2,Q_PEWTER) - bg)
                  bb = bb + 0.25*(pal(3,Q_PEWTER) - bb)
               end if
               if (orb) then
                  r = r + 0.85*(br - r);  g = g + 0.85*(bg - g);  b = b + 0.85*(bb - b)
                  er = er + 0.7*br;  eg = eg + 0.62*bg;  eb = eb + 0.5*bb
               else
                  if (tflash(i,j) > 0) then
                     a = 0.5*tflash(i,j)/real(NFLASH)
                     br = br + a*(1 - br);  bg = bg + a*(1 - bg);  bb = bb + a*(1 - bb)
                  end if
                  if (ticked) then
                     al = 0.62 + 0.38*pres(i,j)
                  else
                     al = 1
                  end if
                  if (lens) then
                     if (is_kin(rl, hl)) then
                        br = min(1., 1.2*br);  bg = min(1., 1.2*bg);  bb = min(1., 1.2*bb)
                     else
                        y = 0.3*br + 0.6*bg + 0.1*bb
                        br = 0.3*y;  bg = 0.3*y;  bb = 0.3*y
                     end if
                  end if
                  lc(1,i,j) = br;  lc(2,i,j) = bg;  lc(3,i,j) = bb
                  lc(:,i,j) = lc(:,i,j)*al          ! weight; blended below with the lit ground
                  wk2(i,j) = al
                  fl = 0
                  if (alive(im(i),j) == 0 .or. iand(gene(im(i),j), 65535) /= rl) fl = fl + 1
                  if (alive(ip(i),j) == 0 .or. iand(gene(ip(i),j), 65535) /= rl) fl = fl + 2
                  if (alive(i,jp(j)) == 0 .or. iand(gene(i,jp(j)), 65535) /= rl) fl = fl + 4
                  if (alive(i,jm(j)) == 0 .or. iand(gene(i,jm(j)), 65535) /= rl) fl = fl + 8
                  jfl(i,j) = int(fl, i1)
               end if
            else if (pres(i,j) > 0.03) then
               ! soft tissue where life flickers: the presence of the recently living
               call body_rgb(prule(i,j), 8, br, bg, bb)
               a = 0.5*pres(i,j)
               if (lens) then
                  if (is_kin(prule(i,j), hl)) then
                     a = min(0.9, 1.4*a)
                  else
                     a = 0.25*a
                  end if
               end if
               if (orb) then
                  r = r + a*(br - r);  g = g + a*(bg - g);  b = b + a*(bb - b)
                  er = er + 0.6*a*br;  eg = eg + 0.55*a*bg;  eb = eb + 0.45*a*bb
               else
                  wk(i,j) = a
                  lc(1,i,j) = br;  lc(2,i,j) = bg;  lc(3,i,j) = bb
               end if
            end if
            if (orb) then
               cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
               ce(1,i,j) = er;  ce(2,i,j) = eg;  ce(3,i,j) = eb
               cycle
            end if
            ! ---- night: the terminator, the ring's shadow, a warm twilight band
            c = ra(j)*chh(i) + rb(j)
            dl = dlt(hk0(i),j)*(1 - hwt(i)) + dlt(hk1(i),j)*hwt(i)
            day = daylight(c, dl)
            tw = 4*day*(1 - day)
            mr = nlv*0.70 + (1 - nlv)*day
            mg = nlv*0.82 + (1 - nlv)*day*(1 - 0.14*tw)
            mb = nlv*1.20 + (1 - nlv)*day*(1 - 0.30*tw)
            if (lens) then
               mr = 0.42*mr;  mg = 0.42*mg;  mb = 0.42*mb
            end if
            r = r*mr + er;  g = g*mg + eg;  b = b*mb + eb
            lm = day + (1 - day)*0.62                ! the living glow at night
            if (alive(i,j) /= 0) then
               al = wk2(i,j)
               br = lc(1,i,j)*lm;  bg = lc(2,i,j)*lm*0.97;  bb = lc(3,i,j)*lm*0.92
               x = 0.3*ca*al
               br = br + x*(pal(1,Q_CLOUD)*mr - br)
               bg = bg + x*(pal(2,Q_CLOUD)*mg - bg)
               bb = bb + x*(pal(3,Q_CLOUD)*mb - bb)
               lc(1,i,j) = br + (1 - al)*r
               lc(2,i,j) = bg + (1 - al)*g
               lc(3,i,j) = bb + (1 - al)*b
            else if (pres(i,j) > 0.03) then
               a = wk(i,j)
               r = r + a*(lc(1,i,j)*lm - r)
               g = g + a*(lc(2,i,j)*lm - g)
               b = b + a*(lc(3,i,j)*lm - b)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
         end do
      end do
   end subroutine pass_living

   subroutine relief_rgb(i, j, s, r, g, b)
      ! plain shaded relief of a cell (hypsometric tint, depth colour), hill-shading s
      integer,  intent(in)  :: i, j
      real(sp), intent(in)  :: s
      real(sp), intent(out) :: r, g, b
      real(sp) :: hs
      if (land(i,j) == 0) then
         hs = 1 + 0.4*s*(shs(i,j) - 1)
      else
         hs = max(0.3, 1 + s*(shs(i,j) - 1))
      end if
      r = sbase(1,i,j)*hs;  g = sbase(2,i,j)*hs;  b = sbase(3,i,j)*hs
      if (land(i,j) == 2) then
         r = pal(1,Q_STONE);  g = pal(2,Q_STONE);  b = pal(3,Q_STONE)
      end if
   end subroutine relief_rgb

   subroutine pass_relief(fine)
      ! RELIEF: terrain only, the shaded relief of an atlas with its rivers and foam
      logical, intent(in) :: fine
      real(sp) :: r, g, b, a, rel
      integer  :: i, j
      rel = 1.25*pval(P_RELIEF, 1d0)
      do j = 1, NY
         do i = 1, NX
            call relief_rgb(i, j, rel, r, g, b)
            if (land(i,j) == 0 .and. sfoam(i,j) > 0) then
               a = 0.15*sfoam(i,j)
               r = r + a*(pal(1,Q_FOAM) - r)
               g = g + a*(pal(2,Q_FOAM) - g)
               b = b + a*(pal(3,Q_FOAM) - b)
            end if
            if (.not. fine .and. rivs(i,j) > 0) then
               a = 0.35 + 0.6*rivs(i,j)
               r = r + a*(pal(1,Q_RIVER) - r)
               g = g + a*(pal(2,Q_RIVER) - g)
               b = b + a*(pal(3,Q_RIVER) - b)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
            lab(i,j) = 0
         end do
      end do
   end subroutine pass_relief

   subroutine pass_climate()
      ! CLIMATE: temperature in a diverging palette; labels for isotherms every 5 C,
      ! the freezing line and the coast
      real(sp) :: t, hs, rel
      integer  :: i, j, k
      rel = 0.5*pval(P_RELIEF, 1d0)
      do j = 1, NY
         do i = 1, NX
            t = temp(i,j)
            k = max(0, min(200, int((t + 50)*2 + 0.5)))
            if (land(i,j) >= 1) then
               hs = max(0.4, 1 + rel*(shs(i,j) - 1))
            else
               hs = 0.80
            end if
            cc(:,i,j) = tpl(:,k)*hs
            lab(i,j) = climate_label(t, land(i,j) >= 1)
         end do
      end do
   end subroutine pass_climate

   pure integer function climate_label(t, island)
      ! isotherm band (5 C), frozen or not, land or sea, packed into one label
      real(sp), intent(in) :: t
      logical,  intent(in) :: island
      climate_label = max(0, min(63, floor(t/5) + 20))
      if (t < 0) climate_label = climate_label + 64
      if (island) climate_label = climate_label + 128
   end function climate_label

   subroutine pass_water(fine)
      ! WATER: soil moisture on land, humidity over the sea, rain as a pale veil, rivers
      logical, intent(in) :: fine
      real(sp) :: r, g, b, a, hs, rel
      integer  :: i, j, k
      rel = 0.5*pval(P_RELIEF, 1d0)
      do j = 1, NY
         do i = 1, NX
            if (land(i,j) >= 1) then
               k = max(0, min(31, int(wet(i,j)*31 + 0.5)))
               hs = max(0.4, 1 + rel*(shs(i,j) - 1))
               r = wpl(1,k)*hs;  g = wpl(2,k)*hs;  b = wpl(3,k)*hs
            else
               k = max(0, min(31, int(humid(i,j)/1.5*31 + 0.5)))
               r = hpl(1,k);  g = hpl(2,k);  b = hpl(3,k)
            end if
            a = min(0.55, rain(i,j)/14)
            if (a > 0) then
               r = r + a*(0.55 - r);  g = g + a*(0.72 - g);  b = b + a*(0.95 - b)
            end if
            if (.not. fine .and. rivs(i,j) > 0) then
               a = 0.5 + 0.5*rivs(i,j)
               r = r + a*(pal(1,Q_RIVER2) - r)
               g = g + a*(pal(2,Q_RIVER2) - g)
               b = b + a*(pal(3,Q_RIVER2) - b)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
            lab(i,j) = 128*min(1, int(land(i,j)))
         end do
      end do
   end subroutine pass_water

   subroutine pass_frost()
      ! FROST: the Ising spins themselves, crisp black and white; glints where they flipped
      integer :: i, j
      do j = 1, NY
         do i = 1, NX
            if (ice(i,j) > 0) then
               if (land(i,j) >= 1) then
                  cc(:,i,j) = [0.86, 0.86, 0.86]
               else
                  cc(:,i,j) = [0.74, 0.80, 0.88]
               end if
            else
               if (land(i,j) >= 1) then
                  cc(:,i,j) = [0.016, 0.016, 0.016]
               else
                  cc(:,i,j) = [0.004, 0.006, 0.012]
               end if
            end if
            if (tspark(i,j) > 0) cc(:,i,j) = 0.5*cc(:,i,j) + 0.5*pal(:,Q_GOLD)
            lab(i,j) = merge(1, 0, ice(i,j) > 0) + 128*min(1, int(land(i,j)))
         end do
      end do
   end subroutine pass_frost

   subroutine pass_verdure()
      ! VERDURE: the food plants in a sequential palette, ash, fire and the ploughed furrows
      real(sp) :: r, g, b, a, hs, rel, v
      integer  :: i, j, k
      rel = 0.6*pval(P_RELIEF, 1d0)
      do j = 1, NY
         do i = 1, NX
            if (land(i,j) >= 1) then
               v = min(1.2, max(0., verd(i,j)))
               k = int(v*52.5 + 0.5)
               hs = max(0.4, 1 + rel*(shs(i,j) - 1))
               r = vpl(1,k)*hs;  g = vpl(2,k)*hs;  b = vpl(3,k)*hs
               if (ash(i,j) > 0.01) then
                  a = min(0.8, ash(i,j))
                  r = r + a*(0.16 - r);  g = g + a*(0.07 - g);  b = b + a*(0.07 - b)
               end if
               if (furrow(i,j) >= 16) then
                  r = r*1.15 + 0.02;  g = g*1.08 + 0.01
               end if
               if (fire(i,j) > 0) then
                  r = 1.0;  g = 0.35;  b = 0.05
               end if
            else
               r = 0.4*sbase(1,i,j);  g = 0.4*sbase(2,i,j);  b = 0.4*sbase(3,i,j)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
            lab(i,j) = 128*min(1, int(land(i,j)))
         end do
      end do
   end subroutine pass_verdure

   subroutine pass_awe()
      ! AWE: reverence in gold, dread in violet, each on a soft aura of its domain
      real(sp) :: r, g, b, a, x
      integer  :: i, j
      wk = 0
      do j = 1, NY
         do i = 1, NX
            if (alive(i,j) /= 0) wk(i,j) = awe(i,j)
         end do
      end do
      call blur(wk, 2)
      call blur(wk, 2)
      do j = 1, NY
         do i = 1, NX
            call relief_rgb(i, j, 0.6, r, g, b)
            r = 0.22*r;  g = 0.22*g;  b = 0.22*b
            x = wk(i,j)
            a = min(0.55, 1.6*abs(x))
            if (x > 0) then
               r = r + a*(0.45*pal(1,Q_GOLD) - r)
               g = g + a*(0.45*pal(2,Q_GOLD) - g)
               b = b + a*(0.45*pal(3,Q_GOLD) - b)
            else if (x < 0) then
               r = r + a*(0.45*pal(1,Q_VIOLET) - r)
               g = g + a*(0.45*pal(2,Q_VIOLET) - g)
               b = b + a*(0.45*pal(3,Q_VIOLET) - b)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
            if (alive(i,j) /= 0) then
               select case (awe(i,j))
               case (1)
                  lc(:,i,j) = 1.1*pal(:,Q_GOLD)
               case (-1)
                  lc(:,i,j) = 1.1*pal(:,Q_VIOLET)
               case default
                  lc(:,i,j) = pal(:,Q_DIM)
               end select
               call edges(i, j)
            end if
         end do
      end do
   end subroutine pass_awe

   subroutine pass_plague()
      ! PLAGUE: the infected in the colour of their strain, the immune in pewter,
      ! the healthy dim; a soft aura marks each outbreak
      real(sp) :: r, g, b, a
      integer  :: i, j, hh
      wk = 0;  wk2 = 0;  cal = 0
      do j = 1, NY
         do i = 1, NX
            if (alive(i,j) /= 0 .and. sick(i,j) > 0) then
               hh = strain_hue(int(strain(i,j)))
               wk(i,j) = jew(1,hh,9);  wk2(i,j) = jew(2,hh,9);  cal(i,j) = jew(3,hh,9)
            end if
         end do
      end do
      call blur(wk, 2);  call blur(wk2, 2);  call blur(cal, 2)
      do j = 1, NY
         do i = 1, NX
            call relief_rgb(i, j, 0.6, r, g, b)
            a = 0.22
            r = a*r + 1.4*wk(i,j);  g = a*g + 1.4*wk2(i,j);  b = a*b + 1.4*cal(i,j)
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
            if (alive(i,j) /= 0) then
               if (sick(i,j) > 0) then
                  hh = strain_hue(int(strain(i,j)))
                  lc(:,i,j) = jew(:,hh,12)
               else if (sick(i,j) < 0) then
                  lc(:,i,j) = 0.55*pal(:,Q_PEWTER)
               else
                  lc(:,i,j) = 0.7*pal(:,Q_DIM)
               end if
               call edges(i, j)
            end if
         end do
      end do
      cal = 0
   end subroutine pass_plague

   pure integer function strain_hue(k)
      ! a hue of its own for each strain (golden angle)
      integer, intent(in) :: k
      strain_hue = modulo(nint(95 + 137.508d0*k), 360)
   end function strain_hue

   subroutine edges(i, j)
      ! jewel edges of a living cell for the views that colour cells by something else
      integer, intent(in) :: i, j
      integer :: fl
      fl = 0
      if (alive(im(i),j) == 0) fl = fl + 1
      if (alive(ip(i),j) == 0) fl = fl + 2
      if (alive(i,jp(j)) == 0) fl = fl + 4
      if (alive(i,jm(j)) == 0) fl = fl + 8
      jfl(i,j) = int(fl, i1)
      wk3(i,j) = 1
   end subroutine edges

   subroutine pass_rules()
      ! RULES: each cell tinted by the automaton that governs it ("Conway all the way down")
      real(sp), parameter :: TINT(3,7) = reshape([0.90, 0.80, 0.55,  0.32, 0.78, 0.22, &
         1.00, 0.30, 0.04,  0.78, 0.22, 0.80,  1.00, 0.72, 0.08,  0.28, 0.55, 1.00, &
         0.00, 0.00, 0.00], [3, 7])
      real(sp) :: r, g, b
      integer  :: i, j, k, c
      wk = 0
      do k = 1, nloc
         i = wrapi(nint(lx(k)));  j = wrapj(nint(ly(k)))
         wk(i,j) = 1
      end do
      do j = 1, NY
         do i = 1, NX
            call relief_rgb(i, j, 0.6, r, g, b)
            r = 0.30*r;  g = 0.30*g;  b = 0.30*b
            if (fire(i,j) > 0) then
               c = 3
            else if (alive(i,j) /= 0 .and. sick(i,j) > 0) then
               c = 2
            else if (alive(i,j) /= 0) then
               c = 1
            else if (wk(i,j) > 0) then
               c = 5
            else if (furrow(i,j) >= 16) then
               c = 4
            else if (ice(i,j) > 0) then
               c = 6
            else
               c = 7
            end if
            if (c < 7) then
               r = r + 0.8*(TINT(1,c) - r)
               g = g + 0.8*(TINT(2,c) - g)
               b = b + 0.8*(TINT(3,c) - b)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
            lab(i,j) = c
         end do
      end do
   end subroutine pass_rules

   subroutine pass_purist()
      ! PURIST: white cells on black, the classic look
      integer :: i, j
      do j = 1, NY
         do i = 1, NX
            if (alive(i,j) /= 0) then
               cc(:,i,j) = 0.92
            else
               cc(:,i,j) = 0.0025
            end if
            lab(i,j) = 0
         end do
      end do
   end subroutine pass_purist

   ! ================================================================ society's views

   subroutine glow_fronts()
      ! the fronts of wars smoulder under the living; where a cell has just fallen at a
      ! border (xenophobia, war) the ground flashes white-hot
      integer  :: i, j
      real(sp) :: f, a
      if (.not. allocated(front)) return
      f = 0.75 + 0.25*sin(0.35*real(modulo(tick, 1000_i8), sp))
      do j = 1, NY
         do i = 1, NX
            if (died(i,j) == 2) then
               a = 0.8
               cc(1,i,j) = cc(1,i,j) + a*(1.00 - cc(1,i,j))
               cc(2,i,j) = cc(2,i,j) + a*(0.86 - cc(2,i,j))
               cc(3,i,j) = cc(3,i,j) + a*(0.62 - cc(3,i,j))
            else if (front(i,j) /= 0 .and. land(i,j) >= 1) then
               a = 0.42*f
               cc(1,i,j) = cc(1,i,j) + a*(0.95 - cc(1,i,j))
               cc(2,i,j) = cc(2,i,j) + a*(0.28 - cc(2,i,j))
               cc(3,i,j) = cc(3,i,j) + a*(0.10 - cc(3,i,j))
            end if
         end do
      end do
   end subroutine glow_fronts

   integer function owner_at(i, j)
      ! the realm holding cell (i,j), 0 if none
      integer, intent(in) :: i, j
      integer :: r
      owner_at = 0
      if (.not. allocated(rowner)) return
      r = region(i,j)
      if (r >= 1 .and. r <= nreg_s) owner_at = rowner(r)
      if (owner_at < 0 .or. owner_at > npol) owner_at = 0
   end function owner_at

   subroutine dim_ground(i, j, r, g, b)
      ! unclaimed land and sea, drawn dark so the realms and faiths stand out
      integer,  intent(in)  :: i, j
      real(sp), intent(out) :: r, g, b
      if (land(i,j) >= 1) then
         call relief_rgb(i, j, 0.8, r, g, b)
         r = 0.34*r;  g = 0.34*g;  b = 0.34*b
      else
         r = 0.42*sbase(1,i,j);  g = 0.42*sbase(2,i,j);  b = 0.42*sbase(3,i,j)
      end if
   end subroutine dim_ground

   subroutine mark_seats(which)
      ! gold marks: the seats of the realms (1) or the holy sites of the faiths (2)
      integer, intent(in) :: which
      integer :: k, r, a, b, i, j
      integer, parameter :: MI(5) = [0, 1, -1, 0, 0], MJ(5) = [0, 0, 0, 1, -1]
      do k = 1, merge(npol, nfaith, which == 1)
         if (which == 1) then
            if (pol(k)%state /= 1) cycle
            r = pol(k)%capital
         else
            if (faiths(k)%state /= 1) cycle
            r = faiths(k)%holy
         end if
         if (r < 1 .or. r > nregion) cycle
         do a = 1, 5
            i = wrapi(regs(r)%cx + MI(a));  j = wrapj(regs(r)%cy + MJ(a))
            b = merge(Q_GOLDHI, Q_GOLD, a == 1)
            cc(1,i,j) = pal(1,b);  cc(2,i,j) = pal(2,b);  cc(3,i,j) = pal(3,b)
         end do
      end do
   end subroutine mark_seats

   subroutine pass_realms()
      ! REALMS: every region in the arms of the realm that holds it, lead lines at its
      ! borders, the living a little brighter, the fronts of its wars aglow, seats in gold
      integer  :: i, j, p, hh
      real(sp) :: r, g, b, x, f, a
      f = 0.75 + 0.25*sin(0.35*real(modulo(tick, 1000_i8), sp))
      do j = 1, NY
         do i = 1, NX
            p = owner_at(i, j)
            if (land(i,j) >= 1 .and. p > 0) then
               hh = modulo(nint(pol(p)%hue), 360)
               x = 0.86 + 0.16*nzw(iand(i,63), iand(j,63))
               if (alive(i,j) /= 0) x = x*1.25
               r = jew(1,hh,7)*x;  g = jew(2,hh,7)*x;  b = jew(3,hh,7)*x
               if (front(i,j) /= 0) then
                  a = 0.55*f
                  r = r + a*(0.98 - r);  g = g + a*(0.30 - g);  b = b + a*(0.10 - b)
               end if
               lab(i,j) = p + 3
            else
               call dim_ground(i, j, r, g, b)
               lab(i,j) = merge(2, 1, land(i,j) >= 1)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
         end do
      end do
      call mark_seats(1)
   end subroutine pass_realms

   subroutine pass_faiths()
      ! FAITHS: each believer in the colour of its creed, every land region washed in the
      ! creed most held there, lead lines between the domains of faith, holy sites in gold
      integer  :: i, j, f, r, hh
      real(sp) :: rr, g, b, x
      do j = 1, NY
         do i = 1, NX
            f = 0
            if (alive(i,j) /= 0) f = creed(i,j)
            r = region(i,j)
            if (land(i,j) >= 1 .and. f >= 1 .and. f <= nfaith) then
               hh = modulo(nint(faiths(f)%hue), 360)
               x = 0.95 + 0.1*nzw(iand(i,63), iand(j,63))
               rr = jew(1,hh,11)*x;  g = jew(2,hh,11)*x;  b = jew(3,hh,11)*x
               lab(i,j) = f + 3
            else if (land(i,j) >= 1 .and. r >= 1 .and. r <= nreg_s) then
               if (rfaith(r) >= 1 .and. rfaith(r) <= nfaith) then
                  hh = modulo(nint(faiths(rfaith(r))%hue), 360)
                  x = 0.45 + 0.4*min(1., rfaiths(r))
                  rr = jew(1,hh,4)*x;  g = jew(2,hh,4)*x;  b = jew(3,hh,4)*x
                  lab(i,j) = rfaith(r) + 3
               else
                  call dim_ground(i, j, rr, g, b)
                  lab(i,j) = 2
               end if
            else
               call dim_ground(i, j, rr, g, b)
               lab(i,j) = merge(2, 1, land(i,j) >= 1)
            end if
            cc(1,i,j) = rr;  cc(2,i,j) = g;  cc(3,i,j) = b
         end do
      end do
      call mark_seats(2)
   end subroutine pass_faiths

   subroutine pass_trade()
      ! TRADE: each realm by how it lives -- deep teal the self-sufficient, gold those
      ! that live by trade, a red cast on the embargoed, darkened by famine
      integer  :: i, j, p, k
      real(sp) :: r, g, b, d, x, s, em
      do j = 1, NY
         do i = 1, NX
            p = owner_at(i, j)
            if (land(i,j) >= 1 .and. p > 0) then
               d = real(min(1d0, 2*pol(p)%depend), sp)
               x = 0.85 + 0.15*nzw(iand(i,63), iand(j,63))
               if (alive(i,j) /= 0) x = x*1.2
               r = (0.12 + d*(0.93 - 0.12))*x
               g = (0.42 + d*(0.72 - 0.42))*x
               b = (0.46 + d*(0.28 - 0.46))*x
               em = 0
               do k = 1, npol
                  if (sanction(k,p) /= 0) em = em + 1
               end do
               if (em > 0) then
                  s = min(0.6, 0.25*em)
                  r = r + s*(0.85 - r);  g = g + s*(0.18 - g);  b = b + s*(0.16 - b)
               end if
               s = real(1 - 0.6*min(1d0, pol(p)%shortfall), sp)
               r = r*s;  g = g*s;  b = b*s
               lab(i,j) = p + 3
            else
               call dim_ground(i, j, r, g, b)
               lab(i,j) = merge(2, 1, land(i,j) >= 1)
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
         end do
      end do
      call mark_seats(1)
   end subroutine pass_trade

   subroutine pass_peoples(hl)
      ! PEOPLES, the stained glass: every land cell takes the people of the nearest
      ! living cell within 6 cells (multi-source BFS); notable peoples in their own
      ! glass, the rest grey; lead lines wherever the owner changes
      integer, intent(in) :: hl
      integer  :: i, j, k, n, qh, qt, ii, jj, d, rl, hh
      real(sp) :: r, g, b, x, y
      own = -1;  dst = 127_i1
      qt = 0
      do j = 1, NY
         do i = 1, NX
            if (alive(i,j) /= 0) then
               own(i,j) = iand(gene(i,j), 65535);  dst(i,j) = 0_i1
               qt = qt + 1;  qq(qt) = i + NX*(j - 1)
            end if
         end do
      end do
      qh = 0
      do while (qh < qt)
         qh = qh + 1
         k = qq(qh);  i = mod(k - 1, NX) + 1;  j = (k - 1)/NX + 1
         d = dst(i,j)
         if (d >= 6) cycle
         do n = 1, 8
            ii = wrapi(i + DI(n));  jj = wrapj(j + DJ(n))
            if (land(ii,jj) == 0 .or. dst(ii,jj) <= d + 1) cycle
            dst(ii,jj) = int(d + 1, i1);  own(ii,jj) = own(i,j)
            qt = qt + 1;  qq(qt) = ii + NX*(jj - 1)
         end do
      end do
      do j = 1, NY
         do i = 1, NX
            rl = own(i,j)
            if (rl >= 0) then
               x = 0.90 + 0.18*nzw(iand(i,63), iand(j,63))
               if (alive(i,j) /= 0) x = x*1.22
               if (ppl(rl)%state >= 1 .and. ppl(rl)%hue >= 0) then
                  hh = modulo(nint(ppl(rl)%hue), 360)
                  r = jew(1,hh,5)*x;  g = jew(2,hh,5)*x;  b = jew(3,hh,5)*x
               else
                  r = pal(1,Q_GLASS)*x;  g = pal(2,Q_GLASS)*x;  b = pal(3,Q_GLASS)*x
               end if
               if (hl >= 0) then
                  if (is_kin(rl, hl)) then
                     r = 1.2*r;  g = 1.2*g;  b = 1.2*b
                  else
                     y = 0.3*r + 0.6*g + 0.1*b
                     r = 0.3*y;  g = 0.3*y;  b = 0.3*y
                  end if
               end if
               lab(i,j) = rl + 3
            else if (land(i,j) >= 1) then
               call relief_rgb(i, j, 0.8, r, g, b)
               r = 0.30*r;  g = 0.30*g;  b = 0.30*b
               lab(i,j) = 2
            else
               r = 0.45*sbase(1,i,j);  g = 0.45*sbase(2,i,j);  b = 0.45*sbase(3,i,j)
               lab(i,j) = 1
            end if
            cc(1,i,j) = r;  cc(2,i,j) = g;  cc(3,i,j) = b
         end do
      end do
   end subroutine pass_peoples

   ! ================================================================ the map, pixel by pixel

   subroutine render_map(view, zoom, cx, cy, hl, buf, w, h)
      ! one view of the map as RGBA bytes, north up: zoom 1 shows the whole torus at
      ! 2 px/cell, zoom 2 or 4 a window about the cell (cx, cy) at 2*zoom px/cell, wrapping.
      ! Pixel (px, py) shows cell i = cx - NX/(2z) + 1 + px/(2z), j = cy + NY/(2z) - py/(2z).
      integer, intent(in) :: view, zoom, cx, cy, hl
      character(len=:), allocatable, intent(inout) :: buf
      integer, intent(out) :: w, h
      integer :: z, i0, j0
      call ensure()
      z = 1
      if (zoom >= 2) z = 2
      if (zoom >= 4) z = 4
      w = 2*NX;  h = 2*NY
      if (allocated(buf)) then
         if (len(buf) /= 4*w*h) deallocate(buf)
      end if
      if (.not. allocated(buf)) allocate(character(len=4*w*h) :: buf)
      i0 = cx - NX/(2*z) + 1
      j0 = cy + NY/(2*z)
      call check_static()
      select case (view)
      case (VIEW_PEOPLES)
         call pass_peoples(hl)
         call pix_flat(VIEW_PEOPLES, z, .false., i0, j0, buf, w, h)
      case (VIEW_CLIMATE)
         call pass_climate()
         call pix_flat(VIEW_CLIMATE, z, .true., i0, j0, buf, w, h)
      case (VIEW_WATER)
         call pass_water(z > 1)
         call pix_flat(VIEW_WATER, z, .true., i0, j0, buf, w, h)
      case (VIEW_FROST)
         call pass_frost()
         call pix_flat(VIEW_FROST, z, .false., i0, j0, buf, w, h)
      case (VIEW_VERDURE)
         call pass_verdure()
         call pix_flat(VIEW_VERDURE, z, .true., i0, j0, buf, w, h)
      case (VIEW_AWE)
         call pass_awe()
         call pix_jewels(z, i0, j0, buf, w, h, .false.)
      case (VIEW_PLAGUE)
         call pass_plague()
         call pix_jewels(z, i0, j0, buf, w, h, .false.)
      case (VIEW_RULES)
         call pass_rules()
         call pix_flat(VIEW_RULES, z, .false., i0, j0, buf, w, h)
         call draw_titans(z, i0, j0, buf, w, h)
      case (VIEW_PURIST)
         call pass_purist()
         call pix_flat(VIEW_PURIST, z, .false., i0, j0, buf, w, h)
      case (VIEW_RELIEF)
         call pass_relief(z > 1)
         call pix_flat(VIEW_RELIEF, z, .true., i0, j0, buf, w, h)
      case (VIEW_REALMS)
         call pass_realms()
         call pix_flat(VIEW_PEOPLES, z, .false., i0, j0, buf, w, h)
      case (VIEW_FAITHS)
         call pass_faiths()
         call pix_flat(VIEW_PEOPLES, z, .false., i0, j0, buf, w, h)
      case (VIEW_TRADE)
         call pass_trade()
         call pix_flat(VIEW_PEOPLES, z, .false., i0, j0, buf, w, h)
      case default
         call pass_living(hl, z > 1, .false.)
         call glow_fronts()
         call pix_jewels(z, i0, j0, buf, w, h, .true.)
         call draw_locusts(z, i0, j0, buf, w, h)
         call draw_titans(z, i0, j0, buf, w, h)
      end select
   end subroutine render_map

   subroutine pix_jewels(z, i0, j0, buf, w, h, living)
      ! the ground (smooth when zoomed) with the living drawn on it as jewels: zoom 1 a
      ! 2x2 tile per cell (highlight to the north-west, rim to the south-east), zoomed a
      ! bevelled gem with rounded corners wherever it borders other people or nothing
      integer, intent(in) :: z, i0, j0, w, h
      character(len=*), intent(inout) :: buf
      logical, intent(in) :: living
      integer  :: a, b, i, j, ir, jb, o1, o2, rl, s, px, py, i2, j2, xx, yy, fl, t, o
      integer  :: col(0:w-1), ci2(0:w-1), sx(0:w-1)
      real(sp) :: wx(0:w-1)
      real(sp) :: r, g, bl, vx, vy, w00, w10, w01, w11, x, br, bg, bb
      logical  :: dr, db, dd, cut, rim
      character(len=4) :: q, qh, qm, qr
      if (z == 1) then
         do a = 0, NX - 1
            col(a) = wrapi(i0 + a)
         end do
         do b = 0, NY - 1
            j = wrapj(j0 - b);  jb = jm(j)
            o1 = 8*b*w;  o2 = o1 + 4*w
            do a = 0, NX - 1
               i = col(a)
               o = 8*a
               if (alive(i,j) == 0) then
                  q = enc(cc(1,i,j), cc(2,i,j), cc(3,i,j))
                  buf(o1+o+1:o1+o+4) = q;  buf(o1+o+5:o1+o+8) = q
                  buf(o2+o+1:o2+o+4) = q;  buf(o2+o+5:o2+o+8) = q
               else
                  ir = ip(i)
                  if (living) then
                     rl = iand(gene(i,j), 65535)
                     dr = alive(ir,j) == 0
                     if (.not. dr) dr = iand(gene(ir,j), 65535) /= rl
                     db = alive(i,jb) == 0
                     if (.not. db) db = iand(gene(i,jb), 65535) /= rl
                     dd = alive(ir,jb) == 0
                     if (.not. dd) dd = iand(gene(ir,jb), 65535) /= rl
                  else
                     dr = alive(ir,j) == 0;  db = alive(i,jb) == 0;  dd = alive(ir,jb) == 0
                  end if
                  r = lc(1,i,j);  g = lc(2,i,j);  bl = lc(3,i,j)
                  qh = enc(r + 0.42*(1 - r), g + 0.42*(1 - g), bl + 0.42*(1 - bl))
                  q = enc(r, g, bl)
                  qm = enc(0.72*r, 0.72*g, 0.72*bl)
                  qr = enc(0.46*r, 0.46*g, 0.46*bl)
                  buf(o1+o+1:o1+o+4) = qh
                  if (dr) then
                     buf(o1+o+5:o1+o+8) = qm
                  else
                     buf(o1+o+5:o1+o+8) = q
                  end if
                  if (db) then
                     buf(o2+o+1:o2+o+4) = qm
                  else
                     buf(o2+o+1:o2+o+4) = q
                  end if
                  if (dr .or. db .or. dd) then
                     buf(o2+o+5:o2+o+8) = qr
                  else
                     buf(o2+o+5:o2+o+8) = q
                  end if
               end if
            end do
         end do
         return
      end if
      ! zoomed: bilinear ground, jewel tiles, rivers and furrows drawn finely
      s = 2*z
      t = merge(1, 2, s == 4)
      do px = 0, w - 1
         a = px/s;  xx = mod(px, s)
         col(px) = wrapi(i0 + a);  sx(px) = xx
         x = (xx + 0.5)/s - 0.5
         if (x < 0) then
            ci2(px) = im(col(px));  wx(px) = -x
         else
            ci2(px) = ip(col(px));  wx(px) = x
         end if
      end do
      do py = 0, h - 1
         b = py/s;  yy = mod(py, s)
         j = wrapj(j0 - b)
         x = (yy + 0.5)/s - 0.5
         if (x < 0) then
            j2 = jp(j);  vy = -x
         else
            j2 = jm(j);  vy = x
         end if
         o1 = 4*py*w
         do px = 0, w - 1
            i = col(px);  i2 = ci2(px);  vx = wx(px);  xx = sx(px)
            w00 = (1 - vx)*(1 - vy);  w10 = vx*(1 - vy);  w01 = (1 - vx)*vy;  w11 = vx*vy
            r = w00*cc(1,i,j) + w10*cc(1,i2,j) + w01*cc(1,i,j2) + w11*cc(1,i2,j2)
            g = w00*cc(2,i,j) + w10*cc(2,i2,j) + w01*cc(2,i,j2) + w11*cc(2,i2,j2)
            bl = w00*cc(3,i,j) + w10*cc(3,i2,j) + w01*cc(3,i,j2) + w11*cc(3,i2,j2)
            if (living) then
               if (furrow(i,j) >= 16) then
                  if (btest(furrow(i,j), 0)) then
                     x = merge(etch(iand(furrow(i,j) - 16, 15)), 0.94, btest(xx, 0))
                  else
                     x = merge(etch(iand(furrow(i,j) - 16, 15)), 0.94, btest(yy, 0))
                  end if
                  if (land(i,j) == 2) x = 0.5 + 0.5*x
                  r = r*x;  g = g*x;  bl = bl*x
               else if (land(i,j) == 2) then
                  x = 0.9 + 0.18*nzw(iand(px,63), iand(py,63))
                  r = r*x;  g = g*x;  bl = bl*x
               end if
               if (rcon(i,j) /= 0) call river_px(i, j, xx, yy, s, r, g, bl)
               if (tspark(i,j) > 0 .and. ice(i,j) > 0) then
                  if (nzw(iand(px + 3*py, 63), iand(py, 63)) < 0.12) then
                     r = r + 0.5;  g = g + 0.52;  bl = bl + 0.55
                  end if
               end if
            end if
            if (alive(i,j) /= 0) then
               fl = jfl(i,j)
               cut = .false.;  rim = .false.
               if (xx == 0 .and. btest(fl, 0)) rim = .true.
               if (xx == s - 1 .and. btest(fl, 1)) rim = .true.
               if (yy == 0 .and. btest(fl, 2)) rim = .true.
               if (yy == s - 1 .and. btest(fl, 3)) rim = .true.
               cut = corner(xx, yy, s, fl)
               if (.not. cut) then
                  br = lc(1,i,j);  bg = lc(2,i,j);  bb = lc(3,i,j)
                  if (rim) then
                     if ((xx == 0 .and. btest(fl, 0)) .or. (yy == 0 .and. btest(fl, 2))) then
                        x = 0.62
                     else
                        x = 0.40
                     end if
                     r = br*x;  g = bg*x;  bl = bb*x
                  else
                     x = tsh(xx,yy,t)
                     r = br*x;  g = bg*x;  bl = bb*x
                     x = thi(xx,yy,t)
                     r = r + x*(1 - r);  g = g + x*(1 - g);  bl = bl + x*(1 - bl)
                  end if
               end if
            end if
            buf(o1+4*px+1:o1+4*px+4) = enc(r, g, bl)
         end do
      end do
   end subroutine pix_jewels

   pure logical function corner(xx, yy, s, fl)
      ! is pixel (xx, yy) of an s-pixel jewel tile cut off by a rounded corner?
      integer, intent(in) :: xx, yy, s, fl
      integer :: a, b
      logical :: hx, hy
      corner = .false.
      if (xx < s/2) then
         a = xx;  hx = btest(fl, 0)
      else
         a = s - 1 - xx;  hx = btest(fl, 1)
      end if
      if (yy < s/2) then
         b = yy;  hy = btest(fl, 2)
      else
         b = s - 1 - yy;  hy = btest(fl, 3)
      end if
      if (.not. (hx .and. hy)) return
      if (s <= 4) then
         corner = a == 0 .and. b == 0
      else
         corner = a + b <= 1
      end if
   end function corner

   subroutine river_px(i, j, xx, yy, s, r, g, b)
      ! a river drawn as a line through the cell toward the neighbours it runs to and from
      integer,  intent(in)    :: i, j, xx, yy, s
      real(sp), intent(inout) :: r, g, b
      integer  :: k
      real(sp) :: px, py, dx, dy, t, d, dmin, wid, a
      px = (xx + 0.5)/s - 0.5;  py = 0.5 - (yy + 0.5)/s
      dmin = 9
      do k = 1, 8
         if (.not. btest(rcon(i,j), k - 1)) cycle
         dx = 0.5*DI(k);  dy = 0.5*DJ(k)
         t = max(0., min(1., (px*dx + py*dy)/(dx*dx + dy*dy)))
         d = (px - t*dx)**2 + (py - t*dy)**2
         dmin = min(dmin, d)
      end do
      if (dmin > 1) return
      wid = (0.16 + 0.22*rivs(i,j))*s
      a = min(1., max(0., 0.5*wid + 0.5 - sqrt(dmin)*s))*(0.55 + 0.45*rivs(i,j))
      r = r + a*(pal(1,Q_RIVER) - r)
      g = g + a*(pal(2,Q_RIVER) - g)
      b = b + a*(pal(3,Q_RIVER) - b)
   end subroutine river_px

   subroutine pix_flat(view, z, smoothed, i0, j0, buf, w, h)
      ! a cell-coloured view: smooth (bilinear) or crisp when zoomed, with lines drawn
      ! wherever the labels of neighbouring pixels differ (isotherms, coasts, lead, walls)
      integer, intent(in) :: view, z, i0, j0, w, h
      logical, intent(in) :: smoothed
      character(len=*), intent(inout) :: buf
      integer  :: col(0:w-1), ci2(0:w-1), sx(0:w-1), lrow(-1:w,0:2)
      real(sp) :: wx(0:w-1)
      integer  :: px, py, a, b, i, j, j2, i2, s, xx, yy, o1, st, k0, k1, k2, la
      real(sp) :: r, g, bl, vx, vy, w00, w10, w01, w11, x, lr, lg, lb, al
      s = 2*z
      do px = 0, w - 1
         a = px/s;  xx = mod(px, s)
         col(px) = wrapi(i0 + a);  sx(px) = xx
         x = (xx + 0.5)/s - 0.5
         if (x < 0) then
            ci2(px) = im(col(px));  wx(px) = -x
         else
            ci2(px) = ip(col(px));  wx(px) = x
         end if
      end do
      call label_row(-1, lrow(:,0))
      call label_row(0, lrow(:,1))
      do py = 0, h - 1
         k0 = mod(py, 3);  k1 = mod(py + 1, 3);  k2 = mod(py + 2, 3)
         call label_row(py + 1, lrow(:,k2))
         b = py/s;  yy = mod(py, s)
         j = wrapj(j0 - b)
         x = (yy + 0.5)/s - 0.5
         if (x < 0) then
            j2 = jp(j);  vy = -x
         else
            j2 = jm(j);  vy = x
         end if
         if (.not. smoothed .or. z == 1) vy = 0
         o1 = 4*py*w
         do px = 0, w - 1
            i = col(px)
            if (smoothed .and. z > 1) then
               i2 = ci2(px);  vx = wx(px)
               w00 = (1 - vx)*(1 - vy);  w10 = vx*(1 - vy);  w01 = (1 - vx)*vy;  w11 = vx*vy
               r = w00*cc(1,i,j) + w10*cc(1,i2,j) + w01*cc(1,i,j2) + w11*cc(1,i2,j2)
               g = w00*cc(2,i,j) + w10*cc(2,i2,j) + w01*cc(2,i,j2) + w11*cc(2,i2,j2)
               bl = w00*cc(3,i,j) + w10*cc(3,i2,j) + w01*cc(3,i,j2) + w11*cc(3,i2,j2)
               if ((view == VIEW_WATER .or. view == VIEW_RELIEF) .and. rcon(i,j) /= 0) &
                  call river_px(i, j, sx(px), yy, s, r, g, bl)
            else
               r = cc(1,i,j);  g = cc(2,i,j);  bl = cc(3,i,j)
            end if
            if (view == VIEW_PURIST .and. z > 1) then
               if (sx(px) == s - 1 .or. yy == s - 1) then
                  r = r + 0.012;  g = g + 0.012;  bl = bl + 0.016
               end if
            end if
            la = lrow(px,k1)
            st = max(lstyle(view, la, lrow(px+1,k1)), lstyle(view, la, lrow(px,k2)))
            st = max(st, bold(lstyle(view, la, lrow(px-1,k1))), &
                     bold(lstyle(view, la, lrow(px,k0))))
            if (st > 0) then
               call line_rgb(st, lr, lg, lb, al)
               r = r + al*(lr - r);  g = g + al*(lg - g);  bl = bl + al*(lb - bl)
            end if
            buf(o1+4*px+1:o1+4*px+4) = enc(r, g, bl)
         end do
      end do
   contains
      subroutine label_row(py_, row)
         ! labels of the pixels of row py_ (with one pixel either side, wrapping)
         integer, intent(in)  :: py_
         integer, intent(out) :: row(-1:w)
         integer  :: p, jj, jj2, yy_, ii, q
         real(sp) :: y_, wy_, t_, lf, wx_
         if (py_ < 0 .or. py_ >= h) then
            q = modulo(py_, h)
         else
            q = py_
         end if
         jj = wrapj(j0 - q/s);  yy_ = mod(q, s)
         y_ = (yy_ + 0.5)/s - 0.5
         if (y_ < 0) then
            jj2 = jp(jj);  wy_ = -y_
         else
            jj2 = jm(jj);  wy_ = y_
         end if
         do p = 0, w - 1
            ii = col(p)
            if (view == VIEW_CLIMATE .and. z > 1) then
               wx_ = wx(p)
               t_ = (1 - wx_)*(1 - wy_)*temp(ii,jj) + wx_*(1 - wy_)*temp(ci2(p),jj) &
                  + (1 - wx_)*wy_*temp(ii,jj2) + wx_*wy_*temp(ci2(p),jj2)
               lf = (1 - wx_)*(1 - wy_)*min(1, int(land(ii,jj))) &
                  + wx_*(1 - wy_)*min(1, int(land(ci2(p),jj))) &
                  + (1 - wx_)*wy_*min(1, int(land(ii,jj2))) + wx_*wy_*min(1, int(land(ci2(p),jj2)))
               row(p) = climate_label(t_, lf > 0.5)
            else
               row(p) = lab(ii,jj)
            end if
         end do
         row(-1) = row(w-1);  row(w) = row(0)
      end subroutine label_row
   end subroutine pix_flat

   pure integer function lstyle(view, a, b)
      ! the line between two pixels with labels a and b: 0 none, 1 isotherm, 2 coast,
      ! 3 freezing line (bold), 4 lead, 5 domain wall
      integer, intent(in) :: view, a, b
      lstyle = 0
      if (a == b) return
      select case (view)
      case (VIEW_CLIMATE)
         if (btest(a, 6) .neqv. btest(b, 6)) then
            lstyle = 3
         else if (btest(a, 7) .neqv. btest(b, 7)) then
            lstyle = 2
         else
            lstyle = 1
         end if
      case (VIEW_PEOPLES)
         lstyle = 4
      case (VIEW_FROST)
         if (btest(a, 0) .neqv. btest(b, 0)) then
            lstyle = 5
         else
            lstyle = 2
         end if
      case (VIEW_WATER, VIEW_VERDURE)
         lstyle = 2
      end select
   end function lstyle

   pure integer function bold(st)
      ! only bold lines are drawn on both sides of a boundary
      integer, intent(in) :: st
      bold = 0
      if (st == 3 .or. st == 4) bold = st
   end function bold

   subroutine line_rgb(st, r, g, b, a)
      ! colour and opacity of a line style
      integer,  intent(in)  :: st
      real(sp), intent(out) :: r, g, b, a
      select case (st)
      case (1)
         r = 0.02;  g = 0.02;  b = 0.03;  a = 0.30
      case (2)
         r = 0.01;  g = 0.012;  b = 0.02;  a = 0.55
      case (3)
         r = 0.004;  g = 0.006;  b = 0.016;  a = 0.92
      case (4)
         r = pal(1,Q_LEAD);  g = pal(2,Q_LEAD);  b = pal(3,Q_LEAD);  a = 0.96
      case default
         r = 0.05;  g = 0.30;  b = 0.75;  a = 1.0
      end select
   end subroutine line_rgb

   ! ================================================================ sprites

   subroutine blend_px(buf, w, h, px, py, r, g, b, a, add)
      ! mix (or, with add, add) a linear colour into one pixel of the buffer
      character(len=*), intent(inout) :: buf
      integer,  intent(in) :: w, h, px, py
      real(sp), intent(in) :: r, g, b, a
      logical,  intent(in) :: add
      integer  :: o
      real(sp) :: cr, cg, cb
      if (px < 0 .or. px >= w .or. py < 0 .or. py >= h) return
      o = 4*(py*w + px)
      cr = gdec(iachar(buf(o+1:o+1)));  cg = gdec(iachar(buf(o+2:o+2)))
      cb = gdec(iachar(buf(o+3:o+3)))
      if (add) then
         cr = cr + a*r;  cg = cg + a*g;  cb = cb + a*b
      else
         cr = cr + a*(r - cr);  cg = cg + a*(g - cg);  cb = cb + a*(b - cb)
      end if
      buf(o+1:o+4) = enc(cr, cg, cb)
   end subroutine blend_px

   subroutine screen_xy(x, y, z, i0, j0, xs, ys)
      ! screen position (pixels, continuous) of a board position (cells; centres at integers)
      real(sp), intent(in)  :: x, y
      integer,  intent(in)  :: z, i0, j0
      real(sp), intent(out) :: xs, ys
      real(sp) :: u, v
      u = modulo(x - (i0 - 0.5), real(NX, sp))
      v = modulo((j0 + 0.5) - y, real(NY, sp))
      xs = u*2*z;  ys = v*2*z
   end subroutine screen_xy

   subroutine draw_locusts(z, i0, j0, buf, w, h)
      ! amber dots with short trails along their heading; the gregarious brighter
      integer, intent(in) :: z, i0, j0, w, h
      character(len=*), intent(inout) :: buf
      integer  :: k, n, a, b, px, py, nt
      real(sp) :: xs, ys, dx, dy, r, g, bl, al, rad
      if (nloc <= 0) return
      nt = 2 + z
      rad = 0.6*z
      do k = 1, min(nloc, MAXLOCUST)
         call screen_xy(lx(k), ly(k), z, i0, j0, xs, ys)
         if (xs >= w + 4 .or. ys >= h + 4) cycle
         if (lphase(k) > 0) then
            r = pal(1,Q_LOCG);  g = pal(2,Q_LOCG);  bl = pal(3,Q_LOCG);  al = 1
         else
            r = pal(1,Q_LOCS);  g = pal(2,Q_LOCS);  bl = pal(3,Q_LOCS);  al = 0.75
         end if
         dx = cos(lth(k));  dy = -sin(lth(k))
         do n = nt, 1, -1
            px = int(xs - n*dx*0.9*z);  py = int(ys - n*dy*0.9*z)
            call blend_px(buf, w, h, wrapx(px), wrapy(py), r, g, bl, al*0.5*(1 - real(n)/(nt + 1)), &
                          .false.)
         end do
         do b = -1, 1
            do a = -1, 1
               if (a*a + b*b > rad*rad + 0.5) cycle
               px = int(xs) + a;  py = int(ys) + b
               call blend_px(buf, w, h, wrapx(px), wrapy(py), r, g, bl, al, .false.)
            end do
         end do
      end do
   contains
      integer function wrapx(p)
         ! wrap a pixel column on the whole-torus view
         integer, intent(in) :: p
         wrapx = p
         if (z == 1) wrapx = modulo(p, w)
      end function wrapx
      integer function wrapy(p)
         ! wrap a pixel row on the whole-torus view
         integer, intent(in) :: p
         wrapy = p
         if (z == 1) wrapy = modulo(p, h)
      end function wrapy
   end subroutine draw_locusts

   subroutine draw_titans(z, i0, j0, buf, w, h)
      ! gold sigils glowing in their own light: a ring, an inner ring, a pointer along the
      ! heading; asleep, a ring of grey stone
      integer, intent(in) :: z, i0, j0, w, h
      character(len=*), intent(inout) :: buf
      integer  :: k, a, b, px, py, m
      real(sp) :: xs, ys, rr, d, v, hx, hy, glow, ring, ax, ay, r, g, bl
      do k = 1, MAXTITAN
         if (titans(k)%state < 1) cycle
         call screen_xy(real(titans(k)%x, sp), real(titans(k)%y, sp), z, i0, j0, xs, ys)
         rr = 3.5 + 1.6*z
         m = int(2.4*rr) + 2
         if (xs < -m .or. ys < -m .or. xs > w + m .or. ys > h + m) cycle
         select case (titans(k)%dir)
         case (0)
            hx = 1;  hy = 0
         case (1)
            hx = 0;  hy = -1
         case (2)
            hx = -1;  hy = 0
         case default
            hx = 0;  hy = 1
         end select
         do b = -m, m
            do a = -m, m
               px = int(xs) + a;  py = int(ys) + b
               ax = px + 0.5 - xs;  ay = py + 0.5 - ys
               d = sqrt(ax*ax + ay*ay)
               ring = max(0., 1 - abs(d - rr)/1.1) + 0.7*max(0., 1 - abs(d - 0.55*rr)/0.8)
               v = (ax - hx*1.45*rr)**2 + (ay - hy*1.45*rr)**2
               ring = ring + max(0., 1 - sqrt(v)/(0.25*rr + 0.9))
               ring = min(1., ring)
               if (titans(k)%state == 1) then
                  glow = 0.55*max(0., 1 - d/(2.4*rr))**2
                  r = pal(1,Q_GOLD);  g = pal(2,Q_GOLD);  bl = pal(3,Q_GOLD)
                  if (glow > 0) call blend_px(buf, w, h, wpx(px), wpy(py), r, g, bl, glow, .true.)
                  if (ring > 0) call blend_px(buf, w, h, wpx(px), wpy(py), pal(1,Q_GOLDHI), &
                                              pal(2,Q_GOLDHI), pal(3,Q_GOLDHI), ring, .false.)
               else if (ring > 0) then
                  call blend_px(buf, w, h, wpx(px), wpy(py), pal(1,Q_SLEEP), pal(2,Q_SLEEP), &
                                pal(3,Q_SLEEP), 0.85*ring, .false.)
               end if
            end do
         end do
      end do
   contains
      integer function wpx(p)
         ! wrap a pixel column on the whole-torus view
         integer, intent(in) :: p
         wpx = p
         if (z == 1) wpx = modulo(p, w)
      end function wpx
      integer function wpy(p)
         ! wrap a pixel row on the whole-torus view
         integer, intent(in) :: p
         wpy = p
         if (z == 1) wpy = modulo(p, h)
      end function wpy
   end subroutine draw_titans

   ! ================================================================ the orbit view

   subroutine render_orbit(yaw, pitch, buf, w, h)
      ! the doughnut planet in 3D (640 x 400): yaw turns the camera about the axis (radians,
      ! 0 = the hero shot, the sun to the left), pitch tilts it from 28 degrees above the
      ! ring plane (radians; |pitch| > 1.6 is taken to be degrees)
      real(dp), intent(in) :: yaw, pitch
      character(len=:), allocatable, intent(inout) :: buf
      integer, intent(out) :: w, h
      real(dp) :: p, el
      call ensure()
      p = pitch
      if (abs(p) > 1.6d0) p = p*DEG
      el = max(-80*DEG, min(80*DEG, EL0 + p))
      el = anint(el/(0.5d0*DEG))*0.5d0*DEG
      if (.not. allocated(hpix) .or. abs(el - lut_el) > 1d-9) call build_orbit(el)
      w = OW;  h = OH
      if (allocated(buf)) then
         if (len(buf) /= 4*w*h) deallocate(buf)
      end if
      if (.not. allocated(buf)) allocate(character(len=4*w*h) :: buf)
      call check_static()
      call pass_living(-1, .false., .true.)
      call titan_lights()
      call prep_sun()
      call shade_orbit(yaw, buf)
   end subroutine render_orbit

   subroutine titan_lights()
      ! awake Titans shine from orbit, a small gold blaze in the night-side lights
      integer  :: k, a, b, ii, jj
      real(sp) :: x
      do k = 1, MAXTITAN
         if (titans(k)%state /= 1) cycle
         do b = -2, 2
            do a = -2, 2
               x = 0.9/(1 + a*a + b*b)
               ii = wrapi(titans(k)%x + a);  jj = wrapj(titans(k)%y + b)
               ce(:,ii,jj) = ce(:,ii,jj) + x*pal(:,Q_GOLD)
               cc(:,ii,jj) = cc(:,ii,jj) + 0.5*x*(pal(:,Q_GOLDHI) - cc(:,ii,jj))
            end do
         end do
      end do
   end subroutine titan_lights

   subroutine build_orbit(el)
      ! ray-cast the doughnut for every pixel (four rays each, for clean edges) from a
      ! camera at elevation el: where each ray lands, how close each miss passes (the
      ! atmosphere), and the sky behind with its stars and a milky way
      real(dp), intent(in) :: el
      real(dp), parameter :: OX(4) = [-0.25d0, 0.25d0, -0.25d0, 0.25d0]
      real(dp), parameter :: OY(4) = [-0.25d0, -0.25d0, 0.25d0, 0.25d0]
      real(dp) :: cam(3), fw(3), rt(3), up(3), rd(3), q(3), qm(3), u, v, dmin, dbest, th, bt
      real(dp) :: rx, xb, yb, dl, band, vig
      real(sp) :: sr, sg, sb, m, t, hsh
      integer  :: px, py, p, k, nh, kk
      logical  :: hit, first
      integer(i8) :: k1, k2, k3
      if (.not. allocated(hpix)) then
         allocate(hpix(OW*OH), hbt(2,OW*OH), hn(4,OW*OH), hv(5,OW*OH), halpix(OW*OH))
         allocate(ohv(OW*OH), ohn(4,OW*OH))
         allocate(character(len=4*OW*OH) :: obg)
      end if
      lut_el = el
      cam = DCAM*[cos(el), 0d0, sin(el)]
      fw = -cam/norm2(cam)
      rt = [0d0, 1d0, 0d0]
      up = [rt(2)*fw(3) - rt(3)*fw(2), rt(3)*fw(1) - rt(1)*fw(3), rt(1)*fw(2) - rt(2)*fw(1)]
      nhit = 0;  nhal = 0;  ohv = 0
      do py = 0, OH - 1
         do px = 0, OW - 1
            p = py*OW + px + 1
            nh = 0;  first = .true.;  dbest = 1d9;  qm = 0
            do k = 1, 4
               u = (px + 0.5d0 + OX(k) - OW/2d0)/FPX
               v = (OH/2d0 - py - 0.5d0 - OY(k))/FPX
               rd = fw + u*rt + v*up
               rd = rd/norm2(rd)
               call march(cam, rd, hit, q, dmin)
               if (hit) then
                  nh = nh + 1
                  if (first) then
                     first = .false.
                     nhit = nhit + 1
                     rx = sqrt(q(1)**2 + q(2)**2) - RR
                     th = atan2(q(3), rx);  bt = atan2(q(2), q(1))
                     hpix(nhit) = p
                     hbt(1,nhit) = real(modulo(bt/TWOPI, 1d0), sp)
                     hbt(2,nhit) = real(modulo((th + PI)/TWOPI, 1d0), sp)
                     hn(:,nhit) = real([cos(th), sin(th), cos(bt), sin(bt)], sp)
                     hv(1:3,nhit) = real(-rd, sp)
                     hv(4,nhit) = real(max(0d0, -(cos(th)*cos(bt)*rd(1) + cos(th)*sin(bt)*rd(2) &
                                  + sin(th)*rd(3))), sp)
                  end if
               else if (dmin < dbest) then
                  dbest = dmin;  qm = q
               end if
            end do
            if (nh > 0) hv(5,nhit) = nh/4.
            if (nh < 4 .and. dbest < HALO) then
               rx = sqrt(qm(1)**2 + qm(2)**2) - RR
               th = atan2(qm(3), rx);  bt = atan2(qm(2), qm(1))
               ohv(p) = real((1 - dbest/HALO)**2.2d0, sp)
               ohn(:,p) = real([cos(th), sin(th), cos(bt), sin(bt)], sp)
               if (nh == 0) then
                  nhal = nhal + 1;  halpix(nhal) = p
               end if
            end if
         end do
      end do
      ! the sky: a dark field, a milky way across it, stars of several colours
      k1 = mix32(9001_i8);  k2 = mix32(9002_i8);  k3 = mix32(9003_i8)
      do py = 0, OH - 1
         do px = 0, OW - 1
            p = py*OW + px + 1
            xb = px/real(OW, dp);  yb = py/real(OH, dp)
            dl = abs(0.62d0*xb + yb - 0.92d0)/sqrt(1 + 0.62d0**2)
            band = exp(-(dl/0.11d0)**2)
            vig = 1 - 0.35d0*((xb - 0.5d0)**2 + (yb - 0.5d0)**2)
            kk = iand(px/3, 63)
            m = real(band*(0.55d0 + 0.9d0*nzs(kk, iand(py/3, 63))), sp)
            sr = real(vig*(0.0016d0 + 0.010d0*m), sp)
            sg = real(vig*(0.0018d0 + 0.009d0*m), sp)
            sb = real(vig*(0.0040d0 + 0.016d0*m), sp)
            hsh = real(hr2(px, py, k1), sp)
            if (hsh < 0.0022 + 0.012*band) then
               m = real(hr2(px, py, k2), sp)**5*0.9 + 0.04
               t = real(hr2(px, py, k3), sp)
               if (t < 0.3) then
                  sr = sr + m*0.75;  sg = sg + m*0.85;  sb = sb + m*1.0
               else if (t < 0.75) then
                  sr = sr + m;  sg = sg + m*0.97;  sb = sb + m*0.92
               else
                  sr = sr + m;  sg = sg + m*0.82;  sb = sb + m*0.62
               end if
            end if
            obg(4*p-3:4*p) = enc(sr, sg, sb)
         end do
      end do
      ! a few bright stars wear a small cross
      do py = 1, OH - 2
         do px = 1, OW - 2
            if (hr2(px, py, k1) >= 0.0022 + 0.012) cycle
            m = real(hr2(px, py, k2), sp)**5*0.9 + 0.04
            if (m < 0.45) cycle
            do k = 1, 4
               p = (py + DJ(2*k-1))*OW + px + DI(2*k-1) + 1
               sr = gdec(iachar(obg(4*p-3:4*p-3))) + 0.22*m
               sg = gdec(iachar(obg(4*p-2:4*p-2))) + 0.22*m
               sb = gdec(iachar(obg(4*p-1:4*p-1))) + 0.24*m
               obg(4*p-3:4*p) = enc(sr, sg, sb)
            end do
         end do
      end do
   end subroutine build_orbit

   subroutine march(ro, rd, hit, q, dmin)
      ! sphere-trace one ray against the doughnut (R = 2, r = 1); on a miss, dmin and q
      ! are the closest approach to its surface
      real(dp), intent(in)  :: ro(3), rd(3)
      logical,  intent(out) :: hit
      real(dp), intent(out) :: q(3), dmin
      real(dp) :: b, c, disc, t, t1, d, p(3), rb
      integer  :: n
      hit = .false.;  dmin = 1d9;  q = 0
      rb = RR + 1 + HALO + 0.05d0
      b = dot_product(ro, rd);  c = dot_product(ro, ro) - rb*rb
      disc = b*b - c
      if (disc <= 0) return
      t = max(0d0, -b - sqrt(disc));  t1 = -b + sqrt(disc)
      do n = 1, 400
         p = ro + t*rd
         d = sqrt((sqrt(p(1)**2 + p(2)**2) - RR)**2 + p(3)**2) - 1
         if (d < dmin) then
            dmin = d;  q = p
         end if
         if (d < 2d-4) then
            hit = .true.;  q = p
            return
         end if
         t = t + d
         if (t > t1) return
      end do
   end subroutine march

   subroutine shade_orbit(yaw, buf)
      ! light every pixel of the orbit view: the sun and the ring's shadow, glinting seas,
      ! the atmosphere at the limb, the lights of the night side, the stars behind
      real(dp), intent(in) :: yaw
      character(len=*), intent(inout) :: buf
      real(sp), parameter :: AD(3) = [0.24, 0.48, 1.00], AN(3) = [0.012, 0.022, 0.06]
      real(sp), parameter :: AT(3) = [1.00, 0.42, 0.15]
      real(dp) :: psi, dec
      real(sp) :: cp, sn, cd, sd, sx, sy, sz, rot, hof, fi, fj, fx, fy, w00, w10, w01, w11
      real(sp) :: tr, tg, tb, er, eg, eb, c, dl, x, s, t, direct, day, nh, hx, hy, hz, sp_
      real(sp) :: fr, atm, lit, twl, r, g, b, cov, hr, hg, hb, ct, st, cb, sbt
      integer  :: k, p, i0, i1, j0, j1, kh, jn
      psi = AZ0 + yaw
      dec = tilt*sin(TWOPI*season_frac())
      cp = real(cos(psi), sp);  sn = real(sin(psi), sp)
      cd = real(cos(dec), sp);  sd = real(sin(dec), sp)
      sx = cd*cp;  sy = -cd*sn;  sz = sd
      rot = real(modulo((psi + sunlon)/TWOPI, 1d0), sp)
      hof = real(modulo(psi/TWOPI, 1d0), sp)
      buf(1:4*OW*OH) = obg
      ! the atmosphere seen against the sky
      do k = 1, nhal
         p = halpix(k)
         call halo_rgb(p, hr, hg, hb)
         r = gdec(iachar(obg(4*p-3:4*p-3))) + hr
         g = gdec(iachar(obg(4*p-2:4*p-2))) + hg
         b = gdec(iachar(obg(4*p-1:4*p-1))) + hb
         buf(4*p-3:4*p) = enc(r, g, b)
      end do
      ! the planet
      do k = 1, nhit
         p = hpix(k)
         fi = (hbt(1,k) + rot)*NX + 0.5;  fj = hbt(2,k)*NY + 0.5
         x = real(floor(fi), sp);  fx = fi - x;  i0 = wrapi(int(x));  i1 = wrapi(int(x) + 1)
         x = real(floor(fj), sp);  fy = fj - x;  j0 = wrapj(int(x));  j1 = wrapj(int(x) + 1)
         w00 = (1 - fx)*(1 - fy);  w10 = fx*(1 - fy);  w01 = (1 - fx)*fy;  w11 = fx*fy
         tr = w00*cc(1,i0,j0) + w10*cc(1,i1,j0) + w01*cc(1,i0,j1) + w11*cc(1,i1,j1)
         tg = w00*cc(2,i0,j0) + w10*cc(2,i1,j0) + w01*cc(2,i0,j1) + w11*cc(2,i1,j1)
         tb = w00*cc(3,i0,j0) + w10*cc(3,i1,j0) + w01*cc(3,i0,j1) + w11*cc(3,i1,j1)
         er = w00*ce(1,i0,j0) + w10*ce(1,i1,j0) + w01*ce(1,i0,j1) + w11*ce(1,i1,j1)
         eg = w00*ce(2,i0,j0) + w10*ce(2,i1,j0) + w01*ce(2,i0,j1) + w11*ce(2,i1,j1)
         eb = w00*ce(3,i0,j0) + w10*ce(3,i1,j0) + w01*ce(3,i0,j1) + w11*ce(3,i1,j1)
         ct = hn(1,k);  st = hn(2,k);  cb = hn(3,k);  sbt = hn(4,k)
         c = ct*cd*(cb*cp - sbt*sn) + st*sd
         ! the shadow of the ring, from the sunlight table at this hour
         x = modulo(hbt(1,k) + hof, 1.)*NHOUR
         kh = min(NHOUR - 1, int(x));  t = x - kh
         jn = wrapj(nint(fj))
         dl = (1 - t)*dlt(kh+1,jn) + t*dlt(kh+2,jn)
         s = 1
         if (c > 0) then
            s = min(1., dl/max(c, 0.04))
            t = min(1., c/0.08)
            s = s*t + 1 - t
         end if
         direct = max(0., c)*s
         day = smooth(-0.05, 0.16, c)*s
         x = 0.010 + 1.30*direct
         r = tr*x;  g = tg*x;  b = tb*x
         twl = max(0., 1 - abs(c - 0.01)/0.11)*s
         r = r + tr*0.30*twl*AT(1);  g = g + tg*0.30*twl*AT(2);  b = b + tb*0.30*twl*AT(3)
         x = 1.5*(1 - day)
         r = r + x*er;  g = g + x*eg;  b = b + x*eb
         ! the sun's glint on open water
         if (land(wrapi(nint(fi)),jn) == 0 .and. ice(wrapi(nint(fi)),jn) < 0 .and. direct > 0) then
            hx = sx + hv(1,k);  hy = sy + hv(2,k);  hz = sz + hv(3,k)
            nh = (ct*cb*hx + ct*sbt*hy + st*hz)/sqrt(hx*hx + hy*hy + hz*hz)
            if (nh > 0.9) then
               sp_ = nh*nh*nh;  sp_ = sp_*sp_;  sp_ = sp_*sp_;  sp_ = sp_*sp_;  sp_ = sp_*sp_
               sp_ = 0.85*sp_*sqrt(direct)
               r = r + sp_;  g = g + 0.93*sp_;  b = b + 0.80*sp_
            end if
         end if
         ! the atmosphere, thickest at the limb
         fr = 1 - hv(4,k);  fr = fr*fr*fr
         lit = smooth(-0.25, 0.45, c)
         atm = fr*0.75
         r = r + atm*(AD(1)*lit + AN(1)) + fr*0.35*twl*AT(1)
         g = g + atm*(AD(2)*lit + AN(2)) + fr*0.35*twl*AT(2)
         b = b + atm*(AD(3)*lit + AN(3)) + fr*0.35*twl*AT(3)
         cov = hv(5,k)
         if (cov < 1) then
            call halo_rgb(p, hr, hg, hb)
            r = cov*r + (1 - cov)*(gdec(iachar(obg(4*p-3:4*p-3))) + hr)
            g = cov*g + (1 - cov)*(gdec(iachar(obg(4*p-2:4*p-2))) + hg)
            b = cov*b + (1 - cov)*(gdec(iachar(obg(4*p-1:4*p-1))) + hb)
         end if
         buf(4*p-3:4*p) = enc(r, g, b)
      end do
   contains
      subroutine halo_rgb(p_, r_, g_, b_)
         ! light of the atmosphere seen just past the limb at pixel p_
         integer,  intent(in)  :: p_
         real(sp), intent(out) :: r_, g_, b_
         real(sp) :: c_, v_, l_, t_
         v_ = ohv(p_)
         if (v_ <= 0) then
            r_ = 0;  g_ = 0;  b_ = 0
            return
         end if
         c_ = ohn(1,p_)*cd*(ohn(3,p_)*cp - ohn(4,p_)*sn) + ohn(2,p_)*sd
         l_ = smooth(-0.30, 0.50, c_)
         t_ = max(0., 1 - abs(c_ + 0.04)/0.16)
         r_ = v_*(0.9*AD(1)*l_ + AN(1) + 0.45*t_*AT(1))
         g_ = v_*(0.9*AD(2)*l_ + AN(2) + 0.45*t_*AT(2))
         b_ = v_*(0.9*AD(3)*l_ + AN(3) + 0.45*t_*AT(3))
      end subroutine halo_rgb
   end subroutine shade_orbit

   ! ================================================================ snapshots

   subroutine render_snapshot(fname, view)
      ! a PPM picture of the whole map in one view (view < 0: the planet from orbit)
      character(*), intent(in) :: fname
      integer,      intent(in) :: view
      character(len=:), allocatable :: b
      integer :: w, h
      if (view < 0) then
         call render_orbit(0d0, 0d0, b, w, h)
      else
         call render_map(view, 1, NX/2, NY/2, -1, b, w, h)
      end if
      call write_ppm(fname, b, w, h)
   end subroutine render_snapshot

end module rl_render

!=======================================================================
!  rl_net -- a very small HTTP/1.1 server on 127.0.0.1, written straight
!  onto the POSIX socket calls through iso_c_binding.  The browser is the
!  screen; Fortran does everything else.  Keep-alive connections, several
!  clients at once, and nothing ever blocks on an idle connection: every
!  socket is only read after poll() says it has data.
!  Works with the Linux and the BSD/macOS layouts of struct sockaddr_in.
!=======================================================================
module rl_net
   use, intrinsic :: iso_c_binding
   use, intrinsic :: iso_fortran_env, only: int8, int64
   implicit none
   private
   public :: req_t, net_open, net_next, net_reply, net_close_all, qval, qnum, net_port

   interface
      function c_socket(d, t, p) bind(c, name='socket') result(fd)
         import :: c_int
         integer(c_int), value :: d, t, p
         integer(c_int) :: fd
      end function c_socket
      function c_setsockopt(fd, lvl, opt, val, ln) bind(c, name='setsockopt') result(r)
         import :: c_int, c_ptr
         integer(c_int), value :: fd, lvl, opt, ln
         type(c_ptr),    value :: val
         integer(c_int) :: r
      end function c_setsockopt
      function c_bind(fd, addr, ln) bind(c, name='bind') result(r)
         import :: c_int, c_ptr
         integer(c_int), value :: fd, ln
         type(c_ptr),    value :: addr
         integer(c_int) :: r
      end function c_bind
      function c_listen(fd, n) bind(c, name='listen') result(r)
         import :: c_int
         integer(c_int), value :: fd, n
         integer(c_int) :: r
      end function c_listen
      function c_accept(fd, a, l) bind(c, name='accept') result(r)
         import :: c_int, c_ptr
         integer(c_int), value :: fd
         type(c_ptr),    value :: a, l
         integer(c_int) :: r
      end function c_accept
      function c_recv(fd, buf, n, fl) bind(c, name='recv') result(r)
         import :: c_int, c_size_t, c_long, c_ptr
         integer(c_int),    value :: fd, fl
         type(c_ptr),       value :: buf
         integer(c_size_t), value :: n
         integer(c_long) :: r
      end function c_recv
      function c_send(fd, buf, n, fl) bind(c, name='send') result(r)
         import :: c_int, c_size_t, c_long, c_ptr
         integer(c_int),    value :: fd, fl
         type(c_ptr),       value :: buf
         integer(c_size_t), value :: n
         integer(c_long) :: r
      end function c_send
      function c_close(fd) bind(c, name='close') result(r)
         import :: c_int
         integer(c_int), value :: fd
         integer(c_int) :: r
      end function c_close
      function c_poll(fds, n, t) bind(c, name='poll') result(r)
         import :: c_int, c_ptr, c_long
         type(c_ptr),     value :: fds
         integer(c_long), value :: n
         integer(c_int),  value :: t
         integer(c_int) :: r
      end function c_poll
      function c_signal(sig, h) bind(c, name='signal') result(r)
         import :: c_int, c_intptr_t
         integer(c_int),     value :: sig
         integer(c_intptr_t), value :: h
         integer(c_intptr_t) :: r
      end function c_signal
   end interface

   type, bind(c) :: pollfd_t
      integer(c_int)   :: fd
      integer(c_short) :: events, revents
   end type pollfd_t

   integer, parameter :: MAXC = 24, RBUF = 16384
   type client_t
      integer(c_int) :: fd = -1
      integer :: n = 0                        ! bytes waiting in buf
      integer :: idle = 0                     ! polls since it last spoke
      character(len=RBUF) :: buf = ''
   end type client_t

   type req_t                                 ! one parsed request
      integer :: c = 0                        ! which client asked
      character(len=:), allocatable :: path, query
   end type req_t

   integer(c_int), save :: lfd = -1
   type(client_t), save, target :: cl(MAXC)
   integer,        save :: net_port = 0
   character(*), parameter :: CRLF = achar(13)//achar(10)

contains

   logical function net_open(port0)
      ! listen on 127.0.0.1, on the first free port from port0 upwards
      integer, intent(in) :: port0
      integer(c_int8_t), target :: sa(16)
      integer(c_int),    target :: one
      integer(c_intptr_t) :: old
      integer :: p, lay
      integer(c_int) :: ir
      net_open = .false.
      old = c_signal(13_c_int, 1_c_intptr_t)          ! SIGPIPE: ignore (a closed tab must not kill us)
      do p = port0, port0 + 40
         lfd = c_socket(2_c_int, 1_c_int, 0_c_int)    ! AF_INET, SOCK_STREAM
         if (lfd < 0) return
         one = 1                                      ! SO_REUSEADDR, Linux and BSD spellings
         ir = c_setsockopt(lfd, 1_c_int, 2_c_int, c_loc(one), 4_c_int)
         ir = c_setsockopt(lfd, 65535_c_int, 4_c_int, c_loc(one), 4_c_int)
         do lay = 1, 2                                ! 1: Linux sockaddr_in, 2: BSD (sin_len first)
            sa = 0_c_int8_t
            if (lay == 1) then
               sa(1) = 2_c_int8_t
            else
               sa(1) = 16_c_int8_t;  sa(2) = 2_c_int8_t
            end if
            sa(3) = int(ishft(p, -8), c_int8_t)
            sa(4) = int(iand(p, 255) - 256*(iand(p, 255)/128), c_int8_t)
            sa(5) = 127_c_int8_t;  sa(8) = 1_c_int8_t
            if (c_bind(lfd, c_loc(sa), 16_c_int) == 0) then
               if (c_listen(lfd, 32_c_int) == 0) then
                  net_port = p
                  net_open = .true.
                  return
               end if
            end if
         end do
         ir = c_close(lfd)
      end do
   end function net_open

   subroutine net_next(rq, got, wait_ms)
      ! accept whatever is knocking, read whatever has arrived, and hand back
      ! the next complete request (got = .false. if there is none yet)
      type(req_t), intent(out) :: rq
      logical,     intent(out) :: got
      integer,     intent(in)  :: wait_ms
      type(pollfd_t), target :: pf(MAXC + 1)
      integer :: who(MAXC + 1), np, i, k, e
      integer(c_int) :: fd
      integer(c_long) :: m
      got = .false.
      if (lfd < 0) return
      do i = 1, MAXC                         ! a request may already be buffered
         if (cl(i)%fd >= 0 .and. index(cl(i)%buf(1:cl(i)%n), CRLF//CRLF) > 0) then
            call parse(i, rq);  got = .true.;  return
         end if
      end do
      np = 1
      pf(1) = pollfd_t(lfd, 1_c_short, 0_c_short);  who(1) = 0
      do i = 1, MAXC
         if (cl(i)%fd < 0) cycle
         np = np + 1
         pf(np) = pollfd_t(cl(i)%fd, 1_c_short, 0_c_short);  who(np) = i
      end do
      if (c_poll(c_loc(pf), int(np, c_long), int(wait_ms, c_int)) <= 0) then
         call reap()
         return
      end if
      if (iand(int(pf(1)%revents), 1) /= 0) then          ! a new connection
         fd = c_accept(lfd, c_null_ptr, c_null_ptr)
         if (fd >= 0) then
            k = 0
            do i = 1, MAXC
               if (cl(i)%fd < 0) then
                  k = i;  exit
               end if
            end do
            if (k == 0) then                               ! full house: oldest idle goes
               k = maxloc(cl%idle, 1)
               call drop(k)
            end if
            cl(k)%fd = fd;  cl(k)%n = 0;  cl(k)%idle = 0
         end if
      end if
      do e = 2, np
         i = who(e)
         if (pf(e)%revents == 0) then
            cl(i)%idle = cl(i)%idle + 1
            cycle
         end if
         if (cl(i)%n >= RBUF) then                         ! header too long: give up on it
            call drop(i);  cycle
         end if
         m = c_recv(cl(i)%fd, c_loc(cl(i)%buf(cl(i)%n + 1:cl(i)%n + 1)), &
                    int(RBUF - cl(i)%n, c_size_t), 0_c_int)
         if (m <= 0) then                                  ! closed by the browser (or an error)
            call drop(i)
         else
            cl(i)%n = cl(i)%n + int(m);  cl(i)%idle = 0
         end if
      end do
      call reap()
      do i = 1, MAXC
         if (cl(i)%fd >= 0 .and. index(cl(i)%buf(1:cl(i)%n), CRLF//CRLF) > 0) then
            call parse(i, rq);  got = .true.;  return
         end if
      end do
   end subroutine net_next

   subroutine parse(i, rq)
      ! "GET /path?query HTTP/1.1": keep path and query, drop the rest of the header
      integer,     intent(in)  :: i
      type(req_t), intent(out) :: rq
      integer :: e, a, b, q
      character(len=:), allocatable :: line, target
      e = index(cl(i)%buf(1:cl(i)%n), CRLF//CRLF) + 3
      line = cl(i)%buf(1:index(cl(i)%buf(1:e), CRLF) - 1)
      a = index(line, ' ');  b = index(line, ' ', back=.true.)
      target = '/'
      if (a > 0 .and. b > a + 1) target = line(a + 1:b - 1)
      q = index(target, '?')
      rq%c = i
      if (q > 0) then
         rq%path = target(1:q - 1);  rq%query = target(q + 1:)
      else
         rq%path = target;  rq%query = ''
      end if
      cl(i)%buf(1:cl(i)%n - e) = cl(i)%buf(e + 1:cl(i)%n)   ! keep anything pipelined behind it
      cl(i)%n = cl(i)%n - e
   end subroutine parse

   subroutine net_reply(rq, ctype, body, status)
      ! answer a request; body may hold any bytes.  The connection stays open.
      type(req_t),  intent(in) :: rq
      character(*), intent(in) :: ctype
      character(*), intent(in), target :: body
      character(*), intent(in), optional :: status
      character(len=:), allocatable, target :: head
      character(len=24) :: nb
      if (rq%c < 1) return
      if (cl(rq%c)%fd < 0) return
      write(nb, '(i0)') len(body)
      head = 'HTTP/1.1 '
      if (present(status)) then
         head = head//status//CRLF
      else
         head = head//'200 OK'//CRLF
      end if
      head = head//'Content-Type: '//ctype//CRLF//'Content-Length: '//trim(nb)//CRLF// &
             'Cache-Control: no-store'//CRLF//'Connection: keep-alive'//CRLF//CRLF
      if (.not. sendall(rq%c, c_loc(head), len(head))) return
      if (len(body) > 0) then
         if (.not. sendall(rq%c, c_loc(body), len(body))) return
      end if
   end subroutine net_reply

   logical function sendall(i, p, n)
      integer,     intent(in) :: i, n
      type(c_ptr), intent(in) :: p
      integer(int8), pointer :: b(:)
      integer(c_long) :: m
      integer :: done
      call c_f_pointer(p, b, [n])
      done = 0
      sendall = .false.
      do while (done < n)
         m = c_send(cl(i)%fd, c_loc(b(done + 1)), int(n - done, c_size_t), 0_c_int)
         if (m <= 0) then
            call drop(i);  return
         end if
         done = done + int(m)
      end do
      sendall = .true.
   end function sendall

   subroutine reap()
      ! connections that said nothing for a long while (speculative pre-connects,
      ! closed tabs) are closed, so they can never pile up
      integer :: i
      do i = 1, MAXC
         if (cl(i)%fd >= 0 .and. cl(i)%idle > 4000) call drop(i)
      end do
   end subroutine reap

   subroutine drop(i)
      integer, intent(in) :: i
      integer(c_int) :: ir
      if (cl(i)%fd >= 0) ir = c_close(cl(i)%fd)
      cl(i)%fd = -1;  cl(i)%n = 0;  cl(i)%idle = 0
   end subroutine drop

   subroutine net_close_all()
      integer(c_int) :: ir
      integer :: i
      do i = 1, MAXC
         call drop(i)
      end do
      if (lfd >= 0) ir = c_close(lfd)
      lfd = -1
   end subroutine net_close_all

   function qval(query, key) result(v)
      ! value of key in "a=1&b=xyz" ('' if absent), %XX and + decoded
      character(*), intent(in) :: query, key
      character(len=:), allocatable :: v
      integer :: s, e, i, h
      character(len=:), allocatable :: raw
      v = ''
      s = 1
      do while (s <= len(query))
         e = index(query(s:), '&')
         if (e == 0) then
            e = len(query)
         else
            e = s + e - 2
         end if
         if (index(query(s:e), key//'=') == 1) then
            raw = query(s + len(key) + 1:e)
            i = 1
            do while (i <= len(raw))
               if (raw(i:i) == '%' .and. i + 2 <= len(raw)) then
                  read(raw(i + 1:i + 2), '(z2)', err=9) h
                  v = v//achar(h);  i = i + 3;  cycle
9                 continue
               end if
               if (raw(i:i) == '+') then
                  v = v//' '
               else
                  v = v//raw(i:i)
               end if
               i = i + 1
            end do
            return
         end if
         s = e + 2
      end do
   end function qval

   real(8) function qnum(query, key, dflt)
      character(*), intent(in) :: query, key
      real(8),      intent(in) :: dflt
      character(len=:), allocatable :: v
      integer :: ios
      v = qval(query, key)
      qnum = dflt
      if (len(v) == 0) return
      read(v, *, iostat=ios) qnum
      if (ios /= 0) qnum = dflt
   end function qnum

end module rl_net

