      call sb_put(sb, 'const Q = new URLSearchParams(location.search);'//NL)
      call sb_put(sb, 'const clamp = (x, a, b) => x < a ? a : x > b ? b : x;'//NL)
      call sb_put(sb, 'const lerp = (a, b, t) => a + (b - a) * t;'//NL)
      call sb_put(sb, 'const ESC = { ''&'': ''&amp;'', ''<'': ''&lt;'', ''>'': ''&gt;'', ''"'': ''&quot;'' };'//NL)
      call sb_put(sb, 'const esc = s => String(s == null ? '''' : s).replace(/[&<>"]/g, c => ESC[c]);'//NL)
      call sb_put(sb, 'const num = (x, d) => (x == null || !isFinite(x)) ? ''–'' : Number(x).toFixed(d);'//NL)
      call sb_put(sb, 'const sleep = ms => new Promise(r => setTimeout(r, ms));'//NL)
      call sb_put(sb, 'const raf = () => new Promise(r => requestAnimationFrame(r));'//NL)
      call sb_put(sb, 'const cap1 = s => s ? s[0].toUpperCase() + s.slice(1) : '''';'//NL)
      call sb_put(sb, 'function big(n) {'//NL)
      call sb_put(sb, '  if (n == null || !isFinite(n)) return ''–'';'//NL)
      call sb_put(sb, '  const a = Math.abs(n);'//NL)
      call sb_put(sb, '  if (a >= 1e6) return (n / 1e6).toFixed(a >= 1e7 ? 1 : 2) + ''M'';'//NL)
      call sb_put(sb, '  if (a >= 1e4) return (n / 1e3).toFixed(a >= 1e5 ? 0 : 1) + ''k'';'//NL)
      call sb_put(sb, '  return Math.round(n).toLocaleString(''en-US'');'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'function el(tag, cls, html) {'//NL)
      call sb_put(sb, '  const e = document.createElement(tag);'//NL)
      call sb_put(sb, '  if (cls) e.className = cls;'//NL)
      call sb_put(sb, '  if (html != null) e.innerHTML = html;'//NL)
      call sb_put(sb, '  return e;'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'const icon = (id, cls) => `<svg class="i${cls ? '' '' + cls : ''''}"><use href="#${id}"/></')
      call sb_put(sb, 'svg>`;'//NL)
      call sb_put(sb, 'const VS = ''︎'';                                    // text presentation for symbols'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, '// the browser''s errors go to the server''s stderr (rl_web /log)'//NL)
      call sb_put(sb, 'let nlog = 0;'//NL)
      call sb_put(sb, 'function report(m) {'//NL)
      call sb_put(sb, '  if (nlog++ > 40) return;'//NL)
      call sb_put(sb, '  try { fetch(''/log?m='' + encodeURIComponent(String(m).slice(0, 560))).catch(() => {}); }')
      call sb_put(sb, ' catch (e) { /* */ }'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'window.onerror = (m, src, l, c, e) => {'//NL)
      call sb_put(sb, '  report(''JS error: '' + m + '' at '' + l + '':'' + c + (e && e.stack ? '' | '' + String(e')
      call sb_put(sb, '.stack).split(''\n'')[0] : ''''));'//NL)
      call sb_put(sb, '};'//NL)
      call sb_put(sb, 'window.addEventListener(''unhandledrejection'', ev => {'//NL)
      call sb_put(sb, '  const r = ev.reason;'//NL)
      call sb_put(sb, '  report(''unhandled rejection: '' + (r && (r.stack || r.message) || r));'//NL)
      call sb_put(sb, '});'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, '// ===================================================================== colour: the render')
      call sb_put(sb, 'er''s jewels'//NL)
      call sb_put(sb, 'function oklch(L, C, h) {'//NL)
      call sb_put(sb, '  const hr = h * Math.PI / 180, ch = Math.cos(hr), sh = Math.sin(hr);'//NL)
      call sb_put(sb, '  const raw = c => {'//NL)
      call sb_put(sb, '    const a = c * ch, b = c * sh;'//NL)
      call sb_put(sb, '    const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;'//NL)
      call sb_put(sb, '    const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;'//NL)
      call sb_put(sb, '    const s = (L - 0.0894841775 * a - 1.2914855480 * b) ** 3;'//NL)
      call sb_put(sb, '    return [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,'//NL)
      call sb_put(sb, '      -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,'//NL)
      call sb_put(sb, '      -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s];'//NL)
      call sb_put(sb, '  };'//NL)
      call sb_put(sb, '  const bad = v => Math.min(v[0], v[1], v[2]) < 0 || Math.max(v[0], v[1], v[2]) > 1;'//NL)
      call sb_put(sb, '  let v = raw(C);'//NL)
      call sb_put(sb, '  if (bad(v)) {'//NL)
      call sb_put(sb, '    let lo = 0, hi = C;'//NL)
      call sb_put(sb, '    for (let k = 0; k < 16; k++) { const mid = 0.5 * (lo + hi); if (bad(raw(mid))) hi = mid')
      call sb_put(sb, '; else lo = mid; }'//NL)
      call sb_put(sb, '    v = raw(lo);'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  return v.map(x => { x = clamp(x, 0, 1); return Math.round(255 * (x <= 0.0031308 ? 12.92 *')
      call sb_put(sb, ' x : 1.055 * x ** (1 / 2.4) - 0.055)); });'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'const JC = new Map();'//NL)
      call sb_put(sb, 'function jewelRGB(hue, lv) {'//NL)
      call sb_put(sb, '  lv = lv == null ? 9 : lv;'//NL)
      call sb_put(sb, '  const k = hue + '':'' + lv;'//NL)
