      call sb_put(sb, '  if (!c) {'//NL)
      call sb_put(sb, '    c = (hue == null || hue < 0) ? oklch(0.54 + 0.025 * lv, 0.028, 85) : oklch(0.5 + 0.025 ')
      call sb_put(sb, '* lv, 0.2 - 0.004 * lv, hue + 30);'//NL)
      call sb_put(sb, '    JC.set(k, c);'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  return c;'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'const jewel = (hue, lv) => { const c = jewelRGB(hue, lv); return `rgb(${c[0]},${c[1]},${c[2')
      call sb_put(sb, ']})`; };'//NL)
      call sb_put(sb, 'const jewelA = (hue, lv, a) => { const c = jewelRGB(hue, lv); return `rgba(${c[0]},${c[1]},')
      call sb_put(sb, '${c[2]},${a})`; };'//NL)
      call sb_put(sb, 'const GOODS = [''grain'', ''timber'', ''stone'', ''salt'', ''furs'', ''spice''];'//NL)
      call sb_put(sb, 'const GCOL = [''#e6c46a'', ''#b9814c'', ''#a9abb2'', ''#dbe8f2'', ''#cf9466'', ''#e0683f'']')
      call sb_put(sb, ';'//NL)
      call sb_put(sb, 'const GOVS = [''chiefdom'', ''kingdom'', ''republic'', ''theocracy'', ''commune'', ''horde')
      call sb_put(sb, ''', ''empire'', ''anarchy''];'//NL)
      call sb_put(sb, 'const govName = g => typeof g === ''number'' ? (GOVS[g - 1] || ''realm'') : String(g || ''r')
      call sb_put(sb, 'ealm'').toLowerCase();'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, '// ===================================================================== the server'//NL)
      call sb_put(sb, 'async function getJSON(u) {'//NL)
      call sb_put(sb, '  const r = await fetch(u, { cache: ''no-store'' });'//NL)
      call sb_put(sb, '  if (!r.ok) throw new Error(u.split(''?'')[0] + '' answered '' + r.status);'//NL)
      call sb_put(sb, '  return r.json();'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'function syncJSON(u) {                               // only for the first paint (headless ')
      call sb_put(sb, 'shots)'//NL)
      call sb_put(sb, '  try {'//NL)
      call sb_put(sb, '    const x = new XMLHttpRequest();'//NL)
      call sb_put(sb, '    x.open(''GET'', u, false);'//NL)
