      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'const frameURL = () => `/frame?v=${G.view}&z=${G.z}&cx=${G.cx}&cy=${G.cy}&hl=${G.hl}`;'//NL)
      call sb_put(sb, 'async function frameLoop() {'//NL)
      call sb_put(sb, '  let lastKey = '''', lastTick = -1;'//NL)
