      call sb_put(sb, NL)
      call sb_put(sb, '// ===================================================================== the overlay: carav')
      call sb_put(sb, 'ans, crowns, the hand-light'//NL)
      call sb_put(sb, 'function realmById(id) { return G.soc && G.soc.realms ? G.soc.realms.find(m => m.id === id)')
      call sb_put(sb, ' : null; }'//NL)
      call sb_put(sb, 'function drawOverlay(now) {'//NL)
      call sb_put(sb, '  const c = $(''#ovl''), ctx = c.getContext(''2d''), d = G.dpr, W = c.width, H = c.height;'//NL)
