      call sb_put(sb, ''', famine: ''⌓'', price: ''⇅'','//NL)
      call sb_put(sb, '  faith: ''✶'', prophet: ''☉'', prophecy: ''☽'', prophecykept: ''✓'', prophecyfaile')
