      call sb_put(sb, '  holywar: ''✙'', praise: ''❦'', convert: ''↻'', heresy: ''‡'', embargoend: ''⊕''')
      call sb_put(sb, ', annex: ''⊞'', secede: ''⊟'','//NL)
      call sb_put(sb, '  caravan: ''⇶'', faithend: ''✝'', prophetdeath: ''✟'''//NL)
      call sb_put(sb, '};'//NL)
      call sb_put(sb, 'const glyph = k => (GLYPH[String(k || '''').toLowerCase().replace(/[_\- ]/g, '''')] || ''·')
      call sb_put(sb, ''') + VS;'//NL)
      call sb_put(sb, 'const CH = { list: [], byId: new Map(), since: 0, fresh: new Set(), n: 0 };'//NL)
      call sb_put(sb, 'function mergeChron(list) {'//NL)
      call sb_put(sb, '  if (!list || !list.length) return false;'//NL)
      call sb_put(sb, '  let ch = false;'//NL)
      call sb_put(sb, '  const init = CH.since === 0;'//NL)
      call sb_put(sb, '  for (const e of list) {'//NL)
      call sb_put(sb, '    if (CH.byId.has(e.id)) continue;'//NL)
      call sb_put(sb, '    CH.byId.set(e.id, e); CH.list.push(e); ch = true;'//NL)
      call sb_put(sb, '    if (!init) CH.fresh.add(e.id);'//NL)
      call sb_put(sb, '    CH.since = Math.max(CH.since, e.id);'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  CH.since = Math.max(CH.since, ...list.map(e => e.id));'//NL)
      call sb_put(sb, '  if (CH.list.length > 600) { const drop = CH.list.splice(0, CH.list.length - 600); for (co')
      call sb_put(sb, 'nst e of drop) CH.byId.delete(e.id); }'//NL)
      call sb_put(sb, '  return ch;'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'function renderChron() {'//NL)
      call sb_put(sb, '  // ages in reverse order, each headed by its name; inside an age the newest entry first'//NL)
      call sb_put(sb, '  const L = CH.list.slice().sort((a, b) => a.id - b.id), ages = [{ e: null, list: [] }];'//NL)
      call sb_put(sb, '  for (const e of L) {'//NL)
      call sb_put(sb, '    if (e.kind === ''age'') ages.push({ e, list: [] });'//NL)
      call sb_put(sb, '    else ages[ages.length - 1].list.push(e);'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  const out = [];'//NL)
      call sb_put(sb, '  for (let k = ages.length - 1; k >= 0; k--) {'//NL)
      call sb_put(sb, '    const A = ages[k];'//NL)
      call sb_put(sb, '    if (A.e) out.push(`<div class="agehead"><em>${glyph(''age'')}</em>${esc(A.e.text)}<span')
      call sb_put(sb, '>${Math.floor(A.e.year)}</span></div>`);'//NL)
      call sb_put(sb, '    let yr = null, first = true;'//NL)
      call sb_put(sb, '    for (let j = A.list.length - 1; j >= 0; j--) {'//NL)
      call sb_put(sb, '      const e = A.list[j], y = Math.floor(e.year);'//NL)
      call sb_put(sb, '      if (y !== yr) { out.push(`<div class="yr">Year ${y}</div>`); yr = y; }'//NL)
      call sb_put(sb, '      const go = e.x || e.y, imp = clamp(e.imp || 1, 1, 5);'//NL)
      call sb_put(sb, '      let t = esc(e.text);'//NL)
      call sb_put(sb, '      if (first && t.length > 1 && /[A-Za-z]/.test(t[0])) { t = `<i class="cap0">${t[0]}</i')
      call sb_put(sb, '>${t.slice(1)}`; }'//NL)
      call sb_put(sb, '      first = false;'//NL)
      call sb_put(sb, '      out.push(`<div class="ent i${imp}${go ? '' go'' : ''''}${CH.fresh.has(e.id) ? '' new')
      call sb_put(sb, ''' : ''''}` +'//NL)
      call sb_put(sb, '        `${e.kind === ''extinct'' ? '' epitaph'' : ''''}"${go ? ` data-x="${e.x}" data-y="$')
      call sb_put(sb, '{e.y}"` : ''''}>` +'//NL)
      call sb_put(sb, '        `<span class="g">${glyph(e.kind)}</span><span class="t">${t}</span></div>`);'//NL)
      call sb_put(sb, '    }'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  $(''#clist'').innerHTML = out.join('''') || ''<div class="empty">The Book is still blank.')
      call sb_put(sb, '</div>'';'//NL)
