      call sb_put(sb, '  });'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, '// ===================================================================== society: realms, f')
      call sb_put(sb, 'aiths, the market'//NL)
      call sb_put(sb, 'const PH = { to: 0, t: [], p: [] };                   // the world''s price history'//NL)
      call sb_put(sb, 'function mergeHist(h) {'//NL)
      call sb_put(sb, '  if (!h || !h.t || !h.p) return;'//NL)
      call sb_put(sb, '  const n = h.t.length, first = h.to - n + 1;'//NL)
      call sb_put(sb, '  if (h.to < PH.to) { PH.to = 0; PH.t = []; PH.p = []; }'//NL)
      call sb_put(sb, '  for (let k = 0; k < n; k++) {'//NL)
      call sb_put(sb, '    if (first + k <= PH.to) continue;'//NL)
      call sb_put(sb, '    PH.t.push(h.t[k]); PH.p.push(h.p[k]);'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  PH.to = Math.max(PH.to, h.to);'//NL)
      call sb_put(sb, '  if (PH.t.length > 1500) { PH.t.splice(0, PH.t.length - 1500); PH.p.splice(0, PH.p.length ')
      call sb_put(sb, '- 1500); }'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'const PST = { awaiting: 1, kept: 2, failed: 3 };'//NL)
