      call sb_put(sb, 'ate] || 3;'//NL)
      call sb_put(sb, '  s.rmap = new Map(s.realms.map(m => [m.id, m]));'//NL)
      call sb_put(sb, '  for (const f of s.fallen || []) if (!s.rmap.has(f.id)) s.rmap.set(f.id, { id: f.id, name:')
      call sb_put(sb, ' f.title, title: f.title, hue: -1, fallen: true });'//NL)
      call sb_put(sb, '  s.fmap = new Map((s.faiths || []).map(f => [f.id, f]));'//NL)
