      call sb_put(sb, '    renderSociety();'//NL)
      call sb_put(sb, '  } catch (e) { /* the society route may not be there yet */ }'//NL)
      call sb_put(sb, '  socBusy = false;'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'const rName = id => { const m = G.soc && G.soc.rmap.get(id); return m ? m.name : ''realm ''')
      call sb_put(sb, ' + id; };'//NL)
      call sb_put(sb, 'const rHue = id => { const m = G.soc && G.soc.rmap.get(id); return m ? m.hue : -1; };'//NL)
