      call sb_put(sb, 'const stabCol = s => s < 0.3 ? ''#d0603e'' : s < 0.55 ? ''#d8a657'' : ''#a9c97a'';'//NL)
      call sb_put(sb, 'function sec(t, n) { return `<div class="sh">${t}${n != null ? `<span>${n}</span>` : ''''}<')
      call sb_put(sb, '/div>`; }'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, 'function renderSociety() {'//NL)
