      call sb_put(sb, '}'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, '// ------------------------------------------------------------------ realms and diplomacy'//NL)
      call sb_put(sb, 'function renderRealms(s) {'//NL)
      call sb_put(sb, '  const R = s.realms.slice().sort((a, b) => b.pop - a.pop);'//NL)
