      call sb_put(sb, NL)
      call sb_put(sb, '// ------------------------------------------------------------------ faiths and prophecies'//NL)
      call sb_put(sb, 'const PRK = [null, [''star'', ''☄'', ''starfall''], [''winter'', ''❄''], [''plague'', ')
