      call sb_put(sb, NL)
      call sb_put(sb, '// ------------------------------------------------------------------ the market'//NL)
      call sb_put(sb, 'function spark(cv, g) {'//NL)
      call sb_put(sb, '  const d = G.dpr, W = cv.width = Math.round(cv.clientWidth * d) || 116, H = cv.height = Ma')
      call sb_put(sb, 'th.round(cv.clientHeight * d) || 36;'//NL)
      call sb_put(sb, '  const ctx = cv.getContext(''2d''), P = PH.p, n = Math.min(P.length, 60);'//NL)
      call sb_put(sb, '  if (n < 2) return;'//NL)
      call sb_put(sb, '  const v = P.slice(P.length - n).map(p => p[g]);'//NL)
      call sb_put(sb, '  let lo = Math.min(...v), hi = Math.max(...v);'//NL)
      call sb_put(sb, '  if (hi - lo < 1e-6) { hi += 0.5; lo -= 0.5; }'//NL)
      call sb_put(sb, '  const pad = 2 * d, X = k => pad + (W - 2 * pad) * k / (n - 1), Y = x => H - pad - (H - 2 ')
      call sb_put(sb, '* pad) * (x - lo) / (hi - lo);'//NL)
      call sb_put(sb, '  ctx.beginPath(); ctx.moveTo(X(0), H);'//NL)
      call sb_put(sb, '  for (let k = 0; k < n; k++) ctx.lineTo(X(k), Y(v[k]));'//NL)
      call sb_put(sb, '  ctx.lineTo(X(n - 1), H); ctx.closePath();'//NL)
      call sb_put(sb, '  const gr = ctx.createLinearGradient(0, 0, 0, H);'//NL)
      call sb_put(sb, '  gr.addColorStop(0, GCOL[g] + ''55''); gr.addColorStop(1, GCOL[g] + ''00'');'//NL)
      call sb_put(sb, '  ctx.fillStyle = gr; ctx.fill();'//NL)
      call sb_put(sb, '  ctx.beginPath();'//NL)
      call sb_put(sb, '  for (let k = 0; k < n; k++) ctx[k ? ''lineTo'' : ''moveTo''](X(k), Y(v[k]));'//NL)
      call sb_put(sb, '  ctx.strokeStyle = GCOL[g]; ctx.lineWidth = 1.2 * d; ctx.lineJoin = ''round''; ctx.stroke(')
      call sb_put(sb, ');'//NL)
      call sb_put(sb, '  ctx.fillStyle = ''#fff4dc''; ctx.beginPath(); ctx.arc(X(n - 1), Y(v[n - 1]), 1.8 * d, 0, ')
      call sb_put(sb, '7); ctx.fill();'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'function pctChange(g) {'//NL)
      call sb_put(sb, '  const P = PH.p, m = G.soc.market;'//NL)
