      call sb_put(sb, '  let was = P.length >= 2 ? P[P.length - 2][g] : m.base ? m.base[g] : null;'//NL)
      call sb_put(sb, '  if (P.length >= 2 && P[P.length - 1][g] !== now) was = P[P.length - 1][g];'//NL)
      call sb_put(sb, '  if (now == null || !was) return [now, 0];'//NL)
      call sb_put(sb, '  return [now, 100 * (now / was - 1)];'//NL)
