      call sb_put(sb, '  });'//NL)
      call sb_put(sb, '  h += ''</div><div class="mkey"><span><i style="background:var(--gold)"></i>supply</span><')
      call sb_put(sb, 'span><i style="background:rgba(233,220,192,.45)"></i>demand</span><span>ratio</span></div>')
      call sb_put(sb, ''';'//NL)
      call sb_put(sb, '  // the great caravans'//NL)
      call sb_put(sb, '  const F = (s.flows || []).slice().sort((a, b) => b.vol - a.vol).slice(0, 7);'//NL)
