      call sb_put(sb, 'mb)) T.push({ by: t.by, on: t.on, rate: 1, emb: true, sanc: true });'//NL)
      call sb_put(sb, '  for (const w of s.wars || []) T.push({ by: w.a, on: w.b, rate: 1, emb: true, war: true })')
