      call sb_put(sb, '  // one realm''s ledger'//NL)
      call sb_put(sb, '  h += sec(''A Realm’s Ledger'');'//NL)
      call sb_put(sb, '  h += ''<div class="rpick">'' + s.realms.map(r => `<button data-r="${r.id}" class="${G.sel')
