      call sb_put(sb, '  if (r && r.prices) {'//NL)
      call sb_put(sb, '    const bar = (n, v, c, t) => `<span>${n}</span><span class="bb"><i style="width:${(100 *')
      call sb_put(sb, ' clamp(v, 0, 1)).toFixed(0)}%;background:${c}"></i></span><b>${t}</b>`;'//NL)
      call sb_put(sb, '    h += `<div class="rled"><div class="rbars">${bar(''openness'', r.openness, ''#9cc3e0'',')
      call sb_put(sb, ' num(r.openness, 2))}` +'//NL)
      call sb_put(sb, '      `${bar(''dependence'', r.depend, ''#d8a657'', num(100 * r.depend, 0) + ''%'')}${bar(')
      call sb_put(sb, '''shortfall'', r.shortfall, ''#d0603e'', num(100 * r.shortfall, 0) + ''%'')}` +'//NL)
      call sb_put(sb, '      `${bar(''stability'', r.stability, stabCol(r.stability), num(r.stability, 2))}</div>`')
      call sb_put(sb, ' +'//NL)
      call sb_put(sb, '      ''<table class="rtab"><tr><th>good</th><th>price</th><th>vs world</th><th>made</th><t')
