      call sb_put(sb, '  if (st.regions && st.regions.length) G.regions = st.regions;'//NL)
      call sb_put(sb, '  for (const p of st.top || []) G.names.set(p.rule, Object.assign(G.names.get(p.rule) || {}')
      call sb_put(sb, ', p));'//NL)
      call sb_put(sb, '  const fresh = mergeChron(st.chron);'//NL)
      call sb_put(sb, '  mergeSeries(st.series);'//NL)
      call sb_put(sb, '  G.labKey = ''st'' + st.tick + '':'' + (G.socN || 0);'//NL)
      call sb_put(sb, '  renderTop();'//NL)
      call sb_put(sb, '  renderPeoples();'//NL)
      call sb_put(sb, '  if (fresh || !CH.drawn) { renderChron(); CH.drawn = true; }'//NL)
      call sb_put(sb, '  if (G.view === 1 || G.view === 7) renderLegend();'//NL)
      call sb_put(sb, '  const now = performance.now();'//NL)
      call sb_put(sb, '  if (now - chartsAt > 900) { chartsAt = now; drawCharts(); }'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'let stBusy = false;'//NL)
      call sb_put(sb, 'async function pollState() {'//NL)
      call sb_put(sb, '  if (stBusy || document.hidden) return;'//NL)
      call sb_put(sb, '  stBusy = true;'//NL)
      call sb_put(sb, '  try {'//NL)
      call sb_put(sb, '    const st = await getJSON(`/state?since=${CH.since}&ser=${SER.to}&regions=${G.regions.le')
      call sb_put(sb, 'ngth ? 0 : 1}`);'//NL)
      call sb_put(sb, '    takeState(st);'//NL)
      call sb_put(sb, '    setOnline(true);'//NL)
      call sb_put(sb, '  } catch (e) { setOnline(false); }'//NL)
      call sb_put(sb, '  stBusy = false;'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'async function pollPeoples() {'//NL)
      call sb_put(sb, '  try {'//NL)
      call sb_put(sb, '    const r = await getJSON(''/peoples'');'//NL)
      call sb_put(sb, '    for (const p of r.peoples || []) G.names.set(p.rule, Object.assign(G.names.get(p.rule) ')
      call sb_put(sb, '|| {}, p));'//NL)
      call sb_put(sb, '  } catch (e) { /* */ }'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, '// ===================================================================== the title card'//NL)
      call sb_put(sb, 'function dismissTitle() {'//NL)
      call sb_put(sb, '  const t = $(''#title'');'//NL)
      call sb_put(sb, '  if (t.classList.contains(''gone'')) return;'//NL)
      call sb_put(sb, '  t.classList.add(''gone'');'//NL)
      call sb_put(sb, '  setTimeout(() => { t.style.display = ''none''; }, 1400);'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, '// ===================================================================== keys'//NL)
      call sb_put(sb, 'function onKey(ev) {'//NL)
      call sb_put(sb, '  if (ev.target.closest && ev.target.closest(''input, textarea, select'')) { if (ev.key ===')
      call sb_put(sb, ' ''Escape'') ev.target.blur(); return; }'//NL)
      call sb_put(sb, '  if (ev.ctrlKey || ev.metaKey || ev.altKey) return;'//NL)
      call sb_put(sb, '  const k = ev.key, title = !$(''#title'').classList.contains(''gone'');'//NL)
      call sb_put(sb, '  if (title) { dismissTitle(); if (k === '' '' || k === ''Escape'' || k === ''Enter'') { ev')
      call sb_put(sb, '.preventDefault(); return; } }'//NL)
      call sb_put(sb, '  const vk = VIEWS.find(v => v[4] === k || v[4] === k.toUpperCase());'//NL)
      call sb_put(sb, '  let used = true;'//NL)
      call sb_put(sb, '  switch (k) {'//NL)
      call sb_put(sb, '    case '' '': togglePause(); break;'//NL)
      call sb_put(sb, '    case ''.'': case ''>'': $(''#bstep'').click(); break;'//NL)
      call sb_put(sb, '    case ''+'': case ''='': speed(1); break;'//NL)
      call sb_put(sb, '    case ''-'': case ''_'': speed(-1); break;'//NL)
      call sb_put(sb, '    case ''d'': case ''D'': setSpeed(G.deep ? 4 : 0); break;'//NL)
      call sb_put(sb, '    case ''o'': case ''O'': $(''#orbitfs'').classList.toggle(''on''); break;'//NL)
      call sb_put(sb, '    case ''h'': case ''H'': document.body.classList.toggle(''cinema''); requestAnimationFra')
      call sb_put(sb, 'me(layout); break;'//NL)
      call sb_put(sb, '    case ''p'': case ''P'': setPurist(!G.purist); break;'//NL)
      call sb_put(sb, '    case ''?'': case ''/'': if (G.dlg === ''rules'') closeDlg(); else openDlg(''rules''); b')
      call sb_put(sb, 'reak;'//NL)
      call sb_put(sb, '    case ''l'': case ''L'': toggleLaws(); break;'//NL)
      call sb_put(sb, '    case ''s'': case ''S'': openOracle(); break;'//NL)
      call sb_put(sb, '    case ''k'': case ''K'': setTool(''speak''); break;'//NL)
      call sb_put(sb, '    case ''i'': case ''I'': setTool(''inspect''); break;'//NL)
      call sb_put(sb, '    case ''m'': case ''M'': setTool(''manna''); break;'//NL)
      call sb_put(sb, '    case ''w'': case ''W'': setTool(''wind''); break;'//NL)
      call sb_put(sb, '    case ''['': setBrush(G.r - (G.r > 8 ? 2 : 1)); break;'//NL)
      call sb_put(sb, '    case '']'': setBrush(G.r + (G.r >= 8 ? 2 : 1)); break;'//NL)
      call sb_put(sb, '    case ''b'': case ''B'': setDrawer(!$(''#drawer'').classList.contains(''open'')); break;'//NL)
      call sb_put(sb, '    case ''Escape'':'//NL)
      call sb_put(sb, '      closeDlg(); toggleLaws(false); $(''#orbitfs'').classList.remove(''on''); $(''#dossier')
      call sb_put(sb, ''').classList.remove(''on'');'//NL)
      call sb_put(sb, '      $(''#flyout'').classList.remove(''on''); document.body.classList.remove(''cinema''); ')
      call sb_put(sb, 'if (G.hl >= 0) setHL(-1); requestAnimationFrame(layout);'//NL)
      call sb_put(sb, '      break;'//NL)
      call sb_put(sb, '    default:'//NL)
      call sb_put(sb, '      if (vk) setView(vk[0]); else used = false;'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  if (used) ev.preventDefault();'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, NL)
      call sb_put(sb, '// ===================================================================== the first paint (b')
      call sb_put(sb, 'efore the load event)'//NL)
      call sb_put(sb, 'function b64bytes(s) {'//NL)
      call sb_put(sb, '  const t = atob(s), b = new Uint8ClampedArray(t.length);'//NL)
      call sb_put(sb, '  for (let k = 0; k < t.length; k++) b[k] = t.charCodeAt(k);'//NL)
      call sb_put(sb, '  return b;'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'function boot() {'//NL)
      call sb_put(sb, '  if (Q.get(''still'') === ''1'') document.body.classList.add(''still'');'//NL)
      call sb_put(sb, '  buildChrome(); buildOracle(); buildRules();'//NL)
      call sb_put(sb, '  bindPlate(); bindPeoples(); bindChron(); bindSociety(); bindLaws(); bindOrbit();'//NL)
      call sb_put(sb, '  setBrush(G.r);'//NL)
      call sb_put(sb, '  const B = B0 || {};'//NL)
      call sb_put(sb, '  if (B.w && B.h) { G.fw = B.w; G.fh = B.h; }'//NL)
      call sb_put(sb, '  if (B.state && B.state.world) { G.nx = B.state.world.nx; G.ny = B.state.world.ny; }'//NL)
      call sb_put(sb, '  G.cx = B.cx || Math.floor(G.nx / 2); G.cy = B.cy || Math.floor(G.ny / 2);'//NL)
      call sb_put(sb, '  if (Q.get(''cx'')) G.cx = wrap1(+Q.get(''cx''), G.nx);'//NL)
      call sb_put(sb, '  if (Q.get(''cy'')) G.cy = wrap1(+Q.get(''cy''), G.ny);'//NL)
      call sb_put(sb, '  if (Q.get(''z'')) G.z = clamp(+Q.get(''z''), 1, 4) >= 4 ? 4 : +Q.get(''z'') >= 2 ? 2 : 1;'//NL)
      call sb_put(sb, '  const ppl = syncJSON(''/peoples'');'//NL)
      call sb_put(sb, '  if (ppl) for (const p of ppl.peoples || []) G.names.set(p.rule, p);'//NL)
      call sb_put(sb, '  if (B.state) takeState(B.state);'//NL)
      call sb_put(sb, '  if (B.params) buildLaws(B.params.params || B.params);'//NL)
      call sb_put(sb, '  else getJSON(''/params'').then(r => buildLaws(r.params)).catch(() => {});'//NL)
      call sb_put(sb, '  const soc = B.society || syncJSON(''/society?ph=0'');'//NL)
      call sb_put(sb, '  if (soc) takeSociety(soc);'//NL)
      call sb_put(sb, '  const dOpen = Q.has(''drawer'') ? Q.get(''drawer'') === ''1'' : innerHeight >= 900;'//NL)
      call sb_put(sb, '  $(''#drawer'').classList.toggle(''open'', dOpen);'//NL)
      call sb_put(sb, '  buildDrawer(Q.get(''dtab'') || ''life'');'//NL)
      call sb_put(sb, '  layout();'//NL)
      call sb_put(sb, '  if (B.frame && B.w) {'//NL)
      call sb_put(sb, '    try {'//NL)
      call sb_put(sb, '      const px = b64bytes(B.frame);'//NL)
      call sb_put(sb, '      if (px.length >= 4 * B.w * B.h) takeFrame({ w: B.w, h: B.h, tick: B.state ? B.state.t')
      call sb_put(sb, 'ick : 0, px }, { z: 1, cx: B.cx || G.cx, cy: B.cy || G.cy });'//NL)
      call sb_put(sb, '    } catch (e) { report(''boot frame: '' + e.message); }'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  if (Q.get(''view'')) setView(+Q.get(''view''), true);'//NL)
      call sb_put(sb, '  if (Q.get(''hl'')) G.hl = +Q.get(''hl'');'//NL)
      call sb_put(sb, '  updateZoomTag();'//NL)
      call sb_put(sb, '  drawMap(); placeLabels(); drawPeopleLabels(5000); drawOverlay(performance.now());'//NL)
      call sb_put(sb, '  setPage(Q.get(''tab'') || ''chron'');'//NL)
      call sb_put(sb, '  drawCharts();'//NL)
      call sb_put(sb, '  // the title card: the spinning planet and the epigraph'//NL)
      call sb_put(sb, '  const showTitle = Q.get(''title'') !== ''0'';'//NL)
      call sb_put(sb, '  const ob = parseRLF(syncBin(''/orbit?yaw=0&pitch=0.35''));'//NL)
      call sb_put(sb, '  if (ob) paintRLF($(''#hero canvas''), ob);'//NL)
      call sb_put(sb, '  if (showTitle) {'//NL)
      call sb_put(sb, '    $(''#twn'').textContent = B.state && B.state.world ? `the world of ${B.state.world.name')
      call sb_put(sb, '}, year ${Math.floor(B.state.year)}` : '''';'//NL)
      call sb_put(sb, '    if (ob) paintRLF($(''#title canvas''), ob);'//NL)
      call sb_put(sb, '    $(''#title'').addEventListener(''click'', dismissTitle);'//NL)
      call sb_put(sb, '    if (Q.get(''still'') !== ''1'') setTimeout(dismissTitle, 4200);'//NL)
      call sb_put(sb, '  } else { $(''#title'').classList.add(''gone''); $(''#title'').style.display = ''none''; }'//NL)
      call sb_put(sb, '  const dl = Q.get(''dlg'');'//NL)
      call sb_put(sb, '  if (dl === ''oracle'') { openOracle(Q.get(''rs'') || ''B36/S23''); const d = syncJSON(''/')
      call sb_put(sb, 'oracle?rule='' + encodeURIComponent(rsOf()) + ''&seed=1''); if (d) { takeOracle(d); oracleT')
      call sb_put(sb, 'ick(); } }'//NL)
      call sb_put(sb, '  else if (dl === ''rules'') openDlg(''rules'');'//NL)
      call sb_put(sb, '  else if (dl === ''laws'') toggleLaws(true);'//NL)
      call sb_put(sb, '  if (Q.get(''dossier'')) {'//NL)
      call sb_put(sb, '    const [x, y] = Q.get(''dossier'').split('','').map(Number), d = syncJSON(`/inspect?x=${')
      call sb_put(sb, 'x}&y=${y}`);'//NL)
      call sb_put(sb, '    if (d) pinDossier(x, y, d);'//NL)
      call sb_put(sb, '  }'//NL)
      call sb_put(sb, '  // bindings that need everything above'//NL)
      call sb_put(sb, '  $(''#dhead'').addEventListener(''click'', ev => {'//NL)
      call sb_put(sb, '    const t = ev.target.closest(''.tab'');'//NL)
      call sb_put(sb, '    if (t) { buildDrawer(t.dataset.t); if (!$(''#drawer'').classList.contains(''open'')) se')
      call sb_put(sb, 'tDrawer(true); return; }'//NL)
      call sb_put(sb, '    setDrawer(!$(''#drawer'').classList.contains(''open''));'//NL)
      call sb_put(sb, '  });'//NL)
      call sb_put(sb, '  $(''#veil'').addEventListener(''click'', closeDlg);'//NL)
      call sb_put(sb, '  document.addEventListener(''keydown'', onKey);'//NL)
      call sb_put(sb, '  window.addEventListener(''resize'', () => { layout(); drawCharts(); });'//NL)
      call sb_put(sb, '  // and then the loops'//NL)
      call sb_put(sb, '  requestAnimationFrame(animLoop);'//NL)
      call sb_put(sb, '  frameLoop();'//NL)
      call sb_put(sb, '  orbitLoop();'//NL)
      call sb_put(sb, '  setInterval(pollState, 250);'//NL)
      call sb_put(sb, '  setInterval(() => pollSociety(), 1000);'//NL)
      call sb_put(sb, '  setInterval(pollPeoples, 20000);'//NL)
      call sb_put(sb, '  setTimeout(() => report(`page ok: ${innerWidth}x${innerHeight}, frame ${G.fw}x${G.fh}, ${')
      call sb_put(sb, 'G.regions.length} regions, ` +'//NL)
      call sb_put(sb, '    `${CH.list.length} entries, society ${G.soc ? G.soc.realms.length + '' realms'' : ''abs')
      call sb_put(sb, 'ent''}`), 3000);'//NL)
      call sb_put(sb, '  const nf0 = { n: 0, t: 0 };'//NL)
      call sb_put(sb, '  setTimeout(() => { nf0.n = G.nframes; nf0.t = performance.now(); }, 2000);'//NL)
      call sb_put(sb, '  setTimeout(() => report(`page fps ${((G.nframes - nf0.n) * 1000 / (performance.now() - nf')
      call sb_put(sb, '0.t)).toFixed(1)} ` +'//NL)
      call sb_put(sb, '    `(frames from /frame), ${CH.list.length} entries, ${SER.to} samples`), 9000);'//NL)
      call sb_put(sb, '}'//NL)
      call sb_put(sb, 'G.nframes = 0;'//NL)
      call sb_put(sb, 'try { boot(); } catch (e) { report(''boot failed: '' + (e.stack || e.message)); throw e; }'//NL)
      call sb_put(sb, '</script>'//NL)
      call sb_put(sb, '</body>'//NL)
      call sb_put(sb, '</html>'//NL)
   end subroutine page_html

end module rl_page

!=======================================================================
!  rl_web -- the server of REAL LIFE.  It keeps the calling sequence of
!  the world (a new world, the commands between ticks, a tick) and it
!  answers the browser: the page, frames of the map and of the orbit, the
!  state of the world as JSON, the sliders, the Hand's commands, the
!  inspector, the Oracle and the roll of peoples.  rl_net speaks HTTP;
!  web_route builds every answer, so it can be tried without a socket.
!=======================================================================
module rl_web
   use rl_core
   use rl_terra,     only: terra_params, terra_init, terra_step, terra_command, terra_sun_tables
   use rl_climate,   only: climate_params, climate_init, climate_step, climate_command, &
                           climate_tilt_changed
   use rl_flora,     only: flora_params, flora_init, flora_step, flora_command
   use rl_life,      only: life_params, life_init, life_step, life_command, life_oracle, &
                           life_gliders
   use rl_spirits,   only: spirits_params, spirits_init, spirits_step, spirits_command
   use rl_fauna,     only: fauna_params, fauna_init, fauna_step, fauna_command
   use rl_observe,   only: observe_init, observe_step, observe_json, observe_json_hist
   use rl_chronicle, only: chronicle_params, chronicle_command, chronicle_init, chronicle_step, &
                           chronicle_json, people_name, &
                           people_title, region_at, titan_name, strain_name, famous_rule, &
                           realm_name, realm_title, ruler_name, faith_name, prophet_name, &
                           prophecy_text
   use rl_soc,       only: soc_alloc, soc_clear, pol, npol, war, ally, pact, sanction, tariff, &
                           rel, tradevol, borders, faiths, nfaith, prophs, nproph, wprice, &
                           wsupply, wdemand, wtrade, phist, phist_tick, nphist, MHIST, flows, &
                           nflow, NGOODS, GOOD_NAME, GOV_NAME, NVIEWS_ALL, CMD_PROPHET, &
                           PR_STAR, PR_WINTER, PR_PLAGUE, PR_FALL, PR_RISE, PR_MANNA, PR_TITAN, &
                           PR_RAIN, PR_VICTORY, PR_LAZARUS, PR_FIRE, PR_THAW
   use rl_polity,    only: polity_params, polity_init, polity_step, polity_command
   use rl_faith,     only: faith_params, faith_init, faith_step, faith_command
   use rl_market,    only: market_params, market_init, market_step, market_command
   use rl_render,    only: render_params, render_init, render_tick, render_map, render_orbit
   use rl_net,       only: req_t, net_open, net_next, net_reply, net_close_all, qval, qnum
   use rl_page,      only: page_html
   use, intrinsic :: iso_c_binding, only: c_int, c_int64_t, c_ptr, c_loc
   use, intrinsic :: ieee_arithmetic, only: ieee_is_finite
   implicit none
   private
   public :: world_setup, world_new, world_apply, world_tick, world_purist, fresh_seed
   public :: web_open, web_poll, web_close, web_route, web_body, web_ctype, web_status
   public :: view_code, view_name, parse_rule, b64_put, wall, tick_budget, day_length

   integer(i8), public, protected :: web_frames = 0     ! map frames served
   integer(i8), public, protected :: web_ticks = 0      ! ticks run by this process
   integer(i8), public, protected :: web_requests = 0   ! requests answered
   integer,     public, protected :: web_worlds = 0     ! worlds made (the page's 'gen')
   real(dp),    public, protected :: tick_ms = 0, frame_ms = 0, orbit_ms = 0, state_ms = 0
   logical,     public, protected :: hardened = .false.  ! send timeout and TCP_NODELAY are set

   interface
      function c_getsockopt(fd, lvl, opt, val, ln) bind(c, name='getsockopt') result(r)
         import :: c_int, c_ptr
         integer(c_int), value :: fd, lvl, opt
         type(c_ptr),    value :: val, ln
         integer(c_int) :: r
      end function c_getsockopt
      function c_setsockopt(fd, lvl, opt, val, ln) bind(c, name='setsockopt') result(r)
         import :: c_int, c_ptr
         integer(c_int), value :: fd, lvl, opt, ln
         type(c_ptr),    value :: val
         integer(c_int) :: r
      end function c_setsockopt
   end interface

   ! ================================================================ replies and the frame cache
   integer, parameter :: K_SB = 0, K_PAGE = 1, K_FRAME = 2, K_ORBIT = 3   ! where a body lies
   integer, parameter :: NSLOT = 4, BIG = 1000000
   type frame_t
      integer :: view = -1, zoom = 0, cx = 0, cy = 0, hl = -2, w = 0, h = 0
      integer(i8) :: ver = -1, used = 0
      real(dp) :: yaw = 0, pitch = 0
      character(len=:), allocatable :: rep      ! the 'RLF1' header and the RGBA, ready to send
   end type frame_t
   type(frame_t) :: fc(NSLOT), orb
   character(len=:), allocatable :: img, oimg   ! the renderer's canvases (map, orbit)
   type(sbuf_t) :: sb, pg                       ! the reply being built; the page, built once
   integer :: rkind = K_SB, rslot = 1
   character(len=40) :: rtype = '', rstat = ''
   integer(i8) :: wver = 0, nuse = 0            ! world version (any change bumps it); cache clock

   ! ================================================================ remembered between requests
   integer, allocatable :: roster(:)                ! every rule that has ever been notable
   integer :: nros = 0, nsig = -1, ngen = -1
   integer(i8) :: nscan = 0
   real(dp) :: lam_c = 0                        ! mean lambda of the living, at version lam_v
   integer(i8) :: lam_v = -1
   integer(i1), allocatable :: clsc(:)          ! the Oracle's verdict per rule (0: not asked yet)
   character(len=16) :: cname(32) = ''          ! the verdicts heard so far
   integer :: ncname = 0
   integer :: kp_graze = 0, kp_upkeep = 0, kp_price = 0, kp_heat = 0, kp_sigt = 0, &
              kp_ewill = 0, kp_vbirth = 0, kp_span = 0, kp_lum = 0, kp_budget = 0, kp_day = 0
   character(len=12), parameter :: FLAGW(0:11) = [character(len=12) :: 'wanderers', &
      'seafarers', 'star-scarred', 'plagued', 'twice-born', 'hunters', 'frost-folk', &
      'roadwalkers', 'hybrid', 'legend', 'dread', 'blessed']
   character(len=8), parameter :: VNAME(0:NVIEWS_ALL-1) = [character(len=8) :: 'living', &
      'peoples', 'climate', 'water', 'frost', 'verdure', 'awe', 'plague', 'rules', 'purist', &
      'relief', 'realms', 'faiths', 'trade']
   character(len=8), parameter :: PRWORD(12) = [character(len=8) :: 'star', 'winter', &
      'plague', 'fall', 'rise', 'manna', 'titan', 'rain', 'victory', 'lazarus', 'fire', 'thaw']
   real(dp), parameter :: GOOD_BASE(6) = [1d0, 1.5d0, 2d0, 3d0, 5d0, 8d0]
   integer,  parameter :: MAXFLOWS_SHOWN = 24
   character(len=12), parameter :: SEASONS(0:11) = [character(len=12) :: 'Early Spring', &
      'Spring', 'Late Spring', 'Early Summer', 'High Summer', 'Late Summer', 'Early Autumn', &
      'Autumn', 'Late Autumn', 'Early Winter', 'Deep Winter', 'Late Winter']

contains

   ! ================================================================ the world (SPEC 2.2)

   subroutine world_setup(nx_, ny_)
      ! the board and its laws: the blackboard, then every module registers its sliders
      integer, intent(in) :: nx_, ny_
      call core_alloc(nx_, ny_)
      call soc_alloc()
      call terra_params();  call climate_params();  call flora_params()
      call life_params();  call spirits_params();  call fauna_params()
      call polity_params();  call faith_params();  call market_params()
      call chronicle_params();  call render_params()
      kp_budget = reg_param('budget', 'Tick budget', 'Time', 12d0, 4d0, 40d0, &
         'Milliseconds of simulation between two looks at the browser: more lets a slow '// &
         'world keep pace, less keeps the page lively.')
      kp_day = reg_param('daylength', 'Length of a day', 'Time', 45d0, 5d0, 600d0, &
         'Seconds of wall time for one turn of the planet, and so for the night to sweep '// &
         'round once.', logs=.true.)
      kp_graze = find_param('graze');    kp_upkeep = find_param('upkeep')
      kp_price = find_param('priceoflife');  kp_heat = find_param('heatcost')
      kp_sigt = find_param('sigmat');    kp_ewill = find_param('ewill')
      kp_vbirth = find_param('vbirth');  kp_span = find_param('lifespan')
      kp_lum = find_param('lum')
      if (.not. allocated(clsc)) then
         allocate(clsc(0:65535))
         clsc = 0
         cname(1:6) = [character(len=16) :: 'Barren', 'Still', 'Oscillating', 'Chaotic', &
                       'Explosive', 'Complex']
         ncname = 6
      end if
      if (.not. allocated(roster)) allocate(roster(256))
      if (.not. allocated(sb%s)) call sb_put(sb, '')
      if (.not. allocated(pg%s)) call sb_put(pg, '')
   end subroutine world_setup

   subroutine world_new(seed)
      ! a new world from a seed; the Conway limit is left first and entered again after
      integer, intent(in) :: seed
      logical :: was
      was = purist
      if (was) call world_purist(.false.)
      call core_clear()
      world_seed = seed
      call rng_seed(seed)
      call terra_init();  call soc_clear()
      call climate_init();  call flora_init();  call life_init()
      call spirits_init();  call fauna_init()
      call polity_init();  call faith_init();  call market_init()
      call observe_init();  call chronicle_init()
      call render_init()
      if (climate_tilt_changed) then
         call terra_sun_tables()
         climate_tilt_changed = .false.
      end if
      web_worlds = web_worlds + 1;  wver = wver + 1
      if (was) call world_purist(.true.)
   end subroutine world_new

   subroutine world_apply()
      ! hand the queued commands to every module (between ticks, and also while paused)
      type(cmd_t) :: q(CMDQMAX)
      integer :: n, k
      if (ncmd == 0) return
      n = ncmd
      q(1:n) = cmdq(1:n)
      ncmd = 0                                  ! what the modules push now waits for the next tick
      do k = 1, n
         call dispatch(q(k))
      end do
      wver = wver + 1
   end subroutine world_apply

   subroutine dispatch(c)
      ! one command to every module; the main program's own controls are done here
      type(cmd_t), intent(in) :: c
      select case (c%kind)
      case (CMD_PAUSE)
         paused = .true.
      case (CMD_PLAY)
         paused = .false.
      case (CMD_SPEED)
         tpf = clampi(c%v, 0, 64)
      case (CMD_STEP, CMD_RESET)                 ! the server does these itself, at once
      case default
         if (c%kind == CMD_PURIST) purist = c%v > 0.5d0
         call terra_command(c);  call climate_command(c);  call flora_command(c)
         call life_command(c);  call spirits_command(c);  call fauna_command(c)
         call polity_command(c);  call faith_command(c);  call market_command(c)
         call chronicle_command(c)
      end select
   end subroutine dispatch

   subroutine world_tick()
      ! one tick: the queued commands, then every module in the order of SPEC 2.2
      real(dp) :: t0
      t0 = wall()
      call world_apply()
      call terra_step();  call climate_step();  call flora_step();  call life_step()
      call spirits_step();  call fauna_step()
      call polity_step();  call faith_step();  call market_step()
      call observe_step();  call chronicle_step()
      call render_tick()
      tick = tick + 1
      if (climate_tilt_changed) then             ! the tilt slider moved: new sunlight tables
         call terra_sun_tables()
         climate_tilt_changed = .false.
      end if
      web_ticks = web_ticks + 1;  wver = wver + 1
      tick_ms = ema(tick_ms, 1d3*(wall() - t0))
   end subroutine world_tick

   subroutine world_purist(on)
      ! enter or leave the Conway limit at once
      logical, intent(in) :: on
      if (on .eqv. purist) return
      call dispatch(cmd_t(kind=CMD_PURIST, v=merge(1d0, 0d0, on), hand=.false.))
      wver = wver + 1
   end subroutine world_purist

   integer function fresh_seed()
      ! a new seed from the clock, 1 .. 99999
      integer(i8) :: c
      call system_clock(c)
      fresh_seed = 1 + int(mod(mix32(iand(c, 4294967295_i8)), 99999_i8))
   end function fresh_seed

   real(dp) function tick_budget()
      ! seconds the ticks may run before the browser is heard again (the 'budget' law)
      tick_budget = 1d-3*law(kp_budget, 12d0)
   end function tick_budget

   real(dp) function day_length()
      ! seconds of wall time for one turn of the planet (the 'daylength' law)
      day_length = max(1d0, law(kp_day, 45d0))
   end function day_length

   ! ================================================================ the server

   logical function web_open(port0)
      ! listen on 127.0.0.1, on the first free port from port0 up (rl_net keeps it in net_port)
      integer, intent(in) :: port0
      web_open = net_open(port0)
      if (web_open) call harden()
   end function web_open

   subroutine web_poll(wait_ms, got)
      ! answer the next request if one arrives within wait_ms
      integer, intent(in)  :: wait_ms
      logical, intent(out) :: got
      type(req_t) :: rq
      call net_next(rq, got, wait_ms)
      if (.not. got) return
      call web_route(rq%path, rq%query)
      select case (rkind)
      case (K_PAGE)
         call net_reply(rq, trim(rtype), pg%s(1:pg%n), trim(rstat))
      case (K_FRAME)
         call net_reply(rq, trim(rtype), fc(rslot)%rep, trim(rstat))
      case (K_ORBIT)
         call net_reply(rq, trim(rtype), orb%rep, trim(rstat))
      case default
         call net_reply(rq, trim(rtype), sb%s(1:sb%n), trim(rstat))
      end select
   end subroutine web_poll

   subroutine web_close()
      ! hang up on everyone and stop listening
      call net_close_all()
   end subroutine web_close

   subroutine harden()
      ! Connections inherit two options from the listening socket: a send timeout, so that a
      ! browser that stops reading is dropped (rl_net closes it when send fails) after about
      ! two seconds instead of freezing the world, and TCP_NODELAY, so that a small reply is
      ! not held back 40 ms by Nagle's rule (rl_net sends the header and the body apart).
      ! Linux, then BSD.
      integer, parameter :: SOL(2) = [1, 65535], ACCEPTING(2) = [30, 2], SNDTIMEO(2) = [21, 4101]
      integer(c_int),     target :: v, ln
      integer(c_int64_t), target :: tv(2)
      integer(c_int) :: fd, r1, r2
      integer :: lay
      do fd = 0, 1023
         do lay = 1, 2
            v = 0;  ln = 4
            if (c_getsockopt(fd, int(SOL(lay), c_int), int(ACCEPTING(lay), c_int), c_loc(v), &
                             c_loc(ln)) /= 0) cycle
            if (v == 0) cycle
            tv = [1_c_int64_t, 0_c_int64_t]                ! 1 s
            r1 = c_setsockopt(fd, int(SOL(lay), c_int), int(SNDTIMEO(lay), c_int), c_loc(tv), &
                              16_c_int)
            v = 1
            r2 = c_setsockopt(fd, 6_c_int, 1_c_int, c_loc(v), 4_c_int)   ! IPPROTO_TCP, NODELAY
            hardened = r1 == 0 .and. r2 == 0
            return
         end do
      end do
   end subroutine harden

   ! ================================================================ the routes

   subroutine web_route(path, query)
      ! build the answer to one request (its body, type and status); web_poll sends it
      character(*), intent(in) :: path, query
      real(dp) :: t0
      t0 = wall()
      if (.not. allocated(sb%s)) call sb_put(sb, '')
      call sb_clear(sb)
      rkind = K_SB;  rtype = 'application/json; charset=utf-8';  rstat = '200 OK'
      web_requests = web_requests + 1
      select case (path)
      case ('/', '/index.html')
         call r_page()
      case ('/boot.js')
         call r_boot()
      case ('/frame')
         call r_frame(query)
      case ('/orbit')
         call r_orbit(query)
      case ('/state')
         call r_state(query)
         state_ms = ema(state_ms, 1d3*(wall() - t0))
      case ('/params')
         call params_json(qint(query, 'all', 0, 0, 1) == 1)
      case ('/set')
         call r_set(query)
      case ('/cmd')
         call r_cmd(query)
      case ('/inspect')
         call r_inspect(query)
      case ('/oracle')
         call r_oracle(query)
      case ('/peoples')
         call r_peoples()
      case ('/society')
         call r_society(query)
      case ('/log')
         call r_log(query)
      case ('/favicon.ico')
         rstat = '204 No Content'
      case default
         rtype = 'text/plain; charset=utf-8';  rstat = '404 Not Found'
         call sb_put(sb, 'REAL LIFE has nothing at '//path(1:min(len(path), 200))//NL)
      end select
   end subroutine web_route

   function web_body() result(s)
      ! the body of the last answer (a copy, for tests)
      character(len=:), allocatable :: s
      select case (rkind)
      case (K_PAGE)
         s = pg%s(1:pg%n)
      case (K_FRAME)
         s = fc(rslot)%rep
      case (K_ORBIT)
         s = orb%rep
      case default
         s = sb%s(1:sb%n)
      end select
   end function web_body

   function web_ctype() result(s)
      ! the content type of the last answer
      character(len=:), allocatable :: s
      s = trim(rtype)
   end function web_ctype

   function web_status() result(s)
      ! the HTTP status of the last answer
      character(len=:), allocatable :: s
      s = trim(rstat)
   end function web_status

   subroutine r_page()
      ! the page itself (rl_page writes it once)
      if (pg%n == 0) call page_html(pg)
      rkind = K_PAGE;  rtype = 'text/html; charset=utf-8'
   end subroutine r_page

   subroutine r_boot()
      ! window.BOOT: the living map (base64 RGBA), the state and the sliders, so that the
      ! page can paint before its load event
      integer :: k, cx, cy
      cx = NX/2;  cy = NY/2
      call frame_get(VIEW_LIVING, 1, cx, cy, -1, k)
      call sb_put(sb, 'window.BOOT={w:'//itoa(fc(k)%w)//',h:'//itoa(fc(k)%h)//',cx:'// &
                      itoa(cx)//',cy:'//itoa(cy)//',frame:"')
      call b64_put(sb, fc(k)%rep(17:), len(fc(k)%rep) - 16)
      call sb_put(sb, '",state:')
      call state_json(0, 0, .true.)
      call sb_put(sb, ',params:')
      call params_json(.false.)
      call sb_put(sb, '};'//NL)
      rtype = 'text/javascript; charset=utf-8'
   end subroutine r_boot

   subroutine r_frame(q)
      ! /frame?v=&z=&cx=&cy=&hl=: 'RLF1', w, h, tick (int32, little endian), then RGBA
      character(*), intent(in) :: q
      integer :: v, z
      v = view_code(qval(q, 'v'))
      if (v < 0) v = VIEW_LIVING
      z = qint(q, 'z', 1, 1, 4)
      if (z == 3) z = 2
      call frame_get(v, z, wrapi(qint(q, 'cx', NX/2, -BIG, BIG)), &
                     wrapj(qint(q, 'cy', NY/2, -BIG, BIG)), qint(q, 'hl', -1, -1, 65535), rslot)
      rkind = K_FRAME;  rtype = 'application/octet-stream'
      web_frames = web_frames + 1
   end subroutine r_frame

   subroutine r_orbit(q)
      ! /orbit?yaw=&pitch=: the doughnut from space, in the same binary format
      character(*), intent(in) :: q
      real(dp) :: yaw, pitch, t0
      integer :: w, h
      yaw = qreal(q, 'yaw', 0d0);  pitch = qreal(q, 'pitch', 0d0)
      if (orb%ver /= wver .or. abs(yaw - orb%yaw) > 0 .or. abs(pitch - orb%pitch) > 0) then
         t0 = wall()
         call render_orbit(yaw, pitch, oimg, w, h)
         orbit_ms = ema(orbit_ms, 1d3*(wall() - t0))
         call pack_frame(orb, oimg, w, h)
         orb%ver = wver;  orb%yaw = yaw;  orb%pitch = pitch
      end if
      rkind = K_ORBIT;  rtype = 'application/octet-stream'
   end subroutine r_orbit

   subroutine r_state(q)
      ! /state?since=<chronicle id>&ser=<sample index>&regions=0|1
      character(*), intent(in) :: q
      call state_json(qint(q, 'since', 0, 0, huge(1)), qint(q, 'ser', 0, 0, huge(1)), &
                      qint(q, 'regions', 0, 0, 1) == 1)
   end subroutine r_state

   subroutine r_set(q)
      ! /set?k=key&v=value: a law moves (clamped to its range); without v it is only read;
      ! k=* restores every default
      character(*), intent(in) :: q
      character(len=:), allocatable :: k
      integer :: p
      logical :: ok
      ok = .true.
      k = trim(adjustl(qval(q, 'k')))
      if (k == '*') then
         call reset_params()
         call sb_put(sb, '{"ok":true,"n":'//itoa(npar)//'}')
         return
      end if
      p = 0
      if (len(k) > 0) p = find_param(k)
      if (p == 0) then
         call sb_put(sb, '{"ok":false,"err":'//jstr('there is no law called "'//k//'"')//'}')
         return
      end if
      if (len(qval(q, 'v')) > 0) ok = set_param(k, qreal(q, 'v', pv(p)))
      call jo('');  call jb('ok', ok);  call js('k', k);  call jr('v', pv(p));  call jend('}')
   end subroutine r_set

   subroutine r_cmd(q)
      ! /cmd?c=name&x=&y=&r=&v=&s=: the controls act at once; the Hand's deeds are queued
      character(*), intent(in) :: q
      character(len=:), allocatable :: c, s, err
      integer :: kind, x, y, r, g
      real(dp) :: v, v2
      c = lower(trim(adjustl(qval(q, 'c'))));  s = trim(adjustl(qval(q, 's')))
      x = wrapi(qint(q, 'x', NX/2, -BIG, BIG));  y = wrapj(qint(q, 'y', NY/2, -BIG, BIG))
      r = qint(q, 'r', 6, 1, 64)
      v = qreal(q, 'v', 0d0);  v2 = qreal(q, 'v2', 0d0)
      kind = 0;  g = 0;  err = ''
      select case (c)
      case ('pause')
         paused = .true.
      case ('play')
         paused = .false.
      case ('step')
         paused = .true.
         call world_tick()
      case ('speed')
         tpf = qint(q, 'v', tpf, 0, 64)
      case ('reset')
         g = qint(q, 'v', 0, 0, huge(1))
         if (g == 0) g = fresh_seed()
         call world_new(g)
         write(output_unit, '(a)') '   a new world: '//trim(world_name)//', seed '//itoa(g)
         flush(output_unit)
      case ('purist')
         call world_purist(v > 0.5d0)
      case ('sow')
         kind = CMD_SOW
         call sow_genome(s, v, g, err)
         v = g
      case ('manna');       kind = CMD_MANNA
      case ('lightning');   kind = CMD_LIGHTNING
      case ('rain');        kind = CMD_RAIN
      case ('wind');        kind = CMD_WIND
      case ('pestilence');  kind = CMD_PESTILENCE
      case ('starfall');    kind = CMD_STARFALL
      case ('raise');       kind = CMD_RAISE
      case ('lower');       kind = CMD_LOWER
      case ('freeze');      kind = CMD_FREEZE
      case ('thaw');        kind = CMD_THAW
      case ('locusts');     kind = CMD_LOCUSTS
      case ('smite');       kind = CMD_SMITE
      case ('speak');       kind = CMD_PROPHET
      case ('sweep');       kind = CMD_SWEEP
      case ('titan')
         kind = CMD_TITAN
         s = turmite(s)
      case ('stamp')
         kind = CMD_STAMP
         s = pattern(s)
      case default
         err = 'there is no command called "'//c//'"'
      end select
      if (len(err) == 0 .and. kind > 0) then
         if (ncmd >= CMDQMAX) then
            err = 'the Hand is busy: the command queue is full'
         else
            call push_cmd(cmd_t(kind=kind, x=x, y=y, r=r, v=v, v2=v2, s=s, hand=.true.))
         end if
      end if
      if (len(err) > 0) then
         call sb_put(sb, '{"ok":false,"err":'//jstr(err)//'}')
         return
      end if
      call jo('')
      call jb('ok', .true.);  call js('c', c);  call jl('tick', tick);  call jb('paused', paused)
      call ji('tpf', tpf);  call jb('purist', purist);  call ji('seed', world_seed)
      call ji('gen', web_worlds);  call ji('queued', ncmd)
      if (kind == CMD_SOW) then
         call ji('genome', g);  call js('rs', rule_str(g_rule(g)))
      end if
      if (kind == CMD_TITAN .or. kind == CMD_STAMP) call js('s', s)
      call jend('}')
   end subroutine r_cmd

   subroutine sow_genome(s, v, g, err)
      ! the genome to sow: s = 'people:<rule>' (one of that people's own); s = 'B36/S23' (the
      ! traits of v if v is a genome, else pigment 8, T* 18.5 C, a grazer); v alone; or the
      ! Conwayans
      character(*), intent(in) :: s
      real(dp),     intent(in) :: v
      integer,      intent(out) :: g
      character(len=:), allocatable, intent(inout) :: err
      integer :: r, gv
      gv = 0
      if (v >= 1 .and. v < 2147483648d0) gv = nint(v)
      g = g_make(RULE_CONWAY, 8, 19, 0)
      if (len(s) > 7) then
         if (lower(s(1:7)) == 'people:') then
            r = parse_rule(s(8:))
            if (r < 0) then
               err = 'there is no people "'//s(8:)//'"'
            else
               g = sample_genome(r)
            end if
            return
         end if
      end if
      if (len(s) > 0) then
         r = parse_rule(s)
         if (r == -2) then
            err = '"'//s//'" asks for B0 or B1, and nothing here is born alone'
         else if (r < 0) then
            err = '"'//s//'" is not a rule (write it like B36/S23)'
         else if (gv > 0) then
            g = g_make(r, g_pig(gv), g_topt(gv), g_diet(gv))
         else
            g = g_make(r, 8, 19, 0)
         end if
      else if (gv > 0) then
         g = gv
      end if
   end subroutine sow_genome

   integer function sample_genome(r) result(g)
      ! a genome of the people r: a living cell's, else one made from the people's means
      integer, intent(in) :: r
      integer :: i, j
      do j = 1, NY
         do i = 1, NX
            if (alive(i,j) /= 0) then
               if (g_rule(gene(i,j)) == r) then
                  g = gene(i,j)
                  return
               end if
            end if
         end do
      end do
      if (ppl(r)%t_first >= 0) then
         g = g_make(r, nint(ppl(r)%pig), nint((ppl(r)%topt + 10)/1.5), nint(ppl(r)%diet))
      else
         g = g_make(r, 8, 19, 0)
      end if
   end function sample_genome

   function turmite(s) result(t)
      ! a Titan's rule: the letters R, L, N and U only, at most 16 of them ('RL' if none)
      character(*), intent(in) :: s
      character(len=:), allocatable :: t, u
      integer :: k
      u = upper(s)
      t = ''
      do k = 1, len(u)
         if (index('RLNU', u(k:k)) > 0 .and. len(t) < 16) t = t//u(k:k)
      end do
      if (len(t) == 0) t = 'RL'
   end function turmite

   function pattern(s) result(t)
      ! a pattern's name in lower case without spaces or dashes, with a few common aliases
      character(*), intent(in) :: s
      character(len=:), allocatable :: t, u
      integer :: k
      u = lower(s)
      t = ''
      do k = 1, len(u)
         if (index(' -_', u(k:k)) == 0 .and. len(t) < 32) t = t//u(k:k)
      end do
      select case (t)
      case ('')
         t = 'glider'
      case ('rpentomino', 'r', 'methuselah')
         t = 'rpent'
      case ('gun', 'gospergun', 'glidergun')
         t = 'gosper'
      case ('spaceship', 'lightweightspaceship')
         t = 'lwss'
      end select
   end function pattern

   subroutine r_inspect(q)
      ! /inspect?x=&y=: a dossier of the cell, why it fares as it does, and its people's card
      character(*), intent(in) :: q
      integer :: i, j, g, r
      logical :: live
      i = wrapi(qint(q, 'x', NX/2, -BIG, BIG));  j = wrapj(qint(q, 'y', NY/2, -BIG, BIG))
      live = alive(i,j) /= 0
      g = gene(i,j);  r = -1
      if (live) r = g_rule(g)
      call jo('')
      call ji('x', i);  call ji('y', j);  call jr('elev', real(elev(i,j), dp))
      call ji('land', int(land(i,j)));  call js('region', region_at(i, j))
      call ji('regionId', region(i,j));  call ji('mass', mass(i,j))
      call jr('temp', real(temp(i,j), dp));  call ji('ice', int(ice(i,j)))
      call jr('wet', real(wet(i,j), dp));  call jr('rain', real(rain(i,j), dp))
      call jr('cloud', real(cloud(i,j), dp));  call jr('flow', real(flow(i,j), dp))
      call jr('verd', real(verd(i,j), dp));  call jr('ash', real(ash(i,j), dp))
      call ji('fire', int(fire(i,j)));  call ji('alive', merge(1, 0, live));  call ji('rule', r)
      if (live) then
         call js('rs', rule_str(r));  call js('people', people_name(r))
         call js('title', people_title(r));  call jr('energy', real(energy(i,j), dp))
         call ji('age', age(i,j));  call jr('ageYears', real(age(i,j), dp)/TPY)
         call ji('pig', g_pig(g));  call jr('topt', real(topt_degc(g_topt(g)), dp))
         call ji('diet', g_diet(g));  call ji('genome', g)
      else
         call js('rs', '');  call js('people', '');  call js('title', '')
         call jr('energy', 0d0);  call ji('age', 0);  call jr('ageYears', 0d0)
         call ji('pig', 0);  call jr('topt', 0d0);  call ji('diet', 0);  call ji('genome', 0)
      end if
      call ji('awe', int(awe(i,j)));  call ji('sick', int(sick(i,j)))
      if (live .and. sick(i,j) > 0) then
         call js('plague', strain_name(int(strain(i,j))))
      else
         call js('plague', '')
      end if
      call ji('furrow', int(furrow(i,j)))
      if (seedg(i,j) /= 0) then
         call js('seed', people_name(g_rule(seedg(i,j))))
      else
         call js('seed', '')
      end if
      call js('why', why_line(i, j))
      if (live) then
         call people_card(r)
      else if (seedg(i,j) /= 0) then
         call people_card(g_rule(seedg(i,j)))
      else
         call jkey('card');  call sb_put(sb, 'null')
      end if
      call jend('}')
   end subroutine r_inspect

   function why_line(i, j) result(s)
      ! one line on how the cell at (i,j) fares and why, from the energy budget of SPEC 3.4
      integer, intent(in) :: i, j
      character(len=:), allocatable :: s, word, st
      real(dp) :: eat, cost, clam, ct, dt, sig, span, sen
      integer :: g, d
      if (purist) then
         s = 'the Conway limit: B3/S23 alone decides, on land and sea alike'
         return
      end if
      if (alive(i,j) == 0) then
         if (fire(i,j) > 0) then
            s = 'burning'
         else if (land(i,j) == 0 .and. ice(i,j) < 0) then
            s = 'open sea: no life can stand here'
         else if (ice(i,j) > 0) then
            s = 'ice: only the frost-adapted (T* at most 2 C) can live here'
         else if (verd(i,j) < law(kp_vbirth, 0.04d0)) then
            s = 'too poor for a birth (verdure '//ftoa(real(verd(i,j), dp), 3)//' < '// &
                ftoa(law(kp_vbirth, 0.04d0), 2)//')'
         else
            s = 'empty, fertile ground (verdure '//ftoa(real(verd(i,j), dp), 2)//')'
         end if
         if (seedg(i,j) /= 0) s = s//'; seeds of the '//trim(people_name(g_rule(seedg(i,j))))// &
                                  ' sleep here'
         return
      end if
      g = gene(i,j);  d = g_diet(g)
      sig = max(1d-3, law(kp_sigt, 8d0))
      eat = law(kp_graze, 0.05d0)*(1 - d/7d0)*verd(i,j)
      dt = temp(i,j) - topt_degc(g_topt(g))
      clam = law(kp_price, 0.02d0)*lam(g_rule(g))
      ct = law(kp_heat, 0.004d0)*(dt/sig)**2
      cost = law(kp_upkeep, 0.008d0) + clam + ct
      if (sick(i,j) > 0) cost = cost + 0.02d0
      if (awe(i,j) > 0) cost = 0.75d0*cost
      span = max(1d0, law(kp_span, 3d0)*TPY)
      sen = min(1d0, age(i,j)/span)**6
      word = 'cold'
      if (dt > 0) word = 'heat'
      if (abs(dt) > 3*sig) then
         st = 'dying of the '//word
      else if (sick(i,j) > 0) then
         st = 'sick with '//trim(strain_name(int(strain(i,j))))
      else if (energy(i,j) < 0.05) then
         st = 'starving to death'
      else if (energy(i,j) < law(kp_ewill, 0.25d0)) then
         st = 'hungry: too weak to consent to a birth'
      else if (sen > 0.01d0) then
         st = 'old: '//ftoa(100*sen, 1)//'% a tick to die of age'
      else if (eat >= cost) then
         st = 'thriving'
      else
         st = 'living on its reserves'
      end if
      s = 'grazing '//ftoa(eat, 3)//' vs upkeep '//ftoa(cost, 3)//' (λ '// &
          ftoa(real(lam(g_rule(g)), dp), 2)//', '//word//' stress '//ftoa(ct, 3)//'): '//st
      if (d > 0) s = s//'; a hunter ('//itoa(d)//'/7)'
      if (awe(i,j) > 0) s = s//'; reverence eases its upkeep'
      if (awe(i,j) < 0) s = s//'; in dread, its children mutate more'
   end function why_line

   subroutine people_card(r)
      ! "card": who a people is, whence it came, what it has done and what its rule makes
      integer, intent(in) :: r
      integer :: d, p, k
      character(len=:), allocatable :: fam
      call jo('card')
      call ji('rule', r);  call js('name', people_name(r));  call js('title', people_title(r))
      call js('rs', rule_str(r));  call ji('n', ppl(r)%n);  call ji('peak', ppl(r)%peak)
      call jr('t0', tyear(ppl(r)%t_first));  call ji('parent', notable_parent(r))
      call ji('sire', ppl(r)%parent);  call ji('mate', ppl(r)%mate)
      call ja('ancestry')
      p = ppl(r)%parent;  k = 0
      do while (p >= 0 .and. p <= 65535 .and. k < 6)
         call js('', people_name(p))
         k = k + 1
         p = ppl(p)%parent
      end do
      call jend(']')
      call jr('lam', real(lam(r), dp))
      call ja('flags')
      do k = 0, 11
         if (btest(ppl(r)%flags, k)) call js('', FLAGW(k))
      end do
      call jend(']')
      call js('class', rule_class(r))
      call ji('state', ppl(r)%state);  call jr('hue', real(hue_of(r), dp))
      call jr('named', tyear(ppl(r)%t_named));  call jr('fell', tyear(ppl(r)%t_fell))
      call ji('births', ppl(r)%births);  call ji('deaths', ppl(r)%deaths)
      call ji('kills', ppl(r)%kills);  call ji('lands', ppl(r)%nmass)
      d = -1
      fam = famous_rule(r, d)
      call js('famous', fam)
      if (len_trim(fam) == 0) d = -1
      call ji('fdist', d)
      call jend('}')
   end subroutine people_card

   function rule_class(r) result(cls)
      ! the Oracle's verdict on a rule, as the test tube shows it for seed 1 (remembered)
      integer, intent(in) :: r
      character(len=:), allocatable :: cls
      integer(i1), allocatable :: fr(:,:,:)
      real(sp) :: d(64)
      character(len=16) :: c
      integer :: m
      m = iand(r, 65535)
      if (clsc(m) > 0) then
         cls = trim(cname(clsc(m)))
         return
      end if
      allocate(fr(48,48,64))
      c = ''
      call life_oracle(m, 1, 64, fr, c, d)
      call learn_class(m, c)
      cls = trim(c)
   end function rule_class

   subroutine learn_class(r, c)
      ! remember the Oracle's verdict on rule r
      integer,      intent(in) :: r
      character(*), intent(in) :: c
      integer :: k
      if (len_trim(c) == 0) return
      do k = 1, ncname
         if (cname(k) == c) then
            clsc(r) = int(k, i1)
            return
         end if
      end do
      if (ncname == size(cname)) return
      ncname = ncname + 1
      cname(ncname) = c
      clsc(r) = int(ncname, i1)
   end subroutine learn_class

   subroutine r_oracle(q)
      ! /oracle?rule=&seed=: 64 frames of the pure rule on a 48 x 48 torus (4 steps apart),
      ! its class and its density; rule may be a number or 'B36/S23'
      character(*), intent(in) :: q
      integer, parameter :: NF = 64
      integer(i1), allocatable :: fr(:,:,:)
      real(sp) :: dens(NF)
      character(len=16) :: cls
      character(len=:), allocatable :: raw, t, fam
      integer :: r, seed, i, j, f, k, d
      t = trim(adjustl(qval(q, 'rule')))
      r = RULE_CONWAY
      if (len(t) > 0) r = parse_rule(t)
      if (r == -2) then
         call sb_put(sb, '{"ok":false,"err":'//jstr('"'//t//'" asks for B0 or B1, and '// &
                         'nothing here is born alone')//'}')
         return
      else if (r < 0) then
         call sb_put(sb, '{"ok":false,"err":'//jstr('"'//t//'" is not a rule')//'}')
         return
      end if
      seed = qint(q, 'seed', 1, 0, huge(1))
      allocate(fr(48,48,NF))
      cls = ''
      call life_oracle(r, seed, NF, fr, cls, dens)
      if (seed == 1) call learn_class(r, cls)
      allocate(character(len=48*48*NF) :: raw)
      k = 0
      do f = 1, NF
         do j = 1, 48
            do i = 1, 48
               k = k + 1
               raw(k:k) = achar(iand(int(fr(i,j,f)), 255))
            end do
         end do
      end do
      d = -1
      fam = famous_rule(r, d)
      if (len_trim(fam) == 0) d = -1
      call jo('')
      call jb('ok', .true.);  call ji('rule', r);  call js('rs', rule_str(r))
      call js('name', people_name(r));  call js('title', people_title(r))
      call jr('lam', real(lam(r), dp));  call js('class', cls);  call js('famous', fam)
      call ji('fdist', d);  call ji('seed', seed);  call ji('n', 48);  call ji('nf', NF)
      call jkey('data');  call sb_put(sb, '"')
      call b64_put(sb, raw, len(raw))
      call sb_put(sb, '"')
      call ja('dens')
      do f = 1, NF
         call jr('', real(dens(f), dp))
      end do
      call jend(']')
      call jend('}')
   end subroutine r_oracle

   subroutine r_peoples()
      ! /peoples: every people that has ever been notable, in the order they became so
      integer, allocatable :: o(:)
      integer :: a, b, r
      call roll()
      allocate(o(nros))
      o = roster(1:nros)
      do a = 2, nros
         r = o(a);  b = a - 1
         do while (b >= 1)
            if (ppl(o(b))%t_named <= ppl(r)%t_named) exit
            o(b + 1) = o(b);  b = b - 1
         end do
         o(b + 1) = r
      end do
      call jo('');  call ja('peoples')
      do a = 1, nros
         r = o(a)
         call jo('')
         call ji('rule', r);  call js('name', people_name(r));  call js('title', people_title(r))
         call js('rs', rule_str(r));  call ji('parent', notable_parent(r))
         call jr('t0', tyear(ppl(r)%t_first))
         if (ppl(r)%state == 1) then
            call jr('t1', year_now())
         else
            call jr('t1', tyear(ppl(r)%t_last))
         end if
         call ji('peak', ppl(r)%peak);  call jr('hue', real(hue_of(r), dp))
         call ji('state', ppl(r)%state);  call ji('n', ppl(r)%n)
         call jr('named', tyear(ppl(r)%t_named));  call jr('fell', tyear(ppl(r)%t_fell))
         call ji('mate', ppl(r)%mate);  call ji('flags', ppl(r)%flags)
         call jend('}')
      end do
      call jend(']');  call jend('}')
   end subroutine r_peoples

   subroutine r_society(q)
      ! /society?ph=K: the realms with their markets, wars and treaties, the world market
      ! (prices since market day K), the largest trades, the faiths and the prophecies
      character(*), intent(in) :: q
      integer :: p, a, b, k, f, n, m, since, k0, c
      integer :: ord(MAXFLOWS_SHOWN)
      call jo('')
      call ja('realms')
      do p = 1, npol
         if (pol(p)%state /= 1) cycle
         call jo('')
         call ji('id', p);  call js('name', realm_name(p));  call js('title', realm_title(p))
         call js('gov', trim(GOV_NAME(max(1, min(size(GOV_NAME), pol(p)%gov)))))
         call js('ruler', ruler_name(p));  call ji('people', pol(p)%people)
         if (pol(p)%people >= 0) then
            call js('peopleName', people_name(pol(p)%people))
         else
            call js('peopleName', '')
         end if
         call ji('faith', pol(p)%faith)
         if (pol(p)%faith > 0) then
            call js('faithName', faith_name(pol(p)%faith))
         else
            call js('faithName', '')
         end if
         call place('capital', pol(p)%capital)
         call ji('nreg', pol(p)%nreg);  call ji('pop', pol(p)%pop)
         call jr('wealth', pol(p)%wealth);  call jr('army', pol(p)%army)
         call jr('stability', pol(p)%stability);  call jr('openness', pol(p)%openness)
         call jr('depend', pol(p)%depend);  call jr('shortfall', pol(p)%shortfall)
         call jr('hue', real(pol(p)%hue, dp));  call jr('founded', tyear(pol(p)%t_found))
         call jvec('prices', pol(p)%price);  call jvec('prod', pol(p)%prod)
         call jvec('cons', pol(p)%cons);  call jvec('imp', pol(p)%imp)
         call jvec('expo', pol(p)%expo);  call jvec('stock', pol(p)%stock)
         call jend('}')
      end do
      call jend(']')
      call ja('fallen')                          ! the twenty most recently fallen
      n = 0
      do p = npol, 1, -1
         if (pol(p)%state /= 2 .or. n >= 20) cycle
         n = n + 1
         call jo('');  call ji('id', p);  call js('title', realm_title(p))
         call jr('founded', tyear(pol(p)%t_found));  call jr('fell', tyear(pol(p)%t_fall))
         call jend('}')
      end do
      call jend(']')
      call ja('wars')
      do a = 1, npol
         do b = a + 1, npol
            if (war(a,b) /= 0 .and. pol(a)%state == 1 .and. pol(b)%state == 1) then
               call jo('');  call ji('a', a);  call ji('b', b);  call jend('}')
            end if
         end do
      end do
      call jend(']')
      call pairs('alliances', 1);  call pairs('pacts', 2)
      call ja('sanctions')
      do a = 1, npol
         do b = 1, npol
            if (a /= b .and. sanction(a,b) /= 0 .and. pol(a)%state == 1 .and. &
                pol(b)%state == 1) then
               call jo('');  call ji('by', a);  call ji('on', b);  call jend('}')
            end if
         end do
      end do
      call jend(']')
      call ja('tariffs')                         ! the duties worth a mention
      do a = 1, npol
         do b = 1, npol
            if (a == b .or. pol(a)%state /= 1 .or. pol(b)%state /= 1) cycle
            if (tariff(a,b) < 0.25 .or. .not. trades_with(a, b)) cycle
            call jo('');  call ji('by', a);  call ji('on', b)
            call jr('rate', real(tariff(a,b), dp));  call jend('}')
         end do
      end do
      call jend(']')
      call ja('relations')
      do a = 1, npol
         do b = a + 1, npol
            if (pol(a)%state /= 1 .or. pol(b)%state /= 1) cycle
            if (.not. trades_with(a, b)) cycle
            call jo('');  call ji('a', a);  call ji('b', b)
            call jr('rel', real(rel(a,b), dp));  call jend('}')
         end do
      end do
      call jend(']')
      call jo('market')                          ! the world market and its history
      call ja('goods')
      do k = 1, NGOODS
         call js('', trim(GOOD_NAME(k)))
      end do
      call jend(']')
      call jvec('base', GOOD_BASE);  call jvec('price', wprice);  call jvec('supply', wsupply)
      call jvec('demand', wdemand);  call jvec('trade', wtrade)
      since = qint(q, 'ph', 0, 0, huge(1))
      k0 = max(since + 1, nphist - MHIST + 1, nphist - 399, 1)
      call jo('hist');  call ji('from', k0);  call ji('to', nphist)
      call ja('t')
      do k = k0, nphist
         call jr('', tyear(phist_tick(mod(k - 1, MHIST) + 1)))
      end do
      call jend(']')
      call ja('p')
      do k = k0, nphist
         call ja('')
         do c = 1, NGOODS
            call jr('', real(phist(c, mod(k - 1, MHIST) + 1), dp))
         end do
         call jend(']')
      end do
      call jend(']');  call jend('}');  call jend('}')
      m = min(nflow, MAXFLOWS_SHOWN)              ! the largest trades of the last market day
      call top_flows(ord, m)
      call ja('flows')
      do k = 1, m
         f = ord(k)
         call jo('');  call ji('from', flows(f)%from);  call ji('to', flows(f)%to)
         call ji('good', flows(f)%good);  call jr('vol', real(flows(f)%vol, dp))
         call jr('price', real(flows(f)%price, dp));  call jend('}')
      end do
      call jend(']')
      call ja('faiths')
      do f = 1, nfaith
         if (faiths(f)%state /= 1) cycle
         call jo('');  call ji('id', f);  call js('name', faith_name(f))
         if (faiths(f)%prophet /= 0) then
            call js('prophet', prophet_name(faiths(f)%prophet))
         else
            call js('prophet', '')
         end if
         call ji('followers', faiths(f)%followers);  call ji('nreg', faiths(f)%nreg)
         call jr('devotion', real(faiths(f)%devotion, dp));  call jr('zeal', real(faiths(f)%zeal, dp))
         call jr('openness', real(faiths(f)%openness, dp))
         call jr('ascetic', real(faiths(f)%ascetic, dp))
         call jr('prestige', real(faiths(f)%prestige, dp))
         call ji('kept', faiths(f)%kept);  call ji('failed', faiths(f)%failed)
         call jr('hue', real(faiths(f)%hue, dp));  call place('holy', faiths(f)%holy)
         call jr('founded', tyear(faiths(f)%t_found));  call ji('parent', faiths(f)%parent)
         call ji('state', faiths(f)%state);  call jend('}')
      end do
      call jend(']')
      call ja('prophecies')                      ! all that await, and the last few resolved
      n = 0
      do k = nproph, 1, -1
         if (prophs(k)%state == 0) cycle
         if (prophs(k)%state /= 1) then
            if (n >= 6) cycle
            n = n + 1
         end if
         call jo('');  call ji('id', k);  call ji('faith', prophs(k)%faith)
         call js('text', prophecy_text(k))
         call js('kind', trim(PRWORD(max(1, min(12, prophs(k)%kind)))))
         call jr('due', tyear(prophs(k)%t_due))
         call jr('left', real(prophs(k)%t_due - tick, dp)/TPY)
         call jb('toHand', prophs(k)%to_hand)
         a = 0;  b = 0
         if (prophs(k)%region >= 1 .and. prophs(k)%region <= nregion) then
            a = regs(prophs(k)%region)%cx;  b = regs(prophs(k)%region)%cy
         end if
         call ji('x', a);  call ji('y', b)
         select case (prophs(k)%state)
         case (1);  call js('state', 'awaiting')
         case (2);  call js('state', 'kept')
         case default;  call js('state', 'failed')
         end select
         call jend('}')
      end do
      call jend(']')
      call jend('}')
   contains
      subroutine place(key, r)
         ! a region's label point as {"x":..,"y":..}
         character(*), intent(in) :: key
         integer,      intent(in) :: r
         call jo(key)
         if (r >= 1 .and. r <= nregion) then
            call ji('x', regs(r)%cx);  call ji('y', regs(r)%cy)
         else
            call ji('x', 0);  call ji('y', 0)
         end if
         call jend('}')
      end subroutine place
      subroutine jvec(key, v)
         character(*), intent(in) :: key
         real(dp),     intent(in) :: v(:)
         integer :: i_
         call ja(key)
         do i_ = 1, size(v)
            call jr('', v(i_))
         end do
         call jend(']')
      end subroutine jvec
      subroutine pairs(key, which)
         ! [[a,b],...] of standing realms allied (1) or in a trade pact (2)
         character(*), intent(in) :: key
         integer,      intent(in) :: which
         integer :: a_, b_
         logical :: on
         call ja(key)
         do a_ = 1, npol
            do b_ = a_ + 1, npol
               if (pol(a_)%state /= 1 .or. pol(b_)%state /= 1) cycle
               if (which == 1) then
                  on = ally(a_,b_) /= 0
               else
                  on = pact(a_,b_) /= 0
               end if
               if (on) then
                  call ja('');  call ji('', a_);  call ji('', b_);  call jend(']')
               end if
            end do
         end do
         call jend(']')
      end subroutine pairs
      logical function trades_with(a_, b_)
         ! in contact: neighbours, trading partners, allies or enemies
         integer, intent(in) :: a_, b_
         trades_with = tradevol(a_,b_) + tradevol(b_,a_) > 0 .or. war(a_,b_) /= 0 .or. &
                       ally(a_,b_) /= 0
         if (.not. trades_with) trades_with = borders(a_, b_)
      end function trades_with
      subroutine top_flows(o, nn)
         ! indices of the nn largest flows, largest first
         integer, intent(out) :: o(:)
         integer, intent(in)  :: nn
         integer :: i_, j_, t_
         logical, allocatable :: used(:)
         allocate(used(max(1, nflow)))
         used = .false.
         do i_ = 1, nn
            t_ = 0
            do j_ = 1, nflow
               if (used(j_)) cycle
               if (t_ == 0) then
                  t_ = j_
               else if (flows(j_)%vol*flows(j_)%price > flows(t_)%vol*flows(t_)%price) then
                  t_ = j_
               end if
            end do
            if (t_ == 0) exit
            used(t_) = .true.;  o(i_) = t_
         end do
      end subroutine top_flows
   end subroutine r_society

   subroutine r_log(q)
      ! /log?m=: a message from the page (its errors, its frame rate), printed on stderr
      character(*), intent(in) :: q
      character(len=:), allocatable :: m
      integer :: k
      m = qval(q, 'm')
      m = m(1:min(len(m), 600))
      do k = 1, len(m)
         if (iachar(m(k:k)) < 32) m(k:k) = ' '
      end do
      write(error_unit, '(a)') '   [page] '//m
      flush(error_unit)
      call sb_put(sb, '{"ok":true}')
   end subroutine r_log

   ! ================================================================ the state as JSON

   subroutine state_json(since, ser, regions)
      ! the /state object: the clock, the world now, the Chronicle and the series since the
      ! client last asked, the leading peoples, Titans, plagues, histograms (and the regions)
      integer, intent(in) :: since, ser
      logical, intent(in) :: regions
      call jo('')
      call jl('tick', tick);  call jr('year', year_now());  call jr('season', season_frac())
      call js('seasonName', season_name());  call jb('paused', paused);  call jb('purist', purist)
      call ji('tpf', tpf);  call jb('deep', tpf == 0);  call jr('fps', fps_now)
      call jr('tps', tps_now)
      call jo('world')
      call js('name', world_name);  call ji('nx', NX);  call ji('ny', NY)
      call ji('seed', world_seed);  call ji('gen', web_worlds)
      call jend('}')
      call jo('now')
      call ji('alive', n_alive);  call ji('peoples', n_peoples);  call ji('notable', n_notable)
      call jr('meanT', mean_temp);  call jr('ice', ice_frac);  call jr('ghg', ghg)
      call jr('dust', dust);  call jr('lum', law(kp_lum, 1d0));  call jr('verd', verd_mean)
      call ji('burning', n_burning);  call ji('sick', n_sick);  call ji('locusts', nloc)
      call ji('greg', n_greg);  call jr('phi', vicsek_phi);  call jr('awe', awe_mag)
      call jr('twinT', twin_temp);  call jr('twinIce', twin_ice);  call jr('lamMean', lam_mean())
      call ji('gliders', life_gliders)
      call jend('}')
      call jsep();  call chronicle_json(sb, since)
      call jsep();  call observe_json(sb, ser)
      call top_json()
      call titans_json()
      call strains_json()
      call jsep();  call observe_json_hist(sb)
      if (regions) call regions_json()
      call jo('perf')
      call jr('tickMs', tick_ms);  call jr('frameMs', frame_ms);  call jr('orbitMs', orbit_ms)
      call jr('stateMs', state_ms);  call jl('requests', web_requests)
      call jb('hardened', hardened)
      call jend('}')
      call jend('}')
   end subroutine state_json

   subroutine top_json()
      ! "top": up to 16 notable living peoples, the most numerous first
      integer :: tl(16), m, k, r, a
      call roll()
      m = 0
      do k = 1, nros
         r = roster(k)
         if (ppl(r)%state /= 1 .or. ppl(r)%n <= 0) cycle
         if (m == 16) then
            if (ppl(r)%n <= ppl(tl(16))%n) cycle
         else
            m = m + 1
         end if
         a = m
         do while (a > 1)
            if (ppl(tl(a - 1))%n >= ppl(r)%n) exit
            tl(a) = tl(a - 1);  a = a - 1
         end do
         tl(a) = r
      end do
      call ja('top')
      do k = 1, m
         r = tl(k)
         call jo('')
         call ji('rule', r);  call js('name', people_name(r));  call js('title', people_title(r))
         call js('rs', rule_str(r));  call ji('n', ppl(r)%n);  call ji('peak', ppl(r)%peak)
         call jr('hue', real(hue_of(r), dp));  call jr('cx', real(ppl(r)%cx, dp))
         call jr('cy', real(ppl(r)%cy, dp));  call jr('lam', real(lam(r), dp))
         call jr('pig', real(ppl(r)%pig, dp));  call jr('topt', real(ppl(r)%topt, dp))
         call jr('diet', real(ppl(r)%diet, dp));  call ji('parent', notable_parent(r))
         call jend('}')
      end do
      call jend(']')
   end subroutine top_json

   subroutine titans_json()
      ! "titans": the Old Machines, awake and asleep
      integer :: k
      call ja('titans')
      do k = 1, MAXTITAN
         if (titans(k)%state == 0) cycle
         call jo('')
         call ji('id', k);  call js('name', titan_name(k));  call ji('x', titans(k)%x)
         call ji('y', titans(k)%y);  call ji('state', titans(k)%state)
         call js('rule', titans(k)%rule);  call jl('steps', titans(k)%steps)
         call ji('road', titans(k)%road);  call ji('dir', titans(k)%dir)
         call ji('raised', titans(k)%raised)
         call jend('}')
      end do
      call jend(']')
   end subroutine titans_json

   subroutine strains_json()
      ! "strains": the plagues raging now
      integer :: k, h
      call ja('strains')
      do k = 1, MAXSTRAIN
         if (strains(k)%state /= 1) cycle
         h = strains(k)%host
         call jo('')
         call ji('id', k);  call js('name', strain_name(k));  call ji('n', strains(k)%ninf)
         call ji('host', h)
         if (h >= 0 .and. h <= 65535) then
            call js('hostName', people_name(h))
         else
            call js('hostName', '')
         end if
         call ji('deaths', strains(k)%deaths);  call ji('total', strains(k)%total)
         call ji('peak', strains(k)%peak);  call js('key', rule_str(strains(k)%key))
         call jr('cx', real(strains(k)%cx, dp));  call jr('cy', real(strains(k)%cy, dp))
         call jend('}')
      end do
      call jend(']')
   end subroutine strains_json

   subroutine regions_json()
      ! "regions": the gazetteer, with a spot for each label
      integer :: k
      call ja('regions')
      do k = 1, nregion
         call jo('')
         call ji('id', k);  call js('name', regs(k)%name);  call ji('kind', regs(k)%kind)
         call ji('x', regs(k)%cx);  call ji('y', regs(k)%cy);  call ji('n', regs(k)%n)
         call ji('mass', regs(k)%mass)
         call jend('}')
      end do
      call jend(']')
   end subroutine regions_json

   subroutine params_json(all)
      ! {"params":[...]}: the sliders (every registered law when all)
      logical, intent(in) :: all
      integer :: k
      call jo('');  call ja('params')
      do k = 1, npar
         if (.not. (all .or. par(k)%ui)) cycle
         call jo('')
         call js('key', par(k)%key);  call js('label', par(k)%label)
         call js('group', par(k)%group);  call js('help', par(k)%help);  call jr('v', pv(k))
         call jr('min', par(k)%vmin);  call jr('max', par(k)%vmax);  call jr('dflt', par(k)%dflt)
         call jb('log', par(k)%logs)
         if (all) call jb('ui', par(k)%ui)
         call jend('}')
      end do
      call jend(']');  call jend('}')
   end subroutine params_json

   subroutine roll()
      ! the roll of every people that has ever been notable, rescanned only when it can change
      integer :: sig, r
      integer, allocatable :: t(:)
      sig = ev_total(EV_ARISE) + ev_total(EV_EXTINCT) + ev_total(EV_LAZARUS) + n_notable
      if (sig == nsig .and. ngen == web_worlds .and. abs(tick - nscan) < TPY) return
      nsig = sig;  ngen = web_worlds;  nscan = tick;  nros = 0
      do r = 0, 65535
         if (ppl(r)%state < 1) cycle
         if (nros == size(roster)) then
            allocate(t(2*size(roster)))
            t(1:nros) = roster(1:nros)
            call move_alloc(t, roster)
         end if
         nros = nros + 1
         roster(nros) = r
      end do
   end subroutine roll

   real(dp) function lam_mean()
      ! Langton's lambda, averaged over the living (worked out once per world version)
      integer :: i, j, n
      real(dp) :: s
      if (lam_v /= wver) then
         s = 0;  n = 0
         do j = 1, NY
            do i = 1, NX
               if (alive(i,j) /= 0) then
                  s = s + lam(iand(gene(i,j), 65535));  n = n + 1
               end if
            end do
         end do
         lam_c = s/max(1, n);  lam_v = wver
      end if
      lam_mean = lam_c
   end function lam_mean

   real(sp) function hue_of(r)
      ! a people's hue (SPEC 2.5): its own, else its first ancestor's within 6 steps;
      ! -1 means the neutral warm white of the founders
      integer, intent(in) :: r
      integer :: k, p
      p = r
      do k = 0, 6
         if (p < 0 .or. p > 65535) exit
         if (ppl(p)%hue >= 0) then
            hue_of = ppl(p)%hue
            return
         end if
         p = ppl(p)%parent
      end do
      hue_of = -1
   end function hue_of

   integer function notable_parent(r)
      ! the nearest notable ancestor of a people, -1 if it has none
      integer, intent(in) :: r
      integer :: k, p
      notable_parent = -1
      p = ppl(r)%parent
      do k = 1, 64
         if (p < 0 .or. p > 65535 .or. p == r) return
         if (ppl(p)%state >= 1) then
            notable_parent = p
            return
         end if
         p = ppl(p)%parent
      end do
   end function notable_parent

   ! ================================================================ frames

   subroutine frame_get(view, zoom, cx, cy, hl, k)
      ! the cache slot k that holds this frame of the map, rendered now unless it is cached
      integer, intent(in)  :: view, zoom, cx, cy, hl
      integer, intent(out) :: k
      integer :: w, h
      real(dp) :: t0
      nuse = nuse + 1
      do k = 1, NSLOT
         if (fc(k)%ver == wver .and. fc(k)%view == view .and. fc(k)%zoom == zoom .and. &
             fc(k)%cx == cx .and. fc(k)%cy == cy .and. fc(k)%hl == hl) then
            fc(k)%used = nuse
            return
         end if
      end do
      k = minloc(fc%used, 1)
      t0 = wall()
      call render_map(view, zoom, cx, cy, hl, img, w, h)
      frame_ms = ema(frame_ms, 1d3*(wall() - t0))
      call pack_frame(fc(k), img, w, h)
      fc(k)%view = view;  fc(k)%zoom = zoom;  fc(k)%cx = cx;  fc(k)%cy = cy;  fc(k)%hl = hl
      fc(k)%ver = wver;  fc(k)%used = nuse
   end subroutine frame_get

   subroutine pack_frame(f, pix, w, h)
      ! header and pixels in one buffer: 'RLF1', w, h, tick as little-endian int32, RGBA
      type(frame_t), intent(inout) :: f
      character(*),  intent(in)    :: pix
      integer,       intent(in)    :: w, h
      integer :: n, m
      n = 4*max(0, w)*max(0, h)
      m = min(n, len(pix))
      if (allocated(f%rep)) then
         if (len(f%rep) /= 16 + n) deallocate(f%rep)
      end if
      if (.not. allocated(f%rep)) allocate(character(len=16 + n) :: f%rep)
      f%rep(1:16) = 'RLF1'//le32(w)//le32(h)//le32(int(iand(tick, 2147483647_i8)))
      f%rep(17:16 + m) = pix(1:m)
      if (m < n) f%rep(17 + m:) = repeat(achar(0), n - m)
      f%w = w;  f%h = h
   end subroutine pack_frame

   pure function le32(v) result(s)
      ! four little-endian bytes of a 32-bit integer
      integer, intent(in) :: v
      character(len=4) :: s
      integer(i8) :: u
      integer :: k
      u = iand(int(v, i8), 4294967295_i8)
      do k = 1, 4
         s(k:k) = achar(int(iand(ishft(u, -8*(k - 1)), 255_i8)))
      end do
   end function le32

   subroutine b64_put(b, raw, n)
      ! append the base64 of the first n bytes of raw to a string builder
      type(sbuf_t), intent(inout) :: b
      character(*), intent(in)    :: raw
      integer,      intent(in)    :: n
      character(len=64), parameter :: A = &
         'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
      integer :: k, m, x, nf
      call sb_room(b, 4*((n + 2)/3))
      m = b%n
      nf = n - mod(n, 3)
      do k = 1, nf, 3
         x = ior(ior(ishft(iachar(raw(k:k)), 16), ishft(iachar(raw(k+1:k+1)), 8)), &
                 iachar(raw(k+2:k+2)))
         b%s(m+1:m+1) = A(ishft(x, -18) + 1:ishft(x, -18) + 1)
         b%s(m+2:m+2) = A(iand(ishft(x, -12), 63) + 1:iand(ishft(x, -12), 63) + 1)
         b%s(m+3:m+3) = A(iand(ishft(x, -6), 63) + 1:iand(ishft(x, -6), 63) + 1)
         b%s(m+4:m+4) = A(iand(x, 63) + 1:iand(x, 63) + 1)
         m = m + 4
      end do
      if (mod(n, 3) > 0) then
         x = ishft(iachar(raw(nf+1:nf+1)), 16)
         if (mod(n, 3) == 2) x = ior(x, ishft(iachar(raw(nf+2:nf+2)), 8))
         b%s(m+1:m+1) = A(ishft(x, -18) + 1:ishft(x, -18) + 1)
         b%s(m+2:m+2) = A(iand(ishft(x, -12), 63) + 1:iand(ishft(x, -12), 63) + 1)
         if (mod(n, 3) == 2) then
            b%s(m+3:m+3) = A(iand(ishft(x, -6), 63) + 1:iand(ishft(x, -6), 63) + 1)
         else
            b%s(m+3:m+3) = '='
         end if
         b%s(m+4:m+4) = '='
         m = m + 4
      end if
      b%n = m
   end subroutine b64_put

   subroutine sb_room(b, extra)
      ! room in a string builder for extra more bytes
      type(sbuf_t), intent(inout) :: b
      integer,      intent(in)    :: extra
      character(len=:), allocatable :: old
      if (.not. allocated(b%s)) call sb_put(b, '')
      if (b%n + extra <= len(b%s)) return
      old = b%s(1:b%n)
      deallocate(b%s)
      allocate(character(len=max(2*len(old) + 1024, b%n + extra + 1024)) :: b%s)
      b%s(1:b%n) = old
   end subroutine sb_room

   ! ================================================================ JSON, piece by piece
   ! Each writer puts a comma first unless the reply has just opened an object or an array
   ! or written a key, so that fields can follow one another freely.

   subroutine jsep()
      ! a comma, unless one is not wanted here
      character :: c
      if (sb%n == 0) return
      c = sb%s(sb%n:sb%n)
      if (c /= '{' .and. c /= '[' .and. c /= ',' .and. c /= ':') call sb_put(sb, ',')
   end subroutine jsep

   subroutine jkey(key)
      ! the separator and "key": (just the separator for an array element)
      character(*), intent(in) :: key
      call jsep()
      if (len(key) > 0) call sb_put(sb, '"'//key//'":')
   end subroutine jkey

   subroutine ji(key, v)
      ! an integer field
      character(*), intent(in) :: key
      integer,      intent(in) :: v
      call jkey(key)
      call sb_put(sb, itoa(v))
   end subroutine ji

   subroutine jl(key, v)
      ! a long integer field
      character(*), intent(in) :: key
      integer(i8),  intent(in) :: v
      call jkey(key)
      call sb_put(sb, ltoa(v))
   end subroutine jl

   subroutine jr(key, x)
      ! a real field, at most 6 significant digits
      character(*), intent(in) :: key
      real(dp),     intent(in) :: x
      call jkey(key)
      call sb_put(sb, jnum(x))
   end subroutine jr

   subroutine js(key, t)
      ! a string field
      character(*), intent(in) :: key, t
      call jkey(key)
      call sb_put(sb, jstr(t))
   end subroutine js

   subroutine jb(key, b)
      ! a logical field
      character(*), intent(in) :: key
      logical,      intent(in) :: b
      call jkey(key)
      if (b) then
         call sb_put(sb, 'true')
      else
         call sb_put(sb, 'false')
      end if
   end subroutine jb

   subroutine jo(key)
      ! open an object
      character(*), intent(in) :: key
      call jkey(key)
      call sb_put(sb, '{')
   end subroutine jo

   subroutine ja(key)
      ! open an array
      character(*), intent(in) :: key
      call jkey(key)
      call sb_put(sb, '[')
   end subroutine ja

   subroutine jend(c)
      ! close an object or an array
      character(*), intent(in) :: c
      call sb_put(sb, c)
   end subroutine jend

   ! ================================================================ small helpers

   integer function qint(q, key, dflt, lo, hi)
      ! an integer from the query, clamped to lo..hi (dflt if it is absent or not a number)
      character(*), intent(in) :: q, key
      integer,      intent(in) :: dflt, lo, hi
      real(dp) :: x
      x = qnum(q, key, real(dflt, dp))
      if (.not. ieee_is_finite(x)) x = dflt
      if (abs(x) > 1d15) x = dflt
      qint = nint(max(real(lo, dp), min(real(hi, dp), x)))
   end function qint

   real(dp) function qreal(q, key, dflt)
      ! a finite number from the query (dflt if it is absent, not a number or absurd)
      character(*), intent(in) :: q, key
      real(dp),     intent(in) :: dflt
      qreal = qnum(q, key, dflt)
      if (.not. ieee_is_finite(qreal)) qreal = dflt
      if (abs(qreal) > 1d12) qreal = dflt
   end function qreal

   pure integer function clampi(x, lo, hi)
      ! nint(x) clamped to lo..hi (lo for NaN)
      real(dp), intent(in) :: x
      integer,  intent(in) :: lo, hi
      if (.not. ieee_is_finite(x)) then
         clampi = lo
      else
         clampi = nint(max(real(lo, dp), min(real(hi, dp), x)))
      end if
   end function clampi

   real(dp) function law(k, dflt)
      ! the value of a registered law, or dflt if no module registered it
      integer,  intent(in) :: k
      real(dp), intent(in) :: dflt
      law = dflt
      if (k > 0) law = pv(k)
   end function law

   pure real(dp) function tyear(t)
      ! a tick as a year, -1 for never
      integer(i8), intent(in) :: t
      tyear = -1
      if (t >= 0) tyear = real(t, dp)/TPY
   end function tyear

   real(dp) function ema(old, new)
      ! a running mean of a timing (it starts at the first value)
      real(dp), intent(in) :: old, new
      if (old <= 0) then
         ema = new
      else
         ema = 0.9d0*old + 0.1d0*new
      end if
   end function ema

   function season_name() result(s)
      ! the northern season by twelfths of the year, the equinox opening spring
      character(len=:), allocatable :: s
      s = trim(SEASONS(min(11, int(12*season_frac()))))
   end function season_name

   integer function view_code(name)
      ! a view by its name ('living', 'peoples', ...) or its number; -1 if there is none
      character(*), intent(in) :: name
      character(len=:), allocatable :: t
      integer :: k, ios
      t = lower(trim(adjustl(name)))
      view_code = -1
      if (len(t) == 0) return
      if (verify(t, '0123456789') == 0) then
         read(t, *, iostat=ios) k
         if (ios == 0 .and. k >= 0 .and. k < NVIEWS_ALL) view_code = k
         return
      end if
      do k = 0, NVIEWS_ALL - 1
         if (t == trim(VNAME(k))) view_code = k
      end do
   end function view_code

   function view_name(v) result(s)
      ! the name of a view ('living' for VIEW_LIVING ...)
      integer, intent(in) :: v
      character(len=:), allocatable :: s
      s = 'living'
      if (v >= 0 .and. v < NVIEWS_ALL) s = trim(VNAME(v))
   end function view_name

   integer function parse_rule(t) result(r)
      ! a rule from 'B36/S23' (any case, either order, slash optional) or from its number;
      ! -1 if it is not a rule, -2 if it asks for B0 or B1
      character(*), intent(in) :: t
      character(len=:), allocatable :: u
      integer :: k, d, mode, ios
      u = upper(trim(adjustl(t)))
      r = -1
      if (len(u) == 0) return
      if (verify(u, '0123456789') == 0) then
         read(u, *, iostat=ios) k
         if (ios == 0 .and. k >= 0 .and. k <= 65535) r = k
         return
      end if
      r = 0;  mode = 0
      do k = 1, len(u)
         select case (u(k:k))
         case ('B')
            mode = 1
         case ('S')
            mode = 2
         case ('/', ' ', ',')
         case ('0':'9')
            d = iachar(u(k:k)) - 48
            if (mode == 0) then
               r = -1
               return
            end if
            if (mode == 1 .and. d <= 1) then
               r = -2
               return
            end if
            if (mode == 1 .and. d <= 8) r = ibset(r, d - 2)
            if (mode == 2 .and. d <= 8) r = ibset(r, 7 + d)
            if (d == 9) then
               r = -1
               return
            end if
         case default
            r = -1
            return
         end select
      end do
      if (mode == 0) r = -1
   end function parse_rule

   pure function lower(t) result(s)
      ! t in lower case
      character(*), intent(in) :: t
      character(len=len(t)) :: s
      integer :: k, c
      do k = 1, len(t)
         c = iachar(t(k:k))
         if (c >= 65 .and. c <= 90) c = c + 32
         s(k:k) = achar(c)
      end do
   end function lower

   pure function upper(t) result(s)
      ! t in upper case
      character(*), intent(in) :: t
      character(len=len(t)) :: s
      integer :: k, c
      do k = 1, len(t)
         c = iachar(t(k:k))
         if (c >= 97 .and. c <= 122) c = c - 32
         s(k:k) = achar(c)
      end do
   end function upper

   real(dp) function wall()
      ! seconds on a monotonic clock
      integer(i8) :: c, r
      call system_clock(c, r)
      wall = real(c, dp)/real(max(1_i8, r), dp)
   end function wall

end module rl_web

!=======================================================================
!  real_life -- the main program: the command line; the browser loop,
!  which answers requests between ticks and runs the ticks at the speed
!  asked for under a time budget; the headless Book; the labs.
!=======================================================================
program real_life
   use rl_core
   use rl_web
   use rl_net,       only: net_port
   use rl_observe,   only: observe_print, observe_lab
   use rl_chronicle, only: chronicle_print_new, people_title
   use rl_render,    only: render_snapshot, render_orbit
   use, intrinsic :: iso_c_binding, only: c_int
   implicit none

   interface
      subroutine c_exit(status) bind(c, name='exit')
         import :: c_int
         integer(c_int), value :: status
      end subroutine c_exit
   end interface

   integer, parameter :: ORBIT = -2                 ! --view orbit: the planet from space
   integer :: port = 8080, nx0 = 384, ny0 = 192, seed = 1, years = 400, view = VIEW_LIVING
   logical :: headless = .false., open_it = .false., start_purist = .false.
   character(len=:), allocatable :: snap, frames, lab
   character(len=1024) :: shead(4) = ''              ! the observatory's table header, kept
   integer :: nshead = 0
   character(len=64) :: sets(64) = ''                ! --set key=value, applied once the laws exist
   integer :: nsets = 0

   snap = '';  frames = '';  lab = ''
   call read_args()
   call world_setup(nx0, ny0)
   call apply_sets()
   if (len(lab) > 0) then
      call observe_lab(lab)
      stop
   end if
   call world_new(seed)
   if (start_purist) call world_purist(.true.)
   if (headless) then
      call book()
   else
      call serve()
   end if

contains

   ! ================================================================ the command line

   subroutine read_args()
      ! --port N, --size small|medium|large, --seed N, --headless, --years N, --snap F,
      ! --frames D, --view NAME, --lab NAME, --open, --purist (or written --key=value)
      character(len=:), allocatable :: a, key, val
      integer :: k, n, e
      k = 1
      n = command_argument_count()
      do while (k <= n)
         a = arg(k)
         e = index(a, '=')
         if (e > 2) then
            if (a(1:2) /= '--') e = 0
         end if
         if (e > 2) then
            key = a(1:e-1);  val = a(e+1:)
         else
            key = a;  val = ''
            select case (key)
            case ('--port', '--size', '--seed', '--years', '--snap', '--frames', '--view', '--lab', &
                  '--set')
               if (k == n) call die(key//' wants a value')
               k = k + 1
               val = arg(k)
            end select
         end if
         select case (key)
         case ('--port')
            port = to_int(key, val, 1, 65535)
         case ('--size')
            select case (val)
            case ('small')
               nx0 = 256;  ny0 = 128
            case ('medium')
               nx0 = 384;  ny0 = 192
            case ('large')
               nx0 = 512;  ny0 = 256
            case default
               call die('--size is small, medium or large, not "'//val//'"')
            end select
         case ('--seed')
            seed = to_int(key, val, 0, huge(1))
         case ('--years')
            years = to_int(key, val, 1, 10000000)
            headless = .true.
         case ('--snap')
            snap = val
            headless = .true.
         case ('--frames')
            frames = val
            headless = .true.
         case ('--view')
            if (val == 'orbit') then
               view = ORBIT
            else
               view = view_code(val)
               if (view < 0) call die('there is no view called "'//val//'"')
            end if
         case ('--lab')
            lab = val
         case ('--set')
            if (nsets < size(sets)) then
               nsets = nsets + 1
               sets(nsets) = val
            end if
         case ('--headless')
            headless = .true.
         case ('--open')
            open_it = .true.
         case ('--purist')
            start_purist = .true.
         case ('--help', '-help', '-h')
            call usage()
            stop
         case default
            call die('I do not know "'//a//'"')
         end select
         k = k + 1
      end do
      if (seed == 0) seed = fresh_seed()
   end subroutine read_args

   subroutine apply_sets()
      ! --set key=value: any law of the world, by its name in the registry
      integer :: k, e, ios
      real(dp) :: v
      do k = 1, nsets
         e = index(sets(k), '=')
         ios = 1
         if (e > 1) read(sets(k)(e+1:), *, iostat=ios) v
         if (ios /= 0) call die('--set wants key=value, not "'//trim(sets(k))//'"')
         if (.not. set_param(sets(k)(1:e-1), v)) &
            call die('there is no law called "'//sets(k)(1:e-1)//'"')
      end do
   end subroutine apply_sets

   function arg(k) result(s)
      ! command-line argument k, at its full length
      integer, intent(in) :: k
      character(len=:), allocatable :: s
      integer :: n
      call get_command_argument(k, length=n)
      allocate(character(len=n) :: s)
      if (n > 0) call get_command_argument(k, s)
   end function arg

   integer function to_int(key, val, lo, hi)
      ! a whole number for an option, within lo..hi
      character(*), intent(in) :: key, val
      integer,      intent(in) :: lo, hi
      integer :: ios
      to_int = lo
      ios = 1
      if (len_trim(val) > 0 .and. verify(trim(val), '+-0123456789') == 0) &
         read(val, *, iostat=ios) to_int
      if (ios /= 0 .or. to_int < lo .or. to_int > hi) &
         call die(key//' wants a whole number from '//itoa(lo)//' to '//itoa(hi)// &
                  ', not "'//val//'"')
   end function to_int

   subroutine usage()
      ! the help text
      write(output_unit, '(a)') &
         'REAL LIFE -- the Game of Life, grown up into a world on a doughnut-shaped planet', &
         '', &
         'usage:  real-life [options]', &
         '', &
         '  --port N       serve on 127.0.0.1, on the first free port from N up (8080)', &
         '  --size S       small (256 x 128), medium (384 x 192, the default) or large', &
         '                 (512 x 256)', &
         '  --seed N       the seed of the world (1); 0 picks a new one', &
         '  --purist       begin in the Conway limit: plain B3/S23 on the torus', &
         '  --open         open the page in the default browser', &
         '  --headless     no browser: run the years and print the Book as it is written', &
         '  --years N      years to run headless (400)', &
         '  --snap F.ppm   headless: a picture of the world at the end', &
         '  --frames DIR   headless: a picture every 4 ticks, DIR/frame_00001.ppm ...', &
         '  --view NAME    what --snap and --frames show: living, peoples, climate, water,', &
         '                 frost, verdure, awe, plague, rules, purist, relief or orbit', &
         '  --lab NAME     a validation experiment, then stop: ising, avalanche, fire, noise,', &
         '                 vicsek', &
         '  --set K=V      set any law of the world by name (as the sliders do), e.g.', &
         '                 --set lum=0.8 --set mutation=0.01', &
         '  --help         this'
   end subroutine usage

   subroutine die(msg)
      ! complain and stop with exit status 2
      character(*), intent(in) :: msg
      write(error_unit, '(a)') 'real-life: '//msg, '(real-life --help lists the options)'
      flush(error_unit)
      flush(output_unit)
      call c_exit(2_c_int)
   end subroutine die

   ! ================================================================ the browser

   subroutine serve()
      ! Answer the browser between ticks.  At tpf ticks a frame (30 frames a second) the
      ! ticks run in bursts of at most the tick budget, so that frames keep flowing when the
      ! world is slow; in Deep Time (tpf = 0) they run flat out, with a pause for requests
      ! every 0.25 s.  While paused the loop only listens, waking every 2 ms.
      real(dp), parameter :: FPS = 30, DEEP = 0.25d0
      real(dp) :: t, tprev, tg, debt, t0, burst
      integer(i8) :: f0, k0
      integer :: n
      logical :: got, idle
      if (.not. web_open(port)) &
         call die('no free port from '//itoa(port)//' to '//itoa(port + 40))
      call banner()
      if (open_it) call execute_command_line('(xdg-open http://localhost:'//itoa(net_port)// &
                        '/ || open http://localhost:'//itoa(net_port)//'/) >/dev/null 2>&1 &')
      debt = 0;  idle = .true.
      tprev = wall();  tg = tprev;  f0 = web_frames;  k0 = web_ticks
      do
         n = 0
         do                                       ! all that is waiting (64 at most), then tick
            call web_poll(merge(2, 0, idle .and. n == 0), got)
            if (.not. got) exit
            n = n + 1
            if (n >= 64) exit
         end do
         call world_apply()                       ! the Hand's deeds land even while paused
         t = wall()
         if (.not. paused) sunlon = modulo(sunlon + TWOPI*(t - tprev)/day_length(), TWOPI)
         burst = tick_budget()
         if (paused) then
            debt = 0
         else if (tpf > 0) then
            debt = min(debt + (t - tprev)*FPS*tpf, 2d0*tpf + 1)
            t0 = t
            do while (debt >= 1)
               call world_tick()
               debt = debt - 1
               if (wall() - t0 > burst) exit
            end do
         else
            t0 = t
            do
               call world_tick()
               if (wall() - t0 > DEEP) exit
            end do
            debt = 0
         end if
         tprev = t
         idle = paused .or. (tpf > 0 .and. debt < 1)
         if (t - tg >= 1) then                    ! the gauges, once a second
            fps_now = (web_frames - f0)/(t - tg)
            tps_now = (web_ticks - k0)/(t - tg)
            tg = t;  f0 = web_frames;  k0 = web_ticks
         end if
      end do
   end subroutine serve

   subroutine banner()
      ! the greeting on the terminal
      character(len=:), allocatable :: limit
      limit = ''
      if (purist) limit = ', in the Conway limit'
      write(output_unit, '(a)') '', &
         '   R E A L   L I F E', &
         '   “In the beginning there was B3/S23.”', '', &
         '   the world of '//trim(world_name)//': seed '//itoa(world_seed)//', '// &
         itoa(NX)//' x '//itoa(NY)//' cells'//limit, '', &
         '   open http://localhost:'//itoa(net_port), &
         '   (Ctrl-C ends the world)', ''
      flush(output_unit)
   end subroutine banner

   ! ================================================================ the headless Book

   subroutine book()
      ! run the years as fast as they will go and print the Book as it is written, with the
      ! observatory's line every ten years, and the pictures asked for
      integer(i8) :: nt, k, nfr
      real(dp) :: t0
      character(len=12) :: num
      call book_title()
      if (len(frames) > 0) call execute_command_line('mkdir -p "'//frames//'"')
      nt = int(years, i8)*TPY
      nfr = 0
      t0 = wall()
      call chronicle_print_new(output_unit)
      do k = 1, nt
         call world_tick()
         sunlon = modulo(sunlon + TWOPI/(day_length()*30*2), TWOPI)   ! as at the default speed
         call chronicle_print_new(output_unit)
         if (mod(tick, int(10*TPY, i8)) == 0) call stats()
         if (len(frames) > 0 .and. mod(tick, 4_i8) == 0) then
            nfr = nfr + 1
            if (nfr < 100000) then
               write(num, '(i5.5)') nfr
            else
               write(num, '(i0)') nfr
            end if
            call picture(frames//'/frame_'//trim(num)//'.ppm')
         end if
      end do
      call book_end(wall() - t0, nfr)
   end subroutine book

   subroutine stats()
      ! The observatory's line for the decade, always under its header.  observe_print writes
      ! into a scratch file; the lines without figures that come before the first line of
      ! figures are the header, which is kept and shown again whenever it is left out.
      character(len=1024) :: line(16)
      integer :: u, ios, n, k, nfig
      logical :: fig(16)
      open(newunit=u, status='scratch', form='formatted', action='readwrite')
      call observe_print(u)
      rewind(u)
      n = 0
      do while (n < 16)
         read(u, '(a)', iostat=ios) line(n + 1)
         if (ios /= 0) exit
         n = n + 1
      end do
      close(u)
      if (n == 0) return
      nfig = 0
      do k = 1, n
         fig(k) = count_digits(line(k)) >= 3
         if (fig(k)) nfig = nfig + 1
      end do
      write(output_unit, '(a)') ''
      if (nfig > 0) then
         if (.not. fig(1)) then                    ! a fresh header: keep it
            nshead = 0
            do k = 1, n
               if (fig(k) .or. nshead == size(shead)) exit
               nshead = nshead + 1
               shead(nshead) = line(k)
            end do
         else
            do k = 1, nshead
               write(output_unit, '(a)') trim(shead(k))
            end do
         end if
      end if
      do k = 1, n
         write(output_unit, '(a)') trim(line(k))
      end do
      write(output_unit, '(a)') ''
      flush(output_unit)
   end subroutine stats

   integer function count_digits(t)
      ! how many of the characters of t are digits
      character(*), intent(in) :: t
      integer :: k
      count_digits = 0
      do k = 1, len_trim(t)
         if (t(k:k) >= '0' .and. t(k:k) <= '9') count_digits = count_digits + 1
      end do
   end function count_digits

   subroutine picture(fname)
      ! a PPM of the world in the chosen view (the orbit view is the planet from space)
      character(*), intent(in) :: fname
      character(len=:), allocatable :: b
      integer :: w, h
      if (view == ORBIT) then
         call render_orbit(0d0, 0d0, b, w, h)
         call write_ppm(fname, b, w, h)
      else
         call render_snapshot(fname, view)
      end if
   end subroutine picture

   function vname() result(s)
      ! the chosen view's name
      character(len=:), allocatable :: s
      if (view == ORBIT) then
         s = 'orbit'
      else
         s = view_name(view)
      end if
   end function vname

   subroutine book_title()
      ! the head of the Book
      character(len=:), allocatable :: limit
      limit = ''
      if (purist) limit = ', in the Conway limit'
      write(output_unit, '(a)') '', &
         '  R E A L   L I F E', &
         '  “In the beginning there was B3/S23.”', '', &
         '  THE BOOK OF '//upper(trim(world_name)), &
         '  seed '//itoa(world_seed)//', '//itoa(NX)//' x '//itoa(NY)//' cells, '// &
         commas(years)//' years'//limit, &
         '  '//repeat('=', 96), ''
      flush(output_unit)
   end subroutine book_title

   subroutine book_end(el, nfr)
      ! the last page: the notable peoples, the world as it ends, the pictures and the time
      real(dp),    intent(in) :: el
      integer(i8), intent(in) :: nfr
      integer, allocatable :: o(:)
      integer :: r, n, a, b
      character(len=:), allocatable :: fate, name
      n = count(ppl(:)%state >= 1)
      allocate(o(n))
      n = 0
      do r = 0, 65535
         if (ppl(r)%state < 1) cycle
         n = n + 1
         o(n) = r
         b = n - 1                                ! keep them in the order they arose
         do while (b >= 1)
            if (arose(o(b)) <= arose(r)) exit
            o(b + 1) = o(b)
            b = b - 1
         end do
         o(b + 1) = r
      end do
      write(output_unit, '(a)') '', '  '//repeat('=', 96), &
         '  Here the Book of '//trim(world_name)//' is closed, in the year '// &
         commas(int(year_now()))//'.', ''
      write(output_unit, '(a)') '  THE NOTABLE PEOPLES, in the order they arose', '', &
         '  '//lpad('arose', 8)//'   '//rpad('people', 38)//rpad('rule', 18)//lpad('peak', 9)// &
         '   fate'
      do a = 1, min(n, 60)
         r = o(a)
         if (ppl(r)%state == 1) then
            fate = 'living, '//commas(ppl(r)%n)
         else
            fate = 'fell in '//commas(int(max(0_i8, ppl(r)%t_fell)/TPY))
         end if
         name = trim(people_title(r))
         if (len(name) > 37) name = name(1:36)//'.'
         write(output_unit, '(a)') '  '//lpad(commas(int(arose(r)/TPY)), 8)//'   '// &
            rpad(name, 38)//rpad(rule_str(r), 18)//lpad(commas(ppl(r)%peak), 9)//'   '//fate
      end do
      if (n > 60) write(output_unit, '(a)') '           ... and '//commas(n - 60)//' more'
      if (n == 0) write(output_unit, '(a)') '           (none)'
      write(output_unit, '(a)') '', '  THE WORLD AT THE END', &
         '     '//commas(n_alive)//' living cells of '//commas(n_peoples)//' peoples ('// &
         commas(n_notable)//' notable); mean temperature '//ftoa(mean_temp, 1)//' C; ice '// &
         itoa(nint(100*ice_frac))//'%; verdure '//ftoa(verd_mean, 2), &
         '     star-falls '//itoa(ev_total(EV_METEOR))//', Titans woken '// &
         itoa(ev_total(EV_TITAN))//', roads '//itoa(ev_total(EV_ROAD))//', plagues '// &
         itoa(ev_total(EV_PLAGUE))//', swarms '//itoa(ev_total(EV_LOCUSTS))// &
         ', great fires '//itoa(ev_total(EV_FIRE))//', peoples arisen '// &
         itoa(ev_total(EV_ARISE))//', fallen '//itoa(ev_total(EV_EXTINCT))
      if (len(snap) > 0) then
         call picture(snap)
         write(output_unit, '(a)') '', '  a picture of the world ('//vname()//'): '//snap
      end if
      if (nfr > 0) write(output_unit, '(a)') '  '//commas(int(nfr))//' frames ('// &
         vname()//'): '//frames//'/frame_00001.ppm ...'
      write(output_unit, '(a)') '', '  '//commas(int(year_now()))//' years ('// &
         commas(int(tick))//' ticks) in '//ftoa(el, 1)//' s: '// &
         ftoa(1d3*el/max(1_i8, tick), 2)//' ms a tick, '// &
         commas(nint(tick/max(1d-9, el)))//' ticks a second', ''
      flush(output_unit)
   end subroutine book_end

   integer(i8) function arose(r)
      ! when a people arose: when it was named notable, else when it was first seen
      integer, intent(in) :: r
      arose = ppl(r)%t_named
      if (arose < 0) arose = max(0_i8, ppl(r)%t_first)
   end function arose

   function commas(n) result(s)
      ! 12,345
      integer, intent(in) :: n
      character(len=:), allocatable :: s, d
      integer :: k
      d = itoa(abs(n))
      s = ''
      do k = len(d), 1, -1
         s = d(k:k)//s
         if (mod(len(d) - k + 1, 3) == 0 .and. k > 1) s = ','//s
      end do
      if (n < 0) s = '-'//s
   end function commas

   function lpad(t, w) result(s)
      ! t right-aligned in w columns
      character(*), intent(in) :: t
      integer,      intent(in) :: w
      character(len=:), allocatable :: s
      s = repeat(' ', max(0, w - len(t)))//t
   end function lpad

   function rpad(t, w) result(s)
      ! t left-aligned in w columns
      character(*), intent(in) :: t
      integer,      intent(in) :: w
      character(len=:), allocatable :: s
      s = t//repeat(' ', max(0, w - len(t)))
   end function rpad

   pure function upper(t) result(s)
      ! t in capitals (ASCII letters only)
      character(*), intent(in) :: t
      character(len=len(t)) :: s
      integer :: k, c
      do k = 1, len(t)
         c = iachar(t(k:k))
         if (c >= 97 .and. c <= 122) c = c - 32
         s(k:k) = achar(c)
      end do
   end function upper

end program real_life
